/* Flash cards USMLE: Microbiology (1176 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["microbiology"] = [{"name":"Antimicrobials (Part 1)","cards":[["kq6le516b","Which antibiotics inhibit cell wall synthesis by blocking peptidoglycan cross-linking?","Beta-lactams: penicillins, cephalosporins, carbapenems, monobactams.","Betalactâmicos."],["fm1dyj1bp","Which antibiotics inhibit peptidoglycan synthesis by binding D-Ala-D-Ala?","Glycopeptides: vancomycin, telavancin.","Vancomicina."],["1ifw3ssqi","Which antibiotics bind the 30S ribosomal subunit?","Aminoglycosides (bactericidal) and tetracyclines (bacteriostatic).","Aminoglicosídeos e tetraciclinas."],["1sstwcatn","Which antibiotics bind the 50S ribosomal subunit?","Chloramphenicol, clindamycin, linezolid, macrolides, streptogramins.","Cloranfenicol, clindamicina, linezolida, macrolídeos."],["4urq9y1ea","Which antibiotics inhibit DNA gyrase/topoisomerase?","Fluoroquinolones.","Fluoroquinolonas."],["18vzotg1y","Which antibiotics inhibit folate synthesis?","Sulfonamides (dihydropteroate synthase) and trimethoprim (dihydrofolate reductase).","Sulfas e trimetoprima."],["b6bs4f1o0","Which antibiotic inhibits RNA polymerase?","Rifampin.","Rifampicina."],["mv91lh7aj","Which antibiotic damages DNA via free radicals?","Metronidazole.","Metronidazol."],["1jhfn581e","Which antibiotic disrupts bacterial cell membranes?","Polymyxins (colistin) and daptomycin.","Polimixinas e daptomicina."],["1wl97wt41","Mechanism of penicillin G and V?","Bind penicillin-binding proteins (transpeptidases), blocking peptidoglycan cross-linking; activate autolytic enzymes.","Bloqueiam as transpeptidases."],["1tmoig62h","Uses of penicillin G and V?","Gram-positive organisms (S. pneumoniae, S. pyogenes, Actinomyces), gram-negative cocci (N. meningitidis), spirochetes (syphilis).","Estreptococos e sífilis."],["zk91yhxrl","Adverse effects of penicillins?","Hypersensitivity reactions, direct Coombs-positive hemolytic anemia, drug-induced interstitial nephritis.","Alergia, hemólise, nefrite intersticial."],["1wt8ifpk1","What is the mechanism of resistance to penicillins?","Beta-lactamase cleavage of the beta-lactam ring.","Betalactamase."],["w0bmtj1di","What are penicillinase-sensitive aminopenicillins?","Amoxicillin and ampicillin: wider spectrum (H. influenzae, H. pylori, E. coli, Listeria, Proteus, Salmonella, Shigella, enterococci).","Amoxicilina e ampicilina."],["1yqns6490","Why is amoxicillin given orally rather than ampicillin?","Amoxicillin has better oral bioavailability.","Melhor absorção oral."],["1kb9hf83u","What is the adverse effect of ampicillin in mononucleosis?","Maculopapular rash.","Exantema na mononucleose."],["1sjtir3ry","What are beta-lactamase inhibitors?","Clavulanic acid, sulbactam, tazobactam, avibactam, vaborbactam; added to penicillins/cephalosporins to protect them.","Inibidores de betalactamase."],["1hxcyny16","What are penicillinase-resistant penicillins?","Dicloxacillin, nafcillin, oxacillin: bulky R group blocks beta-lactamase; S. aureus (MSSA), not MRSA.","Oxacilina para MSSA."],["1s2wfki1e","Adverse effect of nafcillin?","Interstitial nephritis.","Nefrite intersticial."],["be431dzw2","What are antipseudomonal penicillins?","Piperacillin and ticarcillin: Pseudomonas and gram-negative rods; given with beta-lactamase inhibitors.","Piperacilina-tazobactam."],["tpl7s6nr0","First-generation cephalosporins and uses?","Cefazolin, cephalexin: gram-positive cocci, Proteus, E. coli, Klebsiella (PEcK); surgical prophylaxis (cefazolin).","Cefazolina na profilaxia cirúrgica."],["zkbnxo1b3","Second-generation cephalosporins and uses?","Cefoxitin, cefaclor, cefuroxime, cefotetan: gram-positive plus H. influenzae, Enterobacter, Neisseria, Serratia, Proteus, E. coli, Klebsiella (HENS PEcK).","Cobertura gram-negativa maior."],["1hqtcn31m","Third-generation cephalosporins and uses?","Ceftriaxone (meningitis, gonorrhea, Lyme), cefpodoxime, cefotaxime; ceftazidime (Pseudomonas).","Ceftriaxona para meningite e gonorreia."],["10kgnod16","Fourth-generation cephalosporin and uses?","Cefepime: gram-negative including Pseudomonas, and gram-positive.","Cefepima cobre Pseudomonas."],["9mwq4a1ui","Fifth-generation cephalosporin and uses?","Ceftaroline: broad gram-positive and gram-negative coverage including MRSA; not Pseudomonas.","Ceftarolina cobre MRSA."],["152alwgvv","Which organisms are not covered by cephalosporins?","Listeria, Atypicals (Chlamydia, Mycoplasma), MRSA (except ceftaroline), Enterococci (LAME).","Listeria, atípicos, MRSA, enterococos."],["scmtqr3on","Adverse effects of cephalosporins?","Hypersensitivity, autoimmune hemolytic anemia, disulfiram-like reaction (cefotetan), vitamin K deficiency; low cross-reactivity with penicillins.","Alergia; reação cruzada baixa."],["19q7enufc","Why does ceftriaxone cause biliary sludge?","Precipitates with calcium in bile (pseudolithiasis); avoid in neonates with IV calcium.","Precipita com cálcio na bile."],["106l69s5g","Mechanism and uses of carbapenems?","Imipenem, meropenem, ertapenem: broad-spectrum beta-lactamase resistant; gram-positive, gram-negative, anaerobes; reserved for serious infections.","Espectro amplo; infecções graves."],["4bprizjkz","Why is imipenem given with cilastatin?","Cilastatin inhibits renal dehydropeptidase I, preventing imipenem inactivation in renal tubules.","Evita degradação renal."],["2mzppy3z2","Adverse effects of carbapenems?","GI distress, rash, CNS toxicity (seizures) at high levels (imipenem).","Convulsões com imipeném."],["dktl50x6z","Which carbapenem does not cover Pseudomonas?","Ertapenem.","Ertapeném."],["16m4gg6z4","Mechanism and uses of aztreonam?","Monobactam binding PBP3; gram-negative rods only (including Pseudomonas); safe in penicillin allergy.","Monobactâmico; seguro na alergia à penicilina."],["1580jcd26","Mechanism of vancomycin?","Inhibits cell wall peptidoglycan formation by binding D-Ala-D-Ala portion of precursors.","Liga D-Ala-D-Ala."],["bg6d6updv","Uses of vancomycin?","Gram-positive only: MRSA, S. epidermidis, sensitive Enterococcus, oral for C. difficile.","MRSA e C. difficile oral."],["1p5k2w017","Adverse effects of vancomycin?","Nephrotoxicity, ototoxicity, thrombophlebitis, DRESS, red man (vancomycin infusion reaction) syndrome.","Nefro e ototoxicidade, síndrome do homem vermelho."],["8zzdmkhe0","How is vancomycin infusion reaction prevented?","Slower infusion rate and antihistamine pretreatment (histamine release, not IgE).","Infusão lenta e anti-histamínico."],["1dzu4xmdb","Mechanism of aminoglycosides?","Bind 30S subunit, inhibiting formation of initiation complex and causing misreading of mRNA; require O2 for uptake.","Ligam a 30S; precisam de oxigênio."],["1c5j2rl1h","Examples and uses of aminoglycosides?","Gentamicin, neomycin, amikacin, tobramycin, streptomycin: severe gram-negative rod infections; synergistic with beta-lactams; neomycin for bowel surgery.","Gentamicina e amicacina."],["1alho0n1v","Adverse effects of aminoglycosides?","Nephrotoxicity, neuromuscular blockade (contraindicated in myasthenia gravis), ototoxicity (with loop diuretics), teratogenicity.","Nefrotoxicidade, ototoxicidade, bloqueio neuromuscular."],["2xdfor1vm","Why are aminoglycosides combined with beta-lactams for enterococcal endocarditis?","Beta-lactams damage the cell wall, increasing aminoglycoside entry (synergy).","Sinergia: o betalactâmico facilita a entrada."],["1g8rjdmlt","Mechanism of tetracyclines?","Bind 30S subunit, preventing attachment of aminoacyl-tRNA; bacteriostatic.","Impedem a ligação do RNAt."],["14imwjwqv","Uses of tetracyclines (doxycycline, minocycline)?","Borrelia, Mycoplasma, Rickettsia, Chlamydia (intracellular), acne, MRSA skin infections, Lyme disease.","Rickettsia, clamídia, Lyme, acne."],["zwgq6z111","Why should tetracyclines not be taken with milk or antacids?","Divalent cations (Ca2+, Mg2+, Fe2+) inhibit absorption.","Cátions reduzem absorção."],["4w5h131ob","Adverse effects of tetracyclines?","GI distress, discoloration of teeth and inhibition of bone growth in children, photosensitivity, pill esophagitis; contraindicated in pregnancy.","Mancha dentes e fotossensibilidade."],["cyjo9q1hn","Which tetracycline is safe in renal failure?","Doxycycline (fecal elimination).","Doxiciclina."],["1rgz59kts","Mechanism and use of tigecycline?","Tetracycline derivative binding 30S; broad-spectrum including MRSA and VRE; GI symptoms.","Derivado de tetraciclina de amplo espectro."],["1llr9okch","Mechanism of chloramphenicol?","Blocks peptidyltransferase at the 50S subunit; bacteriostatic.","Bloqueia a peptidiltransferase."],["44emp5mla","Adverse effects of chloramphenicol?","Dose-dependent anemia, dose-independent aplastic anemia, gray baby syndrome (premature infants lack UDP-glucuronosyltransferase).","Anemia aplástica e síndrome do bebê cinzento."],["m7i90u38v","Mechanism and uses of clindamycin?","Blocks peptide transfer at 50S subunit; anaerobic infections above the diaphragm (aspiration pneumonia, lung abscess), invasive group A strep (toxin suppression), MRSA skin infections.","Anaeróbios acima do diafragma."],["1l9euzv1j","Adverse effect of clindamycin?","Pseudomembranous colitis (C. difficile).","Colite pseudomembranosa."],["1vjdmll4k","Mechanism and uses of linezolid?","Binds 50S, preventing initiation complex formation; MRSA and VRE.","MRSA e VRE."],["15o0lnj2x","Adverse effects of linezolid?","Myelosuppression (thrombocytopenia), peripheral and optic neuropathy, serotonin syndrome (MAO inhibition).","Plaquetopenia e síndrome serotoninérgica."],["1vuxlrh1w","Mechanism of macrolides?","Bind 23S rRNA of the 50S subunit, blocking translocation; bacteriostatic (azithromycin, clarithromycin, erythromycin).","Bloqueiam a translocação."],["w4v6bq158","Uses of macrolides?","Atypical pneumonias (Mycoplasma, Chlamydophila, Legionella), STIs (Chlamydia), pertussis, gram-positive cocci (penicillin allergy), H. pylori, MAC.","Pneumonias atípicas, clamídia, coqueluche."],["fayv8g1q7","Adverse effects of macrolides?","GI motility issues (motilin agonist), arrhythmia (QT prolongation), cholestatic hepatitis, rash, eosinophilia; CYP3A4 inhibition (not azithromycin).","Diarreia, QT longo, hepatite colestática."],["1bkb1o41d","What is the mechanism of macrolide resistance?","Methylation of 23S rRNA binding site.","Metilação do rRNA 23S."],["1p76zr31o","Mechanism and uses of trimethoprim-sulfamethoxazole?","Sequential folate synthesis blockade; UTIs, Shigella, Salmonella, Pneumocystis (treatment and prophylaxis), Toxoplasma prophylaxis, MRSA skin infections, Nocardia.","ITU, Pneumocystis, Nocardia."],["vt4ok7142","Adverse effects of trimethoprim?","Hyperkalemia (ENaC block), megaloblastic anemia, leukopenia, granulocytopenia (prevent with leucovorin).","Hipercalemia e anemia megaloblástica."],["53wfxb1dx","Adverse effects of sulfonamides?","Hypersensitivity, SJS/TEN, hemolysis in G6PD deficiency, nephrotoxicity (tubulointerstitial nephritis), photosensitivity, kernicterus in infants, displaces other drugs from albumin (warfarin).","Stevens-Johnson, hemólise, kernicterus."],["beyw8il90","Mechanism of fluoroquinolones?","Inhibit DNA gyrase (topoisomerase II) and topoisomerase IV; bactericidal (ciprofloxacin, levofloxacin, moxifloxacin).","Inibem a DNA girase."],["11cfp2113","Uses of fluoroquinolones?","Gram-negative rods of urinary and GI tracts (including Pseudomonas: ciprofloxacin, levofloxacin), Legionella, atypicals, gram-positive (respiratory: levofloxacin, moxifloxacin).","Gram-negativos, Pseudomonas, pneumonias."],["5fxkanc27","Adverse effects of fluoroquinolones?","GI upset, superinfections, tendinopathy and tendon rupture (elderly, steroids), QT prolongation, peripheral neuropathy, aortic aneurysm, cartilage damage in children; avoid in pregnancy.","Ruptura de tendão e QT longo."],["3jdg6l18w","Why should fluoroquinolones not be taken with antacids?","Divalent cations decrease absorption.","Cátions reduzem a absorção."],["1a7zn8t1v","Mechanism and uses of daptomycin?","Lipopeptide disrupting cell membranes of gram-positive cocci; MRSA bacteremia, endocarditis, VRE.","Rompe a membrana; MRSA e VRE."],["1bgd6vv11","Why is daptomycin not used for pneumonia?","Inactivated by pulmonary surfactant.","Inativada pelo surfactante."],["1wowmvvzf","Adverse effects of daptomycin?","Myopathy, rhabdomyolysis (monitor CPK), eosinophilic pneumonia.","Miopatia; monitorar CPK."],["q6a25o6pe","Mechanism and uses of metronidazole?","Forms toxic free radicals in bacterial cells; anaerobes below the diaphragm, Giardia, Entamoeba, Trichomonas, Gardnerella, H. pylori, C. difficile.","Anaeróbios abaixo do diafragma e protozoários."],["qpy1y9ep1","Mechanism and uses of polymyxins?","Colistin (polymyxin E) and polymyxin B: cationic detergents disrupting gram-negative cell membranes; multidrug-resistant gram-negatives.","Último recurso contra gram-negativos resistentes."],["funu1j17p","Adverse effects of polymyxins?","Nephrotoxicity, neurotoxicity, respiratory failure.","Nefro e neurotoxicidade."],["1kgaln317","Mechanism and uses of nitrofurantoin?","Damages bacterial DNA via reactive intermediates; uncomplicated cystitis (concentrates in urine).","Cistite não complicada."],["1mphrllr3","Adverse effects of nitrofurantoin?","Pulmonary fibrosis, peripheral neuropathy, hemolysis in G6PD deficiency; avoid if low GFR.","Fibrose pulmonar e neuropatia."],["1blfh43jm","Mechanism and use of fosfomycin?","Inhibits MurA (early cell wall synthesis); single-dose uncomplicated cystitis.","Dose única para cistite."],["1qpk12b1i","Which antibiotics are bactericidal?","Penicillins, cephalosporins, vancomycin, aminoglycosides, fluoroquinolones, metronidazole, daptomycin.","Betalactâmicos, vancomicina, aminoglicosídeos, quinolonas."],["1u8vcd31h","Which antibiotics are bacteriostatic?","Tetracyclines, macrolides, clindamycin, chloramphenicol, linezolid (mostly), sulfonamides.","Tetraciclinas, macrolídeos, clindamicina."],["4tdt531va","Which antibiotics are safe in pregnancy?","Penicillins, cephalosporins, azithromycin, erythromycin (not estolate), clindamycin, nitrofurantoin (not near term).","Penicilinas, cefalosporinas, azitromicina."],["ls88ni3ae","Which antibiotics are contraindicated in pregnancy?","Sulfonamides (kernicterus), aminoglycosides (ototoxicity), fluoroquinolones (cartilage), clarithromycin, tetracyclines (teeth/bone), chloramphenicol (gray baby). SAFE Children Take Really Good Care.","Sulfas, aminoglicosídeos, quinolonas, tetraciclinas."],["15tkbzk1t","Which antibiotics require dose adjustment in renal failure?","Most beta-lactams, vancomycin, aminoglycosides, fluoroquinolones (except moxifloxacin), TMP-SMX.","Vancomicina e aminoglicosídeos."],["tsl7ysozr","Which antibiotics do not require renal adjustment?","Ceftriaxone, doxycycline, clindamycin, linezolid, moxifloxacin, azithromycin, metronidazole (mostly), nafcillin.","Ceftriaxona, doxiciclina, clindamicina."],["o9aste13z","Which antibiotics cause QT prolongation?","Macrolides and fluoroquinolones (also azoles).","Macrolídeos e quinolonas."],["9wn2d31ri","Which antibiotics cause disulfiram-like reactions?","Metronidazole, cefotetan, cefoperazone, griseofulvin, procarbazine, first-gen sulfonylureas.","Metronidazol e algumas cefalosporinas."],["6enk9oepx","Which antibiotics cause photosensitivity?","Sulfonamides, tetracyclines, fluoroquinolones.","Sulfas, tetraciclinas, quinolonas."],["1vubaim13","Which antibiotics cause nephrotoxicity?","Aminoglycosides, vancomycin, polymyxins, amphotericin B (antifungal), cidofovir, foscarnet.","Aminoglicosídeos e vancomicina."],["1l3lthg1x","Which antibiotics cause ototoxicity?","Aminoglycosides, vancomycin, loop diuretics (non-antibiotic), cisplatin.","Aminoglicosídeos e vancomicina."],["1vpr9l2pk","Which antibiotics are CYP450 inhibitors?","Macrolides (except azithromycin), ciprofloxacin, isoniazid, sulfonamides, azoles.","Macrolídeos, ciprofloxacino, azóis."],["1bz46ml18","Which antibiotic is a CYP450 inducer?","Rifampin (also rifabutin less).","Rifampicina."],["qa0h3b13e","Which antibiotic is used for MRSA bacteremia?","Vancomycin or daptomycin.","Vancomicina ou daptomicina."],["1fma6xakp","Which antibiotic is used for MRSA pneumonia?","Vancomycin or linezolid (not daptomycin).","Vancomicina ou linezolida."],["xpp5tf105","Which oral antibiotics treat community MRSA skin infections?","TMP-SMX, doxycycline, clindamycin, linezolid.","Sulfa, doxiciclina, clindamicina."],["svma081gy","Which antibiotic is used for VRE?","Linezolid or daptomycin (also tigecycline).","Linezolida ou daptomicina."],["1ltpnbrhg","Which antibiotics cover Pseudomonas?","Piperacillin-tazobactam, ceftazidime, cefepime, carbapenems (not ertapenem), aztreonam, ciprofloxacin, levofloxacin, aminoglycosides, colistin.","Piperacilina, cefepima, carbapenêmicos."],["1hdu5831p","Which antibiotics cover anaerobes?","Metronidazole, clindamycin, carbapenems, beta-lactam/beta-lactamase inhibitor combinations, cefoxitin, moxifloxacin.","Metronidazol e clindamicina."],["139fzndkp","Which antibiotics cover atypicals?","Macrolides, tetracyclines, fluoroquinolones.","Macrolídeos, doxiciclina, quinolonas."],["117s9qh18","What is the empiric outpatient treatment for community-acquired pneumonia in healthy adults?","Amoxicillin, doxycycline, or a macrolide (if local resistance low).","Amoxicilina ou doxiciclina."],["36523d1ge","What is the empiric inpatient treatment for community-acquired pneumonia?","Beta-lactam (ceftriaxone) plus macrolide, or respiratory fluoroquinolone alone.","Ceftriaxona com macrolídeo."],["mto9l117d","What is the treatment of gonorrhea and chlamydia coinfection?","Ceftriaxone IM plus doxycycline.","Ceftriaxona e doxiciclina."],["9vqlanth7","What is the treatment of Lyme disease?","Doxycycline (amoxicillin in children <8 and pregnancy).","Doxiciclina."],["1ktvd7a1f","What is the treatment of syphilis in penicillin-allergic pregnant women?","Desensitize and give penicillin.","Dessensibilizar e dar penicilina."],["hc6hl2ki2","What is the prophylaxis for meningococcal close contacts?","Rifampin, ciprofloxacin, or ceftriaxone.","Rifampicina, ciprofloxacino ou ceftriaxona."],["28hwzux5q","What is the prophylaxis for recurrent cellulitis or rheumatic fever?","Penicillin (benzathine penicillin G for rheumatic fever).","Penicilina benzatina."],["1erp9oj16","What is the prophylaxis for HIV patients with CD4 <200?","TMP-SMX (Pneumocystis).","Sulfametoxazol-trimetoprima."],["17ybwav12","What is the prophylaxis for HIV patients with CD4 <100 and positive Toxoplasma IgG?","TMP-SMX.","Sulfametoxazol-trimetoprima."],["i74mpyqkz","What is the surgical prophylaxis of choice for most procedures?","Cefazolin.","Cefazolina."],["1acwo0s1d","What is the treatment of uncomplicated cystitis?","Nitrofurantoin, TMP-SMX, or fosfomycin.","Nitrofurantoína ou fosfomicina."],["1dcv4nlcp","What is the treatment of pyelonephritis?","Fluoroquinolone or ceftriaxone, depending on severity and resistance.","Quinolona ou ceftriaxona."],["ssycbr1tw","What is the mechanism of beta-lactamase inhibitor resistance by gram-negatives?","ESBLs and carbapenemases; porin mutations; efflux pumps.","ESBL, carbapenemases, bombas de efluxo."],["1llp29dnh","Which antibiotic treats ESBL-producing organisms?","Carbapenems.","Carbapenêmicos."],["dtb5ug1fl","Which antibiotics treat carbapenem-resistant Enterobacteriaceae?","Ceftazidime-avibactam, meropenem-vaborbactam, polymyxins, tigecycline (variable).","Ceftazidima-avibactam."],["11r1hvn9l","What is the mechanism of aminoglycoside resistance?","Bacterial transferase enzymes that inactivate the drug by acetylation, phosphorylation, or adenylation.","Enzimas que inativam o fármaco."],["1685w0zqc","What is the mechanism of tetracycline resistance?","Decreased uptake or increased efflux by plasmid-encoded transport pumps.","Bombas de efluxo."],["1mmtj6z1k","What is the mechanism of fluoroquinolone resistance?","Chromosome-encoded mutations in DNA gyrase, plasmid-mediated resistance, efflux pumps.","Mutação na DNA girase."],["ir2lqj1mt","What is the mechanism of sulfonamide resistance?","Altered enzyme (dihydropteroate synthase), decreased uptake, increased PABA synthesis.","Enzima alterada."],["1f8cxv2wx","What is the mechanism of chloramphenicol resistance?","Plasmid-encoded acetyltransferase inactivating the drug.","Acetiltransferase."],["nov9y01ia","What is the mechanism of linezolid resistance?","Point mutation of ribosomal RNA.","Mutação do RNA ribossômico."],["hcamgzgnw","What is the mechanism of polymyxin resistance?","Modification of lipid A (mcr-1 plasmid).","Modificação do lipídio A."],["1joap4hik","What antibiotic class is used for Clostridium perfringens and toxin-producing group A strep?","Penicillin plus clindamycin (clindamycin suppresses toxin synthesis).","Penicilina com clindamicina."],["1hrff301a","What is the treatment of H. pylori with penicillin allergy?","Bismuth quadruple therapy (PPI, bismuth, metronidazole, tetracycline).","Quádrupla com bismuto."],["1we41pors","What is a Jarisch-Herxheimer reaction associated with?","Treatment of syphilis and other spirochetes (penicillin).","Tratamento da sífilis."],["q5vani71g","Which antibiotic causes gray baby syndrome in premature infants?","Chloramphenicol (immature glucuronidation).","Cloranfenicol."]]},{"name":"Antimicrobials (Part 2)","cards":[["1vxm0q61o","Mechanism of rifampin?","Inhibits DNA-dependent RNA polymerase.","Inibe a RNA polimerase bacteriana."],["ozjb45199","Uses of rifampin?","TB, leprosy (delays dapsone resistance), meningococcal prophylaxis, H. influenzae type b prophylaxis in contacts, MRSA in combination.","Tuberculose, hanseníase, profilaxia de meningite."],["1nkp6cj1w","Adverse effects of rifampin?","Minor hepatotoxicity, drug interactions (CYP450 inducer), orange body fluids (urine, tears, sweat), flu-like symptoms.","Fluidos alaranjados e indução do CYP450."],["ymq6ysvk8","Why is rifampin never used alone?","Rapid development of resistance (RNA polymerase mutation).","Resistência rápida."],["1vf3pza7z","Mnemonic for rifampin's 4 Rs?","RNA polymerase inhibitor, Ramps up microsomal CYP450, Red/orange body fluids, Rapid resistance if used alone.","Os quatro Rs da rifampicina."],["zpytv71bv","Mechanism of rifabutin vs rifampin?","Same mechanism; rifabutin is a weaker CYP450 inducer, preferred in HIV on protease inhibitors.","Rifabutina induz menos CYP450."],["1gspaz0sa","Mechanism of isoniazid?","Decreases synthesis of mycolic acids; requires bacterial catalase-peroxidase (KatG) for activation.","Inibe ácidos micólicos; ativada pela KatG."],["1dctm9zas","Uses of isoniazid?","TB treatment and the only agent used alone historically for latent TB.","Tuberculose ativa e latente."],["evyyjl16k","Adverse effects of isoniazid?","Hepatotoxicity, peripheral neuropathy and sideroblastic anemia (B6 deficiency), drug-induced lupus, P450 inhibition, seizures in overdose.","Hepatotoxicidade e neuropatia por falta de B6."],["n2kr4c1gp","How is isoniazid neuropathy prevented?","Pyridoxine (vitamin B6) supplementation.","Piridoxina."],["wy46zvg8i","Why do slow acetylators have more isoniazid toxicity?","Slower hepatic N-acetylation increases drug levels.","Acetiladores lentos acumulam o fármaco."],["lyxa44hph","Treatment of isoniazid overdose seizures?","Pyridoxine.","Piridoxina."],["176cnsb18","Mechanism of pyrazinamide?","Uncertain; converted to pyrazinoic acid, works best in acidic pH (phagolysosomes).","Atua em pH ácido."],["1scd57qea","Adverse effects of pyrazinamide?","Hyperuricemia (gout), hepatotoxicity.","Ácido úrico alto e hepatotoxicidade."],["3nbq51x2o","Mechanism of ethambutol?","Decreases carbohydrate polymerization of mycobacterial cell wall by blocking arabinosyltransferase.","Bloqueia a arabinosiltransferase."],["1nr60hvdd","Adverse effect of ethambutol?","Optic neuropathy (red-green color blindness, decreased visual acuity).","Neurite óptica; perde visão de cores."],["2cnhap1oq","Mnemonic for ethambutol adverse effect?","Eyethambutol.","Etambutol afeta o olho."],["10f645amv","Which TB drugs are hepatotoxic?","Isoniazid, rifampin, pyrazinamide (ethambutol is not).","Isoniazida, rifampicina e pirazinamida."],["18zma6j18","What is the first-line regimen for drug-susceptible pulmonary TB?","Rifampin, isoniazid, pyrazinamide, ethambutol for 2 months, then rifampin and isoniazid for 4 months.","RIPE por 2 meses e RI por 4 meses."],["1tru5a21y","What is the role of directly observed therapy in TB?","Improves adherence and prevents resistance.","Melhora a adesão."],["1r6d2p1k2","What drugs treat MDR-TB?","Bedaquiline, pretomanid, linezolid (BPaL), fluoroquinolones (moxifloxacin), injectable agents historically.","Bedaquilina, pretomanida e linezolida."],["1rmpy071t","Mechanism and adverse effect of bedaquiline?","Inhibits mycobacterial ATP synthase; QT prolongation.","Inibe ATP sintase; QT longo."],["1tudqjvjn","Mechanism and use of streptomycin?","Aminoglycoside; TB (second line), plague, tularemia.","Peste e tularemia."],["wi2uej1rk","What is the drug of choice for MAC prophylaxis or treatment in HIV?","Azithromycin (prophylaxis historically at CD4 <50; now only if ART not started); treatment with clarithromycin/azithromycin plus ethambutol.","Azitromicina e etambutol."],["1uxd2yqyj","Mechanism and use of dapsone?","Inhibits folate synthesis (like sulfonamides); leprosy, Pneumocystis prophylaxis, dermatitis herpetiformis.","Hanseníase e Pneumocystis."],["1hgf3uvx9","Adverse effects of dapsone?","Hemolysis in G6PD deficiency, methemoglobinemia, agranulocytosis.","Hemólise e metemoglobinemia."],["1johdxtvb","What is time-dependent killing?","Efficacy depends on time above MIC (beta-lactams, vancomycin): frequent dosing or continuous infusion.","Tempo acima da CIM."],["mola1h1xh","What is concentration-dependent killing?","Efficacy depends on peak concentration relative to MIC (aminoglycosides, fluoroquinolones, daptomycin): once-daily high doses.","Pico de concentração."],["1t2pzi118","What is the post-antibiotic effect?","Persistent suppression of bacterial growth after drug levels fall below MIC (aminoglycosides, fluoroquinolones).","Efeito que persiste após a queda do nível."],["k0t0gfsfs","What is the minimum inhibitory concentration (MIC)?","Lowest drug concentration that prevents visible bacterial growth.","Menor concentração que inibe o crescimento."],["fubyqz1sr","What is synergy in antibiotic therapy?","Combined effect greater than the sum (e.g., beta-lactam increases aminoglycoside entry in enterococcal endocarditis).","Efeito combinado maior."],["15ipa0dx2","What is antagonism in antibiotic therapy?","Bacteriostatic drug may reduce efficacy of bactericidal drugs that need active growth (e.g., tetracycline with penicillin).","Um reduz o efeito do outro."],["1ql41bfyl","Which antibiotics achieve good CNS penetration for meningitis?","Ceftriaxone, cefotaxime, cefepime, meropenem, vancomycin (with inflamed meninges), ampicillin, TMP-SMX, metronidazole, rifampin.","Ceftriaxona, meropeném, vancomicina."],["is6h6nr46","Which antibiotics have poor CNS penetration?","First-generation cephalosporins, aminoglycosides, clindamycin, most macrolides.","Cefazolina, aminoglicosídeos, clindamicina."],["593tv717h","What is empiric therapy for bacterial meningitis in neonates?","Ampicillin plus cefotaxime (or gentamicin).","Ampicilina com cefotaxima."],["1lwtvjakn","What is empiric therapy for bacterial meningitis in adults >50 years?","Vancomycin plus ceftriaxone plus ampicillin (Listeria).","Vancomicina, ceftriaxona e ampicilina."],["1ffl6dqta","Why is dexamethasone given in bacterial meningitis?","Reduces neurologic complications (hearing loss) and mortality in pneumococcal meningitis when given before or with first antibiotic dose.","Reduz sequelas na meningite pneumocócica."],["16kq7ro4k","What is empiric therapy for hospital-acquired pneumonia?","Antipseudomonal beta-lactam (piperacillin-tazobactam, cefepime, meropenem) plus MRSA coverage (vancomycin or linezolid) if risk factors.","Antipseudomonas e cobertura de MRSA."],["jtwk4o1m1","What is empiric therapy for sepsis of unknown source?","Broad-spectrum: vancomycin plus antipseudomonal beta-lactam within 1 hour.","Vancomicina e antipseudomonas na primeira hora."],["1r1epbg1b","What is empiric therapy for febrile neutropenia?","Antipseudomonal beta-lactam monotherapy (cefepime, piperacillin-tazobactam, meropenem); add vancomycin if indicated.","Cefepima ou piperacilina-tazobactam."],["1qyfmki1l","What is empiric therapy for intra-abdominal infection?","Coverage of gram-negatives and anaerobes: piperacillin-tazobactam, or ceftriaxone plus metronidazole.","Gram-negativos e anaeróbios."],["16uk2g7ef","What is the treatment of native valve endocarditis due to MSSA?","Nafcillin or oxacillin (or cefazolin).","Oxacilina ou cefazolina."],["1jbd0obqp","What is the treatment of enterococcal endocarditis?","Ampicillin plus ceftriaxone or gentamicin.","Ampicilina com ceftriaxona ou gentamicina."],["1ww8e8hcw","What is the treatment of viridans strep endocarditis?","Penicillin G or ceftriaxone.","Penicilina ou ceftriaxona."],["1qasn6x1d","What is the treatment of cellulitis without purulence?","Cephalexin or dicloxacillin (strep coverage).","Cefalexina."],["1klmsfwcv","What is the treatment of purulent cellulitis or abscess?","Incision and drainage; MRSA coverage (TMP-SMX, doxycycline) if needed.","Drenagem e cobertura de MRSA."],["k1htgi1p5","What is the treatment of diabetic foot infection (moderate)?","Broad coverage: amoxicillin-clavulanate or ampicillin-sulbactam; add MRSA coverage if risk.","Amoxicilina-clavulanato."],["74cympsjw","What is the treatment of animal bites?","Amoxicillin-clavulanate.","Amoxicilina-clavulanato."],["1vx5ry21w","What is the treatment of Rocky Mountain spotted fever in a child?","Doxycycline (benefit outweighs teeth risk).","Doxiciclina mesmo em criança."],["ciqms014h","What is the treatment of pertussis and prophylaxis of contacts?","Azithromycin.","Azitromicina."],["1t2g5o6yp","What is the treatment of Legionella pneumonia?","Azithromycin or levofloxacin.","Azitromicina ou levofloxacino."],["1e6w6z21u","What is the treatment of Mycoplasma pneumonia?","Azithromycin (or doxycycline).","Azitromicina."],["1elabukym","What is the treatment of chlamydia in pregnancy?","Azithromycin (or amoxicillin).","Azitromicina."],["69m4rps69","What is the treatment of trichomoniasis and bacterial vaginosis?","Metronidazole.","Metronidazol."],["soszp16wi","What is the treatment of uncomplicated malaria from P. vivax?","Chloroquine plus primaquine (or tafenoquine) after G6PD testing.","Cloroquina e primaquina."],["4uoe92dnr","What is the treatment of anthrax?","Ciprofloxacin or doxycycline (plus other agents for systemic disease); postexposure prophylaxis with ciprofloxacin or doxycycline.","Ciprofloxacino ou doxiciclina."],["gzx7s1ilw","What is the treatment of plague and tularemia?","Streptomycin or gentamicin (doxycycline or ciprofloxacin alternatives).","Estreptomicina ou gentamicina."],["1h7hs7vle","What is the treatment of brucellosis?","Doxycycline plus rifampin (or streptomycin/gentamicin).","Doxiciclina com rifampicina."],["1bisrm51i","What is the treatment of Q fever?","Doxycycline.","Doxiciclina."],["1r51rs2b4","What is the treatment of leptospirosis?","Doxycycline or penicillin.","Doxiciclina ou penicilina."],["8zsak1ix1","What is the treatment of actinomycosis?","Penicillin.","Penicilina."],["15igtfo15","What is the treatment of nocardiosis?","TMP-SMX.","Sulfametoxazol-trimetoprima."],["wospv11d4","What is the treatment of Whipple disease?","Ceftriaxone then TMP-SMX for a year.","Ceftriaxona e depois sulfa por um ano."],["1t2ifjp1h","What is the treatment of cat-scratch disease?","Usually self-limited; azithromycin for extensive lymphadenopathy.","Autolimitada; azitromicina."],["17vdma513","What is the treatment of bacillary angiomatosis?","Erythromycin or doxycycline.","Eritromicina ou doxiciclina."],["krviylexr","What is the treatment of Pneumocystis pneumonia in sulfa allergy?","Pentamidine, atovaquone, or clindamycin-primaquine, trimethoprim-dapsone.","Pentamidina ou atovaquona."],["ie1rdgu75","What antifungal is preferred for candidemia?","Echinocandin (micafungin, caspofungin).","Equinocandina."],["1isv0lx1o","What antifungal is preferred for invasive aspergillosis?","Voriconazole (or isavuconazole).","Voriconazol."],["1xu478m19","What antifungal is preferred for mucormycosis?","Amphotericin B (liposomal).","Anfotericina lipossomal."],["uw9t5o11m","What antifungal is preferred for onychomycosis?","Oral terbinafine.","Terbinafina."],["13ztss3w8","What antifungal is preferred for tinea capitis?","Oral griseofulvin or terbinafine.","Griseofulvina ou terbinafina."],["rzeub3ha8","What antiviral treats influenza?","Oseltamivir (also baloxavir, zanamivir).","Oseltamivir."],["17o61mk1v","What antiviral treats CMV retinitis?","Ganciclovir or valganciclovir (foscarnet or cidofovir if resistant).","Ganciclovir."],["7qz56dh37","What antiviral treats HSV encephalitis?","IV acyclovir.","Aciclovir venoso."],["fahlnm1b3","What antiviral treats severe RSV in immunocompromised?","Ribavirin (rarely used).","Ribavirina."],["118tduj1k","What antiviral treats hepatitis C genotype-independent?","Sofosbuvir-velpatasvir or glecaprevir-pibrentasvir.","Sofosbuvir-velpatasvir."],["10umqru19","What antiviral treats hepatitis B?","Tenofovir or entecavir.","Tenofovir ou entecavir."],["1vbqmg4z4","What antiparasitic treats strongyloidiasis?","Ivermectin.","Ivermectina."],["1d454gdt9","What antiparasitic treats scabies?","Topical permethrin or oral ivermectin.","Permetrina ou ivermectina."],["1us3lka5i","What antiparasitic treats head lice?","Permethrin, malathion, ivermectin lotion, spinosad.","Permetrina."],["1ksge82oj","What is antibiotic stewardship?","Coordinated efforts to optimize antimicrobial use (right drug, dose, duration) to reduce resistance and adverse effects.","Uso racional de antibióticos."],["mowpe7y7q","What is de-escalation in antibiotic therapy?","Narrowing broad empiric therapy based on culture results.","Estreitar o espectro conforme cultura."],["10qzizso2","Which antibiotics have the highest risk of C. difficile infection?","Clindamycin, fluoroquinolones, broad-spectrum cephalosporins, carbapenems.","Clindamicina e quinolonas."],["1kk900k1h","Which antibiotic causes tendon rupture especially with steroids?","Fluoroquinolones.","Fluoroquinolonas."],["1d9l5x8oh","Which antibiotic causes hearing loss with loop diuretics?","Aminoglycosides.","Aminoglicosídeos."],["a1z8kj1v6","Which antibiotic causes red-green color blindness?","Ethambutol.","Etambutol."],["1dqbthkra","Which antibiotic causes orange urine?","Rifampin.","Rifampicina."],["k0mxjz19t","Which antibiotic causes teeth discoloration in children?","Tetracyclines.","Tetraciclinas."],["gnploc15g","Which antibiotic causes pseudotumor cerebri?","Tetracyclines (minocycline, doxycycline).","Tetraciclinas."],["9wns5d1wh","Which antibiotic causes SJS and kernicterus?","Sulfonamides.","Sulfas."],["kbr5v61fh","Which antibiotic causes pulmonary fibrosis and neuropathy in long-term UTI prophylaxis?","Nitrofurantoin.","Nitrofurantoína."],["1rfwudf5r","Which antibiotic causes thrombocytopenia and serotonin syndrome with SSRIs?","Linezolid.","Linezolida."],["3qrqgezkx","Which antibiotic causes cholestatic hepatitis and infantile pyloric stenosis?","Erythromycin.","Eritromicina."],["153bttt5x","Which antibiotic causes hyperkalemia similar to a potassium-sparing diuretic?","Trimethoprim.","Trimetoprima."],["m4n2seub6","Which antibiotic causes seizures at high doses especially in renal failure?","Imipenem (and cefepime, penicillins).","Imipeném."],["11q0g8b66","Which antibiotic causes elevated CPK?","Daptomycin.","Daptomicina."],["s69gnf1ih","Which antibiotic causes optic and peripheral neuropathy with prolonged use?","Linezolid.","Linezolida."],["bmwevk6pv","Which antibiotic interacts with warfarin to increase INR?","TMP-SMX, metronidazole, fluoroquinolones, macrolides (CYP inhibitors).","Sulfa, metronidazol, quinolonas."],["gsqyovk8e","Which antibiotic decreases the effect of oral contraceptives significantly?","Rifampin (CYP450 induction).","Rifampicina."],["184hb5ye2","Which antibiotics chelate with calcium, iron, and antacids?","Tetracyclines and fluoroquinolones.","Tetraciclinas e quinolonas."],["w7i5wxtzs","Which antibiotic class is preferred for penicillin-allergic patients with gram-negative infections?","Aztreonam (no cross-reactivity, except ceftazidime side chain).","Aztreonam."],["1wnqesx1n","What is the cross-reactivity risk between penicillin and cephalosporins?","Low (about 1-2%), mostly with similar side chains.","Baixa, cerca de 1-2%."],["e2u82cykb","What is the cross-reactivity risk between penicillin and carbapenems?","Very low (<1%).","Muito baixa."],["e3qrdi1am","What is the antibiotic choice for Listeria?","Ampicillin (plus gentamicin in severe cases); TMP-SMX if allergic.","Ampicilina."],["dqtbjl1ku","What is the antibiotic choice for Bacteroides fragilis?","Metronidazole (also carbapenems, piperacillin-tazobactam).","Metronidazol."],["e6e19w17s","What is the antibiotic choice for Treponema pallidum?","Penicillin G.","Penicilina G."],["viy94kk82","What is the antibiotic choice for Rickettsia and Ehrlichia?","Doxycycline.","Doxiciclina."],["po4vzyll6","What is the antibiotic choice for Mycoplasma pneumoniae?","Macrolides.","Macrolídeos."],["dyky3l1f8","What is the antibiotic choice for Salmonella Typhi?","Ceftriaxone or azithromycin (fluoroquinolones if susceptible).","Ceftriaxona ou azitromicina."],["2p1pby1sg","What is the antibiotic choice for Campylobacter (severe)?","Azithromycin.","Azitromicina."],["1xcuqoq11","What is the antibiotic choice for Shigella?","Azithromycin, ciprofloxacin, or ceftriaxone.","Azitromicina ou ciprofloxacino."],["vf85sl1sh","What is the antibiotic choice for cholera?","Doxycycline or azithromycin (plus rehydration).","Doxiciclina e reidratação."],["1m5nnqbf7","What is the antibiotic choice for gonococcal conjunctivitis in a neonate?","Ceftriaxone (cefotaxime if hyperbilirubinemia).","Ceftriaxona."],["1noedfgme","What is the antibiotic choice for chlamydial conjunctivitis or pneumonia in infants?","Oral erythromycin or azithromycin.","Eritromicina ou azitromicina."],["ar4qwbvtn","What is the antibiotic choice for Haemophilus ducreyi?","Azithromycin or ceftriaxone.","Azitromicina ou ceftriaxona."],["debccq14f","What is the antibiotic choice for Helicobacter pylori first-line in high clarithromycin resistance?","Bismuth quadruple therapy.","Quádrupla com bismuto."],["1o0w2l13u","What is the antibiotic choice for prophylaxis after splenectomy in children?","Daily penicillin (or amoxicillin), especially in sickle cell disease until age 5.","Penicilina diária."]]},{"name":"Bacteriology (Part 1)","cards":[["840fcl1fp","What is the function of peptidoglycan?","Gives rigid support and protects against osmotic pressure; sugar backbone with cross-linked peptide side chains.","Dá rigidez à parede."],["yi2szaank","What is the cell wall difference between gram-positive and gram-negative bacteria?","Gram-positive: thick peptidoglycan with lipoteichoic acid. Gram-negative: thin peptidoglycan plus outer membrane with LPS.","Gram+ tem parede grossa; gram- tem membrana externa."],["8gbb7f1kl","What is the function of lipoteichoic acid?","Gram-positive cell wall component that induces TNF-alpha and IL-1.","Induz TNF e IL-1."],["dgh7do18q","What is the function of the outer membrane in gram-negative bacteria?","Contains LPS (endotoxin) and porins; protects against some antibiotics.","Contém LPS e porinas."],["1utdsr71w","What is lipid A?","Toxic component of LPS (endotoxin) that induces TNF and IL-1 via TLR4.","Parte tóxica do LPS."],["1gss0t819","What is the function of the capsule?","Protects against phagocytosis; usually polysaccharide (except Bacillus anthracis, D-glutamate).","Protege contra fagocitose."],["mya4s1bjq","What is the function of the glycocalyx (slime layer)?","Mediates adherence to surfaces, especially foreign surfaces like catheters (biofilm).","Adesão a cateteres; biofilme."],["1cq6u4aur","What is the function of pili (fimbriae)?","Mediate adherence to host cells; sex pilus forms attachment for conjugation.","Adesão e conjugação."],["s61fyobi4","What is the function of flagella?","Motility.","Movimento."],["z4vdhq9l3","What are spores?","Resistant structures formed by some gram-positive rods (Bacillus, Clostridium) when nutrients are limited; resist heat and chemicals; contain dipicolinic acid.","Formas resistentes de Bacillus e Clostridium."],["xys17bebo","How are spores killed?","Autoclaving (steam at 121°C for 15 minutes).","Autoclave."],["1nq4gf9pb","What is a plasmid?","Extrachromosomal DNA that can carry antibiotic resistance and toxin genes.","DNA extra com genes de resistência."],["5anu8ode1","Which bacteria do not Gram stain well?","Mycoplasma (no cell wall), Mycobacteria (mycolic acid), Treponema and Leptospira (too thin), Legionella (intracellular), Rickettsia, Chlamydia, Bartonella, Ehrlichia, Anaplasma. These Little Microbes May Unfortunately Lack Real Color But Are Everywhere.","Mycoplasma, micobactérias, espiroquetas, intracelulares."],["1cdw4wp10","Which stain is used for Chlamydia, Rickettsia, Borrelia, Plasmodium, Trypanosoma?","Giemsa stain.","Giemsa."],["1o4mo2w1k","What is periodic acid-Schiff (PAS) stain used for?","Stains glycogen and mucopolysaccharides; Tropheryma whipplei (Whipple disease).","Doença de Whipple."],["1depqa9ia","What is Ziehl-Neelsen (acid-fast) stain used for?","Mycobacteria, Nocardia (weakly acid fast), Cryptosporidium oocysts.","Micobactérias e Nocardia."],["1ag7vio16","What is India ink stain used for?","Cryptococcus neoformans (capsule; mucicarmine also stains capsule).","Criptococo."],["1weyk74sb","What is silver stain used for?","Fungi (Coccidioides, Pneumocystis), Legionella, Helicobacter pylori, Bartonella.","Fungos, Legionella, H. pylori."],["14jb4t1ct","What is fluorescent antibody stain used for?","Identifying many bacteria and viruses (e.g., Pneumocystis, Treponema).","Identificação por anticorpo fluorescente."],["4bbsex14t","What media is used for H. influenzae?","Chocolate agar with factors V (NAD+) and X (hematin).","Ágar chocolate com fatores V e X."],["14zlds717","What media is used for Neisseria gonorrhoeae and N. meningitidis?","Thayer-Martin agar (vancomycin, colistin, nystatin, trimethoprim inhibit other organisms).","Ágar Thayer-Martin."],["ca40dcw1u","What media is used for Bordetella pertussis?","Bordet-Gengou agar (potato) or Regan-Lowe medium.","Bordet-Gengou."],["1570elb1f","What media is used for Corynebacterium diphtheriae?","Tellurite agar or Löffler medium.","Telurito ou Löffler."],["1jdbl9s1s","What media is used for Mycobacterium tuberculosis?","Löwenstein-Jensen medium, Middlebrook medium, rapid automated broth cultures.","Löwenstein-Jensen."],["fneytj1g2","What media is used for Mycoplasma pneumoniae?","Eaton agar (requires cholesterol).","Ágar de Eaton."],["cyfv8r1ol","What media distinguishes lactose fermenters?","MacConkey agar: lactose fermenters grow as pink colonies.","MacConkey: fermentadores ficam rosa."],["5sjq4hbbp","What is eosin-methylene blue agar used for?","E. coli colonies with green metallic sheen.","E. coli com brilho verde metálico."],["53d10w1cv","What media is used for Legionella?","Buffered charcoal yeast extract agar with iron and cysteine.","Ágar de carvão com ferro e cisteína."],["11uymgx11","What media is used for fungi?","Sabouraud agar.","Ágar Sabouraud."],["127qvkirz","Which organisms are obligate aerobes?","Nocardia, Pseudomonas, Mycobacterium tuberculosis, Bacillus (Nagging Pests Must Breathe).","Nocardia, Pseudomonas, M. tuberculosis."],["1w5a57g1p","Why does reactivation TB favor the lung apices?","Apices have the highest PO2, favoring the obligate aerobe M. tuberculosis.","Ápice tem mais oxigênio."],["1qtad311e","Which organisms are obligate anaerobes?","Clostridium, Bacteroides, Fusobacterium, Actinomyces israelii (Anaerobes Can't Breathe Fresh Air).","Clostridium, Bacteroides, Actinomyces."],["1ccnlfb1k","Why are aminoglycosides ineffective against anaerobes?","They require O2-dependent uptake.","Precisam de oxigênio para entrar."],["1qqt2iqlu","Features of anaerobic infections?","Foul smell (short-chain fatty acids), gas production in tissue, abscesses; part of normal flora.","Odor fétido, gás, abscessos."],["1c7jbgppx","Which bacteria are obligate intracellular?","Rickettsia and Chlamydia (cannot make own ATP). Stay inside (cells) when it is Really Chilly.","Rickettsia e Chlamydia."],["15d93lc1s","Which bacteria are facultative intracellular?","Salmonella, Neisseria, Brucella, Mycobacterium, Listeria, Francisella, Legionella, Yersinia pestis.","Salmonella, Listeria, micobactérias, Legionella."],["13twf4thl","Which bacteria are encapsulated?","Streptococcus pneumoniae, Haemophilus influenzae type b, Neisseria meningitidis, E. coli, Salmonella, Klebsiella, group B Strep (SHiNE SKiS).","Pneumococo, Haemophilus, meningococo."],["1xp786cv9","Which bacteria are urease positive?","Proteus, Cryptococcus, H. pylori, Ureaplasma, Nocardia, Klebsiella, S. epidermidis, S. saprophyticus (Pee CHUNKSS).","Proteus, H. pylori, Klebsiella."],["1xbzeqynf","Why do urease-positive organisms cause struvite stones?","Urease splits urea into ammonia, raising urine pH and precipitating magnesium ammonium phosphate.","Amônia alcaliniza a urina."],["lae40tj7z","Which bacteria are catalase positive?","Nocardia, Pseudomonas, Listeria, Aspergillus, Candida, E. coli, Staphylococci, Serratia, Burkholderia cepacia, H. pylori (Cats Need PLACESS for their Sun Bath and Hair).","Estafilococos, Nocardia, Aspergillus."],["yx1vpl1a2","Which bacteria produce pigments?","Actinomyces israelii (yellow sulfur granules), S. aureus (golden), Pseudomonas aeruginosa (blue-green pyocyanin), Serratia marcescens (red).","S. aureus dourado, Pseudomonas verde-azulado, Serratia vermelha."],["1fjtuzl1c","What is protein A of S. aureus?","Binds Fc region of IgG, preventing opsonization and phagocytosis.","Liga IgG pela Fc."],["1y5s832l9","What is IgA protease?","Cleaves IgA, allowing mucosal colonization; produced by S. pneumoniae, H. influenzae type b, Neisseria (SHiN).","Destrói IgA."],["1e0ez5761","What is M protein of group A strep?","Prevents phagocytosis; shares epitopes with human cardiac myosin (rheumatic fever).","Antifagocitário; mimetiza miosina."],["552of71wt","What are the main differences between exotoxins and endotoxins?","Exotoxins: secreted polypeptides from gram-positive and gram-negative, highly toxic, antigenic (toxoid vaccines), heat labile. Endotoxin: LPS of gram-negative, released on lysis, less potent, heat stable, no toxoid.","Exotoxina é proteína secretada; endotoxina é LPS."],["oeismu1na","What are the effects of endotoxin?","Macrophage activation (IL-1, IL-6, TNF: fever, shock), complement activation (C3a, C5a), tissue factor activation (DIC).","Febre, choque e CIVD."],["br4jh61u6","Which toxins inhibit protein synthesis by inactivating EF-2?","Diphtheria toxin (Corynebacterium diphtheriae) and exotoxin A (Pseudomonas aeruginosa).","Difteria e exotoxina A."],["yj5alk3jp","Which toxins inhibit protein synthesis by inactivating the 60S ribosome?","Shiga toxin (Shigella) and Shiga-like toxin (EHEC).","Toxina Shiga."],["mpjqomlol","How does heat-labile toxin of ETEC cause diarrhea?","Overactivates adenylate cyclase (increased cAMP), increasing Cl- secretion and water efflux.","Aumenta AMPc; diarreia aquosa."],["mvph78138","How does heat-stable toxin of ETEC cause diarrhea?","Overactivates guanylate cyclase (increased cGMP), decreasing NaCl and water reabsorption.","Aumenta GMPc."],["1txgk4ilx","How does anthrax edema toxin work?","Mimics adenylate cyclase (increased cAMP), causing edematous borders of black eschar.","Aumenta AMPc; edema."],["1wanoks1x","How does cholera toxin work?","Overactivates adenylate cyclase by permanently activating Gs, causing rice-water diarrhea.","Ativa Gs; diarreia em água de arroz."],["1rq9tcets","How does pertussis toxin work?","Inhibits Gi, increasing cAMP; causes whooping cough and lymphocytosis.","Inibe Gi; coqueluche."],["o7vowumuy","How does tetanus toxin work?","Cleaves SNARE proteins in Renshaw cells, blocking release of inhibitory neurotransmitters (GABA, glycine): spastic paralysis, trismus, risus sardonicus, opisthotonos.","Bloqueia GABA e glicina; espasmos."],["mlecodc69","How does botulinum toxin work?","Cleaves SNARE proteins, blocking ACh release at the neuromuscular junction: flaccid paralysis, descending weakness, diplopia.","Bloqueia acetilcolina; paralisia flácida."],["1ulp8wcth","Why is infant botulism associated with honey?","Ingested spores germinate in the infant gut and produce toxin (floppy baby).","Esporos no mel germinam no intestino."],["1s6s10k11","How does Clostridium perfringens alpha toxin work?","Phospholipase (lecithinase) that degrades membranes: myonecrosis (gas gangrene) and hemolysis.","Lecitinase; gangrena gasosa."],["1dunt7nje","How does streptolysin O work?","Protein that degrades cell membranes, lysing RBCs (beta-hemolysis); ASO antibodies indicate recent infection.","Hemolisina; anticorpo ASO."],["zepmbf1ut","What are superantigens and which organisms make them?","Toxins binding MHC II and TCR outside the antigen site, causing overwhelming cytokine release: S. aureus TSST-1, S. pyogenes erythrogenic exotoxin A.","Ativam muitas células T; choque tóxico."],["r7xq6ohzw","What is exfoliative toxin?","S. aureus toxin that cleaves desmoglein 1, causing staphylococcal scalded skin syndrome.","Síndrome da pele escaldada."],["15h5vsvhq","What is transformation in bacterial genetics?","Uptake of naked DNA from the environment (S. pneumoniae, H. influenzae type b, Neisseria).","Captura de DNA livre."],["gjebhl13j","What is conjugation in bacterial genetics?","Transfer of plasmid DNA via sex pilus (F+ x F- or Hfr).","Transferência por pilus sexual."],["e6mxfe183","What is transduction in bacterial genetics?","Transfer of DNA by a bacteriophage (generalized or specialized).","Transferência por bacteriófago."],["1prpeuh1y","What is transposition?","Transposon (jumping gene) moves DNA segment within or between plasmids and chromosome; can carry resistance genes (e.g., vanA in enterococci).","Genes saltadores."],["1j5dmxf18","Which toxins are encoded by lysogenic phage conversion?","ShigA-like toxin, Botulinum toxin, Cholera toxin, Diphtheria toxin, Erythrogenic toxin of S. pyogenes (ABCDE).","Toxinas codificadas por fagos."],["oiyz8x9dp","What is the alpha-hemolysis pattern?","Partial hemolysis (green) from hemoglobin oxidation: S. pneumoniae, viridans streptococci.","Hemólise parcial verde."],["uxrqmv1dd","What is the beta-hemolysis pattern?","Complete hemolysis (clear zone): S. aureus, S. pyogenes, S. agalactiae, Listeria.","Hemólise completa."],["nzetkyi0q","What is the gamma-hemolysis pattern?","No hemolysis: Enterococcus, S. gallolyticus.","Sem hemólise."],["3x69dj6iw","How do you differentiate staphylococci from streptococci?","Catalase: staphylococci positive, streptococci negative.","Catalase."],["1h2z8fp19","How do you differentiate S. aureus from other staphylococci?","Coagulase positive.","Coagulase positiva."],["82k5rv15x","How do you differentiate S. epidermidis from S. saprophyticus?","Novobiocin: S. epidermidis sensitive, S. saprophyticus resistant.","Novobiocina."],["18d6p5krx","How do you differentiate S. pneumoniae from viridans streptococci?","Optochin and bile solubility: S. pneumoniae sensitive and bile soluble; viridans resistant and insoluble.","Optoquina e bile."],["1rhbjycpl","How do you differentiate S. pyogenes from S. agalactiae?","Bacitracin: S. pyogenes (group A) sensitive, S. agalactiae (group B) resistant; group B is CAMP positive and hippurate positive.","Bacitracina e teste CAMP."],["1n4z65g1s","How do you identify enterococci?","Grow in 6.5% NaCl and bile esculin positive.","Crescem em sal e hidrolisam esculina."],["4tetta1li","Which gram-positive cocci are in chains vs clusters?","Streptococci in chains; staphylococci in clusters.","Estreptococo em cadeia; estafilococo em cacho."],["ke0702buu","Which gram-negative organisms are cocci?","Neisseria (diplococci) and Moraxella catarrhalis.","Neisseria e Moraxella."],["w70j3ylci","How do you differentiate N. meningitidis from N. gonorrhoeae biochemically?","Meningitidis ferments maltose and glucose; gonorrhoeae ferments glucose only.","Meningococo fermenta maltose."],["b7jo7c10y","Which gram-negative rods are lactose fermenters?","Citrobacter, E. coli, Enterobacter, Klebsiella, Serratia (weak) (Lactose is key).","E. coli, Klebsiella, Enterobacter."],["f8vcix40w","Which gram-negative rods are nonfermenters and oxidase positive?","Pseudomonas.","Pseudomonas."],["o1idmx1or","Which gram-negative rods produce H2S?","Salmonella and Proteus (and Shigella does not).","Salmonella e Proteus."],["dnokq41fe","Which gram-positive rods form spores?","Bacillus and Clostridium.","Bacillus e Clostridium."],["1692d0213","Which gram-positive rods do not form spores?","Corynebacterium, Listeria, and the branching filamentous Nocardia and Actinomyces.","Corynebacterium e Listeria."],["55map511x","What is the morphology of Nocardia and Actinomyces?","Branching filamentous gram-positive rods; Nocardia aerobic and acid-fast; Actinomyces anaerobic and not acid-fast.","Ramificados; Nocardia é álcool-ácido resistente."],["1h0voqs14","What are the spirochetes?","Borrelia, Leptospira, Treponema.","Borrelia, Leptospira, Treponema."],["1jb2kip1n","How are spirochetes visualized?","Dark-field microscopy (Treponema, Leptospira); Borrelia can be seen with Giemsa or Wright stain.","Campo escuro."],["ioarnbynn","What is a biofilm and why does it matter?","Bacterial community embedded in a matrix on surfaces (catheters, prosthetics, teeth), resistant to antibiotics and immunity.","Comunidade resistente em superfícies."],["1ehi1nkb8","What is quorum sensing?","Bacterial cell-density communication regulating virulence and biofilm.","Comunicação bacteriana por densidade."],["mbfo17eas","What is the mechanism of bacterial growth phases?","Lag (adaptation), log (exponential growth), stationary (nutrient depletion, spore formation), death.","Fases lag, log, estacionária e morte."],["1kcgdo1m2","What is the difference between bacteriostatic and bactericidal?","Bacteriostatic inhibits growth; bactericidal kills bacteria.","Inibir crescimento versus matar."],["lqonz1czy","What are type III secretion systems?","Needle-like protein apparatus injecting toxins into host cells (Pseudomonas, Salmonella, Shigella, E. coli).","Injetam toxinas nas células."],["ry26tzl53","Which bacteria have a polysaccharide capsule that is a vaccine target?","S. pneumoniae, H. influenzae type b, N. meningitidis, Salmonella Typhi.","Alvos de vacinas conjugadas."],["19f4x00fb","Which organism has a polypeptide capsule?","Bacillus anthracis (poly-D-glutamate).","Bacillus anthracis."],["1053v4q1s","What is the CAMP test?","Group B strep produces CAMP factor that enlarges the hemolysis zone of S. aureus.","Identifica estreptococo do grupo B."],["1bvc08x18","What is the bile solubility test?","S. pneumoniae lyses in bile; viridans streptococci do not.","Pneumococo se dissolve na bile."],["1xdqyx21a","Which organisms are oxidase positive?","Pseudomonas, Neisseria, Vibrio, Campylobacter, H. pylori, Legionella, Pasteurella.","Pseudomonas, Neisseria, Vibrio."],["1fv5ia258","Which organism grows on blood agar as medusa head colonies?","Bacillus anthracis.","Bacillus anthracis."],["ibyjn413g","Which organism has a 'school of fish' appearance on Gram stain?","Haemophilus ducreyi.","Haemophilus ducreyi."],["1xodydbpq","Which organism has a 'safety pin' bipolar staining?","Yersinia pestis (also Klebsiella granulomatis Donovan bodies).","Yersinia pestis."],["zwx7r2b3l","Which organism forms 'sulfur granules'?","Actinomyces israelii.","Actinomyces."],["anifhd1n7","Which organism has metachromatic (volutin) granules?","Corynebacterium diphtheriae.","Corynebacterium diphtheriae."],["8mz3kwdfg","Which organism shows tumbling motility?","Listeria monocytogenes.","Listeria."],["gkpjvw88e","Which organism shows swarming motility on agar?","Proteus mirabilis.","Proteus."],["1xjtdmc1v","Which organism grows in cold (cold enrichment)?","Listeria monocytogenes and Yersinia enterocolitica.","Listeria e Yersinia."],["1ksp9of18","Which organism has a sweet grape-like odor?","Pseudomonas aeruginosa.","Pseudomonas."],["1hk3q171k","Which organism has a 'Chinese letters' arrangement on Gram stain?","Corynebacterium diphtheriae (club-shaped rods in V or L shapes).","Corynebacterium diphtheriae."],["13r4w3u15","Which organism has a 'fishy' odor with KOH (whiff test)?","Gardnerella vaginalis (bacterial vaginosis).","Gardnerella; teste das aminas."],["elg1fw6wb","What are clue cells?","Vaginal epithelial cells covered with Gardnerella vaginalis.","Células com Gardnerella."],["x735kli4f","What are the normal flora of the skin?","Staphylococcus epidermidis (and Cutibacterium acnes).","S. epidermidis."],["1qtv3o8ux","What is the dominant flora of the nose?","S. epidermidis; S. aureus colonizes some people.","S. epidermidis e S. aureus."],["fwxxy14z4","What is the dominant flora of the oropharynx?","Viridans group streptococci.","Estreptococos viridans."],["5m3e32ih6","What is the dominant flora of the colon?","Bacteroides fragilis > E. coli.","Bacteroides e E. coli."],["eyqmrdaro","What is the dominant flora of the vagina?","Lactobacillus (colonized by E. coli and group B strep).","Lactobacilos."],["1ia2h30o0","What is the dominant flora of dental plaque?","Streptococcus mutans.","Streptococcus mutans."],["7lj7h21qv","What is the dominant flora of newborn gut after vaginal vs cesarean delivery?","Vaginal: vaginal flora (Lactobacillus); C-section: skin flora (S. epidermidis).","Parto normal: lactobacilos; cesárea: pele."],["hvpzlljtw","What is the role of normal flora in preventing infection?","Competes with pathogens (colonization resistance); antibiotics disrupt it (C. difficile, Candida).","Competem com patógenos."],["19gd6kq6o","What is a toxoid?","Inactivated toxin used as a vaccine (tetanus, diphtheria).","Toxina inativada usada em vacina."],["1iktu8pyp","Which bacteria cause disease mainly via exotoxin and are prevented by toxoid vaccines?","Clostridium tetani and Corynebacterium diphtheriae.","Tétano e difteria."],["rqbgnv7fx","What is the mechanism of Shiga toxin causing HUS?","Damages glomerular endothelium, leading to platelet consumption, microangiopathic hemolysis, and renal failure.","Lesa endotélio do glomérulo."],["1mokhdfjr","What is the mechanism of diphtheria toxin?","ADP-ribosylates EF-2, inhibiting protein synthesis: pharyngitis with pseudomembranes, myocarditis.","Inativa EF-2; pseudomembrana."],["10wqb321f","What is the mechanism of Bordetella pertussis adenylate cyclase toxin?","Increases cAMP in phagocytes, impairing function.","Prejudica fagócitos."],["1fxygjyyz","What is the role of leukocidin (Panton-Valentine leukocidin)?","S. aureus toxin destroying leukocytes; associated with CA-MRSA necrotizing infections.","Destrói leucócitos; MRSA comunitário."],["1ac3r0uau","What is coagulase's role?","Converts fibrinogen to fibrin, forming a protective fibrin barrier (S. aureus).","Forma barreira de fibrina."],["16lzr6y16","What is hyaluronidase's role?","Spreading factor that degrades connective tissue (S. pyogenes).","Facilita a disseminação."],["ab0rgq86q","What is streptokinase's role?","Activates plasminogen, dissolving clots and facilitating spread (S. pyogenes).","Dissolve coágulos."],["13vbybmhd","What is DNase's role in streptococcal infections?","Degrades DNA in pus, facilitating spread; anti-DNase B antibodies indicate recent infection.","Degrada DNA do pus."],["slxqbjc60","What are lysogenic vs lytic phage cycles?","Lytic: phage replicates and lyses bacteria. Lysogenic: phage DNA integrates (prophage) and may encode toxins.","Lítico destrói; lisogênico integra."],["33s0z41ok","What is a mutation conferring antibiotic resistance via altered target?","Changes in penicillin-binding proteins (MRSA mecA), ribosomal methylation (macrolides), DNA gyrase mutation (fluoroquinolones).","Alteração do alvo."],["1alhjf8k0","What is beta-lactamase?","Enzyme that hydrolyzes beta-lactam ring, inactivating penicillins and cephalosporins.","Enzima que destrói betalactâmicos."],["cdii4irn0","What are ESBLs and carbapenemases?","Extended-spectrum beta-lactamases hydrolyze most cephalosporins; carbapenemases (KPC, NDM) also hydrolyze carbapenems.","Enzimas de resistência ampla."],["3vhf8i1wk","What is the mechanism of vancomycin resistance in enterococci?","Change of D-Ala-D-Ala to D-Ala-D-Lac.","D-Ala-D-Ala vira D-Ala-D-Lac."],["itwjcfig2","What is the mechanism of MRSA resistance?","Altered penicillin-binding protein (PBP2a) encoded by mecA.","PBP2a pelo gene mecA."]]},{"name":"Bacteriology (Part 2)","cards":[["10of74w1t","What infections does Staphylococcus aureus cause via inflammation?","Skin infections (impetigo, cellulitis, abscesses), organ abscesses, pneumonia (often after influenza), infective endocarditis (tricuspid in IVDU), septic arthritis, osteomyelitis.","Pele, abscessos, pneumonia, endocardite, osteomielite."],["ztpwnpt0j","What infections does S. aureus cause via toxins?","Toxic shock syndrome (TSST-1), scalded skin syndrome (exfoliative toxin), rapid-onset food poisoning (preformed enterotoxin).","Choque tóxico, pele escaldada, intoxicação alimentar."],["1eistoq9z","Features of S. aureus food poisoning?","Nausea and vomiting within 2-6 hours after eating preformed heat-stable enterotoxin (mayonnaise, meats).","Vômitos poucas horas após comer."],["1bf3t78ny","Features of toxic shock syndrome?","Fever, vomiting, diffuse erythroderma with desquamation, hypotension, multiorgan failure; associated with tampons and nasal packing.","Febre, eritrodermia e choque."],["1kxt5fxbk","Most common cause of osteomyelitis overall?","Staphylococcus aureus.","S. aureus."],["1pv5xdyfe","What is MRSA and its treatment?","Methicillin-resistant S. aureus (PBP2a); treated with vancomycin, daptomycin (not lung), linezolid, ceftaroline; TMP-SMX, doxycycline, clindamycin for skin.","Vancomicina, linezolida, daptomicina."],["1pgcji714","What infections does Staphylococcus epidermidis cause?","Infections of prosthetic devices and IV catheters (biofilm); common blood culture contaminant.","Infecção de próteses e cateteres."],["1h1vlcct5","What infections does Staphylococcus saprophyticus cause?","Uncomplicated UTI in sexually active young women (second most common after E. coli).","Infecção urinária em mulheres jovens."],["1gk8rne1d","What infections does Streptococcus pneumoniae cause?","Most common cause of MOPS: Meningitis, Otitis media (children), Pneumonia, Sinusitis.","Meningite, otite, pneumonia, sinusite."],["142mv3npa","Features of pneumococcal pneumonia?","Lobar pneumonia with rusty sputum; associated with alcoholism and asplenia.","Pneumonia lobar com escarro ferruginoso."],["it6wow1tm","Microscopic appearance of S. pneumoniae?","Lancet-shaped gram-positive diplococci; encapsulated; Quellung positive.","Diplococos em lanceta."],["1lzrfpeup","Which vaccines target S. pneumoniae?","Conjugate pneumococcal vaccines (PCV15, PCV20, PCV21) and polysaccharide PPSV23.","Vacinas conjugadas e polissacarídica."],["25vm5r14p","What infections do viridans group streptococci cause?","Dental caries (S. mutans), subacute bacterial endocarditis on damaged valves (S. sanguinis makes dextrans that bind fibrin-platelet aggregates).","Cárie e endocardite subaguda."],["1vust6oys","What infections does Streptococcus pyogenes (group A) cause via pyogenic mechanisms?","Pharyngitis, cellulitis, impetigo (honey-crusted lesions), erysipelas.","Faringite, impetigo, erisipela."],["1y87jtq1g","What toxigenic diseases does S. pyogenes cause?","Scarlet fever, toxic shock-like syndrome, necrotizing fasciitis.","Escarlatina e fasceíte necrosante."],["w7x3x317a","What immunologic diseases follow S. pyogenes infection?","Rheumatic fever (after pharyngitis only) and acute poststreptococcal glomerulonephritis (after pharyngitis or impetigo).","Febre reumática e glomerulonefrite."],["3rc3k81cp","Features of scarlet fever?","Blanching sandpaper-like rash sparing the face, strawberry tongue, circumoral pallor, desquamation, after pharyngitis.","Exantema em lixa e língua em framboesa."],["xqpvpkyyh","How is strep pharyngitis diagnosed and treated?","Rapid antigen test or culture; penicillin or amoxicillin (prevents rheumatic fever).","Teste rápido; penicilina."],["1b7hd2b14","What scoring system estimates strep pharyngitis likelihood?","Centor criteria: fever, tonsillar exudates, tender anterior cervical lymphadenopathy, absence of cough (plus age).","Critérios de Centor."],["l96hehgze","What infections does Streptococcus agalactiae (group B) cause?","Neonatal pneumonia, meningitis, and sepsis; also bacteremia in elderly and diabetics.","Sepse e meningite neonatal."],["11mu8cgjv","How is neonatal GBS infection prevented?","Screen pregnant women at 36-37 weeks with rectal and vaginal swabs; intrapartum penicillin if positive.","Rastreio na gestação e penicilina no parto."],["1ru5lqhmb","What infections does Enterococcus cause?","UTIs, biliary tract infections, endocarditis (after GI/GU procedures); VRE is an important nosocomial pathogen.","ITU, vias biliares, endocardite."],["1p3d4s6y9","Treatment of VRE?","Linezolid, daptomycin, tigecycline.","Linezolida ou daptomicina."],["1dy1efhlr","What is Streptococcus gallolyticus associated with?","Bacteremia and endocarditis in patients with colon cancer.","Endocardite e câncer de cólon."],["y1you48za","What is Bacillus anthracis?","Gram-positive, spore-forming rod with polypeptide capsule; causes anthrax.","Bactéria do antraz."],["1b18g5pjs","Features of cutaneous anthrax?","Painless papule surrounded by vesicles, progressing to ulcer with black eschar; edema.","Úlcera indolor com escara negra."],["1vhpzkcjb","Features of pulmonary anthrax (woolsorter's disease)?","Inhalation of spores: flu-like symptoms progressing to fever, pulmonary hemorrhage, widened mediastinum (hemorrhagic mediastinitis), shock.","Mediastino alargado."],["4yho8k1v0","What is Bacillus cereus food poisoning?","Emetic type: reheated rice (fried rice syndrome), preformed toxin, vomiting within 1-5 hours. Diarrheal type: watery diarrhea 8-18 hours.","Arroz reaquecido."],["1isbhdu1w","What is Clostridium tetani's presentation?","Tetanus: spastic paralysis, trismus (lockjaw), risus sardonicus, opisthotonos after puncture wounds.","Tétano: trismo e espasmos."],["1ux4v925n","Prevention and treatment of tetanus?","Tetanus toxoid vaccine; tetanus immune globulin, wound debridement, benzodiazepines, metronidazole.","Vacina, imunoglobulina e desbridamento."],["1v3ll2ayp","What is Clostridium botulinum's presentation in adults?","Symmetric descending flaccid paralysis with diplopia, dysphagia, dysarthria after eating home-canned food (preformed toxin).","Paralisia descendente; conservas caseiras."],["mj2p6o1jk","Treatment of botulism?","Human botulinum antitoxin (or BabyBIG for infants); supportive care.","Antitoxina."],["knmxvu1n1","What is Clostridium perfringens's presentation?","Gas gangrene (myonecrosis with crepitus) and late-onset food poisoning (transient watery diarrhea after reheated meat).","Gangrena gasosa e intoxicação por carne."],["m5p1nu16m","What is Clostridioides difficile's presentation?","Watery diarrhea and pseudomembranous colitis after antibiotics; toxins A (enterotoxin) and B (cytotoxin).","Diarreia e colite pseudomembranosa."],["189i9qdse","What is Corynebacterium diphtheriae's presentation?","Pseudomembranous pharyngitis (grayish-white membrane), bull neck lymphadenopathy, myocarditis, arrhythmias.","Membrana acinzentada e pescoço taurino."],["15hnhkcv1","Treatment and prevention of diphtheria?","Antitoxin plus penicillin or erythromycin; toxoid vaccine (DTaP).","Antitoxina e eritromicina."],["r1h33j1sc","What is Listeria monocytogenes?","Facultative intracellular gram-positive rod; tumbling motility, actin rockets; acquired from unpasteurized dairy, deli meats, transplacental, vaginal.","Leite não pasteurizado e frios."],["1rvtuu31l","Who is at risk for Listeria infection?","Pregnant women (amnionitis, sepsis, spontaneous abortion), neonates (granulomatosis infantiseptica, meningitis), elderly, immunocompromised (meningitis).","Gestantes, recém-nascidos, idosos."],["aovqln4gl","Treatment of Listeria meningitis?","Ampicillin (cephalosporins are ineffective).","Ampicilina."],["a9f16d8eu","What is Nocardia's presentation?","Pulmonary infection in immunocompromised and cutaneous infection after trauma; can spread to CNS (brain abscess).","Pulmão e cérebro em imunossuprimidos."],["1t017bkpf","Treatment of Nocardia vs Actinomyces?","Nocardia: sulfonamides (TMP-SMX). Actinomyces: penicillin. (SNAP).","Nocardia: sulfa; Actinomyces: penicilina."],["nhk2mv19f","What is Actinomyces israelii's presentation?","Oral/facial abscesses that drain through sinus tracts with yellow sulfur granules; normal oral flora; also IUD-associated PID.","Abscessos com grânulos amarelos."],["ghyhs01ml","What are the classic findings of primary tuberculosis?","Ghon complex: Ghon focus (lower lobe or upper part of lower lobe) and hilar lymph node; usually heals with latent infection.","Complexo de Ghon."],["1xzbq6yws","What is secondary (reactivation) tuberculosis?","Reactivation in the lung apex: fibrocaseous cavitary lesions; fever, night sweats, weight loss, hemoptysis.","Cavitação apical."],["1t6pk89ox","What is miliary tuberculosis?","Hematogenous dissemination producing millet-seed lesions in many organs (lungs, liver, spleen, kidneys, meninges).","Disseminação em sementes de painço."],["17uulsm15","Extrapulmonary sites of tuberculosis?","CNS (meningitis, tuberculoma), vertebral body (Pott disease), lymphadenitis (scrofula), renal, GI, adrenal.","Meninges, coluna, linfonodos."],["5s37ax1of","What is Pott disease?","Tuberculous spondylitis (vertebral osteomyelitis).","Tuberculose da coluna."],["1vfz00twj","What is cord factor?","Mycobacterial virulence factor (trehalose dimycolate) that inhibits macrophage maturation and induces TNF.","Fator de virulência do bacilo da TB."],["4psi14i50","What are sulfatides in M. tuberculosis?","Cell wall glycolipids that inhibit phagolysosome fusion.","Impedem a fusão do fagolisossomo."],["wlqzms1jm","What does a positive PPD mean?","Current infection, past exposure, or BCG vaccination; false negatives in immunosuppression.","Infecção atual ou passada, ou BCG."],["xp4gqh8jk","What PPD induration size is positive?","≥5 mm in HIV, recent contacts, immunosuppressed; ≥10 mm in high-risk groups (healthcare workers, IV drug users, recent immigrants); ≥15 mm in low-risk.","5, 10 ou 15 mm conforme o risco."],["gpapev10d","Treatment of latent TB?","Rifamycin-based (rifampin 4 months or isoniazid-rifapentine 3 months) or isoniazid 6-9 months.","Rifampicina 4 meses ou isoniazida."],["1r7ecr1yq","Treatment of active TB?","RIPE: rifampin, isoniazid, pyrazinamide, ethambutol for 2 months, then rifampin and isoniazid for 4 months.","Esquema RIPE."],["w88ikmv95","What is Mycobacterium avium complex?","Disseminated infection in AIDS (CD4 <50): fever, night sweats, weight loss, hepatosplenomegaly; treated with clarithromycin/azithromycin plus ethambutol.","Infecção disseminada em AIDS avançada."],["u9b5sc1a6","What causes leprosy?","Mycobacterium leprae (prefers cool temperatures: skin, nerves, extremities); armadillos are a reservoir in the US.","Mycobacterium leprae."],["ucmy3s1q9","Lepromatous vs tuberculoid leprosy?","Lepromatous: Th2 response, diffuse skin involvement, leonine facies, communicable. Tuberculoid: Th1 response, limited hypoesthetic hairless skin plaques.","Virchowiana difusa; tuberculoide localizada."],["16torjt1y","Treatment of leprosy?","Dapsone and rifampin (tuberculoid); add clofazimine for lepromatous.","Dapsona e rifampicina."],["1jnn1nlc6","What is Mycobacterium marinum?","Skin infection (fish tank granuloma) after exposure to contaminated water; nodular lymphangitis.","Granuloma de aquário."],["qr3vfx1ge","What is Mycobacterium scrofulaceum?","Cervical lymphadenitis in children.","Linfadenite cervical em crianças."],["2d8db1x8q","What causes erysipelas?","Streptococcus pyogenes: well-demarcated raised erythema of the upper dermis and lymphatics.","Estreptococo do grupo A."],["dlp6591ih","What causes impetigo and its appearance?","S. aureus or S. pyogenes: honey-colored crusted lesions (bullous form from S. aureus).","Crostas cor de mel."],["xpmhu11ku","What causes necrotizing fasciitis?","Group A strep (exotoxins), polymicrobial (anaerobes), Clostridium; pain out of proportion, crepitus; surgical emergency.","Dor desproporcional; emergência cirúrgica."],["1t8ldqy1d","What causes cellulitis?","S. pyogenes and S. aureus.","Estreptococo e estafilococo."],["1miisqlnr","What is staphylococcal scalded skin syndrome?","Exfoliative toxin destroys desmoglein 1 in the granulosum layer: widespread sheet-like desquamation, positive Nikolsky sign, in infants and young children; mucosa spared.","Descamação em lençóis; Nikolsky positivo."],["u15q8yzyn","What is the treatment of uncomplicated MSSA infections?","Dicloxacillin, nafcillin, oxacillin, cefazolin.","Oxacilina ou cefazolina."],["14en25w1p","What is the most common cause of acute infective endocarditis on native valves?","Staphylococcus aureus.","S. aureus."],["17lpq461h","What is a common cause of endocarditis in IV drug users affecting the tricuspid valve?","Staphylococcus aureus.","S. aureus."],["14t33fjem","Which organism causes endocarditis with colon cancer?","Streptococcus gallolyticus (bovis).","S. gallolyticus."],["2ydfuw1eq","What is the treatment for Clostridium perfringens gas gangrene?","Surgical debridement, penicillin plus clindamycin, hyperbaric oxygen.","Desbridamento e antibióticos."],["khrk09o6d","Which organism causes erythrasma?","Corynebacterium minutissimum (coral-red fluorescence under Wood lamp).","Corynebacterium minutissimum."],["jpxsbn159","Which gram-positive causes acne?","Cutibacterium acnes (formerly Propionibacterium).","Cutibacterium acnes."],["hnjf3l17k","Which organisms commonly cause infections after prosthetic joint surgery?","S. epidermidis (coagulase-negative staphylococci), S. aureus, Cutibacterium acnes (shoulder).","Estafilococos coagulase negativos."],["va5dl15s7","Which gram-positive causes spontaneous abortion and neonatal meningitis from deli meats?","Listeria monocytogenes.","Listeria."],["12jh2mgt9","Which organism is associated with wool sorters?","Bacillus anthracis.","Bacillus anthracis."],["185skut9o","Which organism is associated with the swimming pool or hot tub folliculitis?","Pseudomonas aeruginosa.","Pseudomonas."],["1szrnsr6h","What causes neonatal conjunctivitis on day 2-5?","Neisseria gonorrhoeae (purulent); prevented with erythromycin ointment.","Gonococo; pomada de eritromicina."],["dvrkgc106","What causes neonatal conjunctivitis on day 5-14?","Chlamydia trachomatis.","Clamídia."],["vkoy7uxgf","What is rheumatic fever's prevention after strep pharyngitis?","Penicillin treatment within 9 days of symptom onset.","Penicilina até 9 dias."],["nz4byn2qr","Does treating strep pharyngitis prevent poststreptococcal glomerulonephritis?","No; antibiotics prevent rheumatic fever but not PSGN.","Não previne a glomerulonefrite."],["c1ycar1pn","What strain types cause PSGN?","Nephritogenic strains of group A strep after pharyngitis or skin infection.","Cepas nefritogênicas."],["1ibh2jy1n","Which organism causes dental caries?","Streptococcus mutans.","Streptococcus mutans."],["3rx2141by","Which organisms cause endocarditis after dental procedures?","Viridans group streptococci.","Estreptococos viridans."],["vc7znb1ju","Which patients need antibiotic prophylaxis before dental procedures?","Prosthetic valves, prior infective endocarditis, certain congenital heart diseases, cardiac transplant with valvulopathy.","Próteses valvares e endocardite prévia."],["1pks5mdnn","Which drug is used for endocarditis prophylaxis?","Amoxicillin (azithromycin, doxycycline, cephalexin if allergic).","Amoxicilina."],["zjy9q3q2c","What is the most common cause of community-acquired pneumonia?","Streptococcus pneumoniae.","Pneumococo."],["11xtecplf","What is the most common cause of bacterial meningitis in adults?","Streptococcus pneumoniae.","Pneumococo."],["dsvkjw1v8","What is the most common cause of bacterial meningitis in newborns?","Group B strep, E. coli, Listeria.","Estreptococo do grupo B, E. coli e Listeria."],["1ghiw483j","What is the empiric treatment for meningitis in adults?","Ceftriaxone plus vancomycin (add ampicillin if >50 or immunocompromised); dexamethasone.","Ceftriaxona e vancomicina."],["nn4ycvptu","What is the CSF profile in bacterial meningitis?","High opening pressure, high neutrophils, high protein, low glucose.","Neutrófilos, proteína alta e glicose baixa."],["cdt5rc1rb","What is the CSF profile in viral meningitis?","Normal or slightly high pressure, lymphocytes, normal or slightly high protein, normal glucose.","Linfócitos e glicose normal."],["64zc91zn7","What is the CSF profile in tuberculous or fungal meningitis?","High pressure, lymphocytes, high protein, low glucose.","Linfócitos, proteína alta, glicose baixa."],["1nrs6odmq","Which organism causes pneumonia with lung abscess in alcoholics?","Klebsiella pneumoniae and anaerobes (aspiration).","Klebsiella e anaeróbios."],["1ejyg5p1h","Which organism causes postinfluenza pneumonia?","Staphylococcus aureus (also S. pneumoniae, H. influenzae).","S. aureus."],["15qd0ig13","What is the classic presentation of Mycoplasma pneumonia?","Atypical walking pneumonia in young adults (military, dorms): insidious, dry cough, x-ray looks worse than patient.","Pneumonia atípica em jovens."],["128b686hj","Why is Mycoplasma not treated with beta-lactams?","No cell wall; treated with macrolides, doxycycline, or fluoroquinolones.","Sem parede celular."],["1093qpbq9","What test is associated with Mycoplasma infection?","Cold agglutinins (IgM), causing cold AIHA.","Crioaglutininas."],["ndcpe4sl3","What does Mycoplasma's membrane contain?","Cholesterol (sterols); requires cholesterol for growth.","Colesterol."],["e2bvam12a","Which organism causes atypical pneumonia from contaminated water sources (air conditioners)?","Legionella pneumophila.","Legionella."],["99av6yyib","How is Legionella diagnosed?","Urinary antigen test; culture on charcoal yeast extract with iron and cysteine.","Antígeno urinário."],["1ail39ck8","What are features of Legionnaires disease?","Severe pneumonia, high fever, GI symptoms (diarrhea), hyponatremia, confusion.","Pneumonia com diarreia e hiponatremia."],["lddwo618b","What is Pontiac fever?","Mild flu-like illness caused by Legionella without pneumonia.","Forma leve semelhante à gripe."],["w1wcms19o","Which organism causes pneumonia in cystic fibrosis and burn patients?","Pseudomonas aeruginosa.","Pseudomonas."],["1jwva721f","Which organism causes pneumonia with currant jelly sputum?","Klebsiella pneumoniae.","Klebsiella."],["1y2o9zo1a","Which organism causes pneumonia in COPD patients with gram-negative coccobacilli?","Haemophilus influenzae (and Moraxella catarrhalis).","Haemophilus influenzae."],["12f648fbz","Which organism causes walking pneumonia with erythema multiforme?","Mycoplasma pneumoniae.","Mycoplasma."],["1eonsys1o","Which organism causes atypical pneumonia after exposure to birds?","Chlamydophila psittaci (psittacosis).","Chlamydia psittaci."],["n0jfmy1y3","Which organism causes atypical pneumonia after exposure to sheep or cattle birth products?","Coxiella burnetii (Q fever).","Coxiella burnetii."],["u9uqcd135","Which organism causes pneumonia in a patient with recent travel to the US Southwest?","Coccidioides immitis.","Coccidioides."],["1u3xdbt14","What is the presentation of a lung abscess from aspiration?","Foul-smelling sputum in patients with impaired consciousness (alcoholism, seizures); right lower lobe; anaerobes.","Escarro fétido; lobo inferior direito."],["4af5ppxm2","Treatment of aspiration pneumonia with abscess?","Clindamycin or ampicillin-sulbactam (anaerobic coverage).","Clindamicina ou ampicilina-sulbactam."],["srm22hv2m","What gram-positive organism is associated with prosthetic shoulder infection?","Cutibacterium acnes.","Cutibacterium acnes."],["df6zjf108","What gram-positive rod causes infection in neonates through the placenta with microabscesses?","Listeria (granulomatosis infantiseptica).","Listeria."],["1bncckc19","Which toxin-mediated illness causes rapid vomiting after eating potato salad at a picnic?","S. aureus enterotoxin.","Enterotoxina do S. aureus."],["a0fs2nw52","What is the treatment for C. difficile in severe disease?","Oral vancomycin (plus IV metronidazole if fulminant).","Vancomicina oral."],["nf3zsqc9e","Which drug class predisposes most to C. difficile?","Clindamycin, fluoroquinolones, cephalosporins, penicillins (and PPIs).","Clindamicina e fluoroquinolonas."],["1ye5pgqg4","Which organism causes subacute endocarditis with negative cultures in a patient with cats?","Bartonella henselae.","Bartonella."],["1qslqd81k","Which organism causes endocarditis with negative cultures and farm animal exposure?","Coxiella burnetii.","Coxiella."],["1jt40hsqj","What is the BCG vaccine?","Attenuated live Mycobacterium bovis; used in high TB prevalence countries; can cause false-positive PPD.","M. bovis atenuado."],["bq1nvq1ng","Which drug-resistant TB definition is MDR-TB?","Resistant to isoniazid and rifampin.","Resistente a isoniazida e rifampicina."],["1e28ocx1g","What test rapidly detects TB and rifampin resistance?","Nucleic acid amplification (GeneXpert MTB/RIF).","Teste molecular GeneXpert."],["jt7eft10w","How many sputum samples are used for AFB smear?","Three sputum samples (including an early morning sample).","Três amostras de escarro."],["1woqhnb1i","What is the classic chest x-ray finding of primary TB?","Lower or middle lobe infiltrate with hilar lymphadenopathy (Ranke complex when calcified).","Infiltrado inferior com adenopatia hilar."],["3g2jri9z0","What is the classic presentation of tuberculous meningitis?","Subacute headache, fever, cranial nerve palsies (basilar meningitis), hydrocephalus; lymphocytic CSF with low glucose.","Meningite basal subaguda."],["vx9ryx109","What is scrofula?","Tuberculous (or atypical mycobacterial) cervical lymphadenitis.","Tuberculose ganglionar cervical."],["ibtrtx8ez","What precautions are needed for suspected active TB?","Airborne isolation with N95 respirator and negative pressure room.","Isolamento respiratório com N95."],["1h7apc01d","Which HIV patients need TB screening?","All HIV-infected patients at diagnosis (annually if risk persists).","Todos os pacientes com HIV."],["18379nk1t","What is the role of IGRA vs PPD in BCG-vaccinated individuals?","IGRA preferred because it does not cross-react with BCG.","IGRA não reage à BCG."],["16oapaohg","What is enterococcal intrinsic resistance?","Cephalosporins are ineffective; many strains resistant to aminoglycosides alone.","Resistentes às cefalosporinas."],["1u9js6r1k","What is the main reservoir of S. aureus in humans?","Anterior nares (nasal colonization); decolonized with mupirocin.","Narinas; mupirocina."],["kaapc41ec","What is the treatment of streptococcal toxic shock syndrome?","Penicillin plus clindamycin (and IVIG in some cases), debridement if needed.","Penicilina com clindamicina."],["1emd33c1o","What causes pharyngitis with a positive monospot vs negative rapid strep in a teenager?","EBV infectious mononucleosis.","Mononucleose."]]},{"name":"Clinical Bacteriology","cards":[["1w9x4391n","What infections does Neisseria meningitidis cause?","Meningococcemia (petechial hemorrhages, gangrene), meningitis, Waterhouse-Friderichsen syndrome.","Meningococcemia e meningite."],["1nz3dhjk2","How is N. meningitidis transmitted and prevented?","Respiratory and oral secretions; prevented by vaccines (conjugate ACWY, MenB); rifampin, ciprofloxacin, or ceftriaxone prophylaxis for close contacts.","Vacina e profilaxia dos contatos."],["m9hbbq1m9","What infections does Neisseria gonorrhoeae cause?","Urethritis, cervicitis, PID, prostatitis, epididymitis, septic arthritis, neonatal conjunctivitis, Fitz-Hugh-Curtis syndrome.","Uretrite, cervicite, artrite séptica."],["9n6lyg1vv","Why is there no vaccine for N. gonorrhoeae?","Antigenic variation of pilus proteins.","Variação antigênica."],["97wzqq1h1","Treatment of gonorrhea?","Ceftriaxone (plus doxycycline if chlamydia not excluded).","Ceftriaxona."],["1h1qy2ue8","What is Fitz-Hugh-Curtis syndrome?","Perihepatitis with violin-string adhesions from PID (gonorrhea or chlamydia).","Peri-hepatite após DIP."],["1nncdqn2r","What is disseminated gonococcal infection?","Triad of tenosynovitis, dermatitis (pustules), migratory polyarthralgia, or purulent monoarthritis.","Tenossinovite, pústulas, artrite."],["1sjs3euey","What infections does Haemophilus influenzae type b cause?","Epiglottitis (cherry red), meningitis, otitis media, pneumonia. (HaEMOPhilus).","Epiglotite, meningite, otite, pneumonia."],["1vprv1c1j","Which H. influenzae causes otitis media mostly now?","Nontypeable (unencapsulated) strains.","Cepas não tipáveis."],["1aj1kj3u5","Treatment of H. influenzae meningitis and prophylaxis of contacts?","Ceftriaxone; rifampin prophylaxis for close contacts.","Ceftriaxona; rifampicina para contatos."],["1hivwiz15","Features of epiglottitis?","Fever, drooling, dysphagia, stridor, tripod position, thumbprint sign on lateral neck x-ray.","Baba, estridor e sinal do polegar."],["1rs0jgh17","What infections does Moraxella catarrhalis cause?","Otitis media and sinusitis in children; COPD exacerbations.","Otite e sinusite."],["o6i19sdbf","What are features of Pseudomonas aeruginosa?","Aerobic, oxidase positive, nonfermenting gram-negative rod; blue-green pigment (pyocyanin); grape-like odor.","Pigmento verde-azulado e odor de uva."],["djgqxuo4z","What infections does Pseudomonas cause?","Pneumonia (CF, ventilator), sepsis, otitis externa (swimmer's ear), malignant otitis externa (diabetics), UTIs, burn infections, hot tub folliculitis, osteomyelitis in IV drug users and foot puncture, ecthyma gangrenosum.","Pneumonia, otite externa, queimaduras."],["l2v1f51w2","Treatment of Pseudomonas?","Antipseudomonal beta-lactams (piperacillin-tazobactam, cefepime, ceftazidime, carbapenems), aminoglycosides, fluoroquinolones, aztreonam, colistin.","Piperacilina, cefepima, carbapenêmicos."],["6mbdef10m","What is ecthyma gangrenosum?","Rapidly progressive necrotic cutaneous lesion from Pseudomonas bacteremia in immunocompromised (neutropenic) patients.","Lesão necrótica em neutropênicos."],["deb0ne1kr","What are the features of E. coli virulence?","Fimbriae (UTI), K capsule (pneumonia, neonatal meningitis), LPS endotoxin (septic shock).","Fímbrias, cápsula K e LPS."],["wkss741v0","What is EIEC?","Enteroinvasive E. coli: invades intestinal mucosa causing necrosis and inflammation; dysentery similar to Shigella.","Disenteria como Shigella."],["wk9hbx1uz","What is ETEC?","Enterotoxigenic E. coli: heat-labile and heat-stable toxins; traveler's diarrhea (watery).","Diarreia do viajante."],["wk6l4p1uz","What is EPEC?","Enteropathogenic E. coli: adheres to apical surface, flattens villi; diarrhea in children; no toxin.","Diarreia infantil."],["wkp2ld1uz","What is EHEC?","Enterohemorrhagic E. coli (O157:H7): Shiga-like toxin; bloody diarrhea, HUS; undercooked beef; does not ferment sorbitol.","Diarreia sanguinolenta e SHU."],["73cju13wt","Why are antibiotics avoided in EHEC?","May increase toxin release and HUS risk.","Podem aumentar o risco de SHU."],["1c7dqopeg","What is Klebsiella pneumoniae's presentation?","Aspiration pneumonia with currant jelly sputum in alcoholics and diabetics; lung abscesses; nosocomial UTIs; very mucoid colonies.","Escarro em geleia de groselha."],["wzs9ym19w","What does Salmonella vs Shigella have in common and differ?","Both invade GI tract. Salmonella: flagella (motile), H2S producer, animal reservoirs, dissemination. Shigella: nonmotile, no H2S, very low infectious dose, only human reservoir.","Salmonella é móvel e tem reservatório animal; Shigella não."],["mzaobz1rp","What is the presentation of nontyphoidal Salmonella?","Gastroenteritis from poultry, eggs, reptiles: bloody diarrhea; antibiotics prolong carrier state (not usually given).","Gastroenterite por aves e ovos."],["sjjoov11b","What is typhoid fever?","Salmonella Typhi: rose spots on abdomen, constipation, abdominal pain, fever, relative bradycardia; carrier state in gallbladder.","Febre tifoide: manchas rosadas e bradicardia relativa."],["1k2uqey1v","What is the presentation of shigellosis?","Crampy abdominal pain, tenesmus, bloody mucoid stools; very low infectious dose; can trigger reactive arthritis and HUS (S. dysenteriae).","Disenteria com tenesmo."],["1r08k1728","What is Yersinia enterocolitica's presentation?","Bloody diarrhea, pseudoappendicitis (RLQ pain from mesenteric adenitis); pork, unpasteurized milk; daycare outbreaks.","Pseudoapendicite."],["fgf89lq7l","What is Campylobacter jejuni's presentation?","Bloody diarrhea from poultry, meat, unpasteurized milk; comma or S-shaped, grows at 42°C; associated with Guillain-Barré and reactive arthritis.","Diarreia por frango; Guillain-Barré."],["i7zm7u1ea","What is Vibrio cholerae's presentation?","Voluminous rice-water diarrhea; comma-shaped, oxidase positive; grows in alkaline media; treated with oral rehydration.","Diarreia em água de arroz."],["wm72xt5w5","What is Vibrio vulnificus?","Infection from raw oysters or seawater exposure: severe wound infections and sepsis, especially in liver disease (iron overload).","Ostras cruas; grave em hepatopatas."],["16sja4i1e","What is Vibrio parahaemolyticus?","Gastroenteritis from raw or undercooked seafood.","Frutos do mar crus."],["mueenw1ya","What is Helicobacter pylori?","Curved, flagellated, urease-positive gram-negative rod causing gastritis, peptic ulcers, gastric adenocarcinoma, MALT lymphoma.","Gastrite, úlcera e câncer gástrico."],["4oqdsuw2j","What is the presentation of Bordetella pertussis?","Whooping cough: catarrhal stage (URI), paroxysmal stage (coughing fits with inspiratory whoop, post-tussive emesis), convalescent stage; lymphocytosis.","Tosse comprida com guincho."],["c4t29ysxw","Treatment and prevention of pertussis?","Macrolides (azithromycin); prophylaxis for contacts; DTaP and Tdap vaccines (including during pregnancy).","Azitromicina e vacina."],["pl4wi2121","What is Legionella's transmission?","Inhalation of aerosols from contaminated water (air conditioning, cooling towers); no person-to-person transmission.","Aerossóis de água contaminada."],["cwlpeg10n","What is Proteus mirabilis's presentation?","UTI with struvite stones (urease positive); swarming motility.","ITU com cálculo de estruvita."],["183bj451b","What is Gardnerella vaginalis's presentation?","Bacterial vaginosis: thin gray-white discharge with fishy odor, clue cells, pH >4.5; treat with metronidazole or clindamycin.","Vaginose bacteriana."],["17vkjbk1o","What is Bacteroides fragilis?","Most common anaerobe in colon; causes intra-abdominal abscesses; treated with metronidazole.","Abscessos abdominais; metronidazol."],["jj25yp1qj","What is Treponema pallidum's presentation in primary syphilis?","Painless chancre (indurated ulcer) at the inoculation site; dark-field shows spirochetes.","Cancro duro indolor."],["1kwwzh7c8","What is the presentation of secondary syphilis?","Disseminated disease: maculopapular rash including palms and soles, condylomata lata, lymphadenopathy, patchy alopecia.","Exantema em palmas e plantas."],["i768qdcxf","What is the presentation of tertiary syphilis?","Gummas, aortitis (vasa vasorum destruction), neurosyphilis (tabes dorsalis, general paresis), Argyll Robertson pupils.","Gomas, aortite, neurossífilis."],["ppaj8m1s2","What are Argyll Robertson pupils?","Pupils that accommodate but do not react to light (prostitute's pupil), in neurosyphilis.","Acomodam mas não reagem à luz."],["1e0020mfn","What is tabes dorsalis?","Degeneration of dorsal columns and roots in neurosyphilis: loss of proprioception, broad-based ataxia, positive Romberg, Charcot joints, lightning pains.","Degeneração dos cordões posteriores."],["12zjisz1u","Which tests diagnose syphilis?","Nontreponemal (VDRL, RPR: screening, monitor treatment) and treponemal (FTA-ABS, TP-PA: confirmation, remain positive).","VDRL/RPR para rastreio; FTA-ABS para confirmar."],["14wtbo57n","What causes false-positive VDRL?","Pregnancy, viral infections (EBV, hepatitis), drugs, rheumatic fever, SLE, antiphospholipid syndrome, leprosy.","Gravidez, viroses, lúpus."],["rr50pm1cp","Treatment of syphilis?","Penicillin G (benzathine IM for early; IV for neurosyphilis); desensitize if allergic in pregnancy.","Penicilina G."],["lfdrzaa4y","What is the Jarisch-Herxheimer reaction?","Flu-like syndrome (fever, chills, headache, myalgia) after starting antibiotics for spirochetal infection due to killed bacteria releasing toxins.","Reação febril após tratar sífilis."],["1ak3zbwz1","What are signs of congenital syphilis?","Early: rhinitis (snuffles), rash, hepatosplenomegaly. Late: saber shins, saddle nose, Hutchinson teeth, mulberry molars, interstitial keratitis, CN VIII deafness.","Nariz em sela, dentes de Hutchinson."],["1qah1tot2","What is Lyme disease's cause and vector?","Borrelia burgdorferi transmitted by Ixodes ticks; reservoir in mice, deer essential for tick life cycle; northeastern US.","Borrelia pelo carrapato Ixodes."],["1nrfnv4wv","What are the stages of Lyme disease?","Early localized: erythema migrans (bull's-eye), flu-like. Early disseminated: bilateral facial nerve palsy, AV block, migratory arthralgias. Late: monoarthritis (knee), encephalopathy.","Eritema migratório, paralisia facial, bloqueio cardíaco, artrite."],["1m5ferque","Treatment of Lyme disease?","Doxycycline (amoxicillin in pregnancy/children); ceftriaxone for late or severe disease.","Doxiciclina."],["1pu1dzlds","What is relapsing fever?","Borrelia recurrentis (louse) or other Borrelia (ticks): recurrent fevers due to antigenic variation.","Febre recorrente por variação antigênica."],["fc82pio37","What is leptospirosis?","Leptospira interrogans in water contaminated with animal urine: flu-like symptoms, myalgias (calf), conjunctival suffusion, photophobia; surfers and tropics.","Água com urina de animais; dor na panturrilha."],["5l646pmz6","What is Weil disease?","Severe leptospirosis: jaundice, azotemia (kidney failure), fever, hemorrhage, anemia.","Icterícia, insuficiência renal e hemorragia."],["1fim954nv","What are the zoonotic bacteria from animal bites?","Pasteurella multocida (cat and dog bites: cellulitis, osteomyelitis), Capnocytophaga (dog bites, asplenic sepsis), Bartonella (cat scratch).","Pasteurella em mordidas de cão e gato."],["1p59wi01d","Treatment of animal bite prophylaxis?","Amoxicillin-clavulanate.","Amoxicilina-clavulanato."],["nkfm5x12g","What is Bartonella henselae's presentation?","Cat-scratch disease (regional lymphadenopathy, stellate necrotizing granulomas) in immunocompetent; bacillary angiomatosis in AIDS.","Doença da arranhadura do gato."],["1k1prkfpx","What is brucellosis?","Brucella from unpasteurized dairy or livestock: undulant fever, night sweats, arthralgia, hepatosplenomegaly.","Febre ondulante; leite não pasteurizado."],["17onjpwo1","What is tularemia?","Francisella tularensis from ticks, rabbits, deer flies: ulceroglandular disease with fever, ulcer, lymphadenopathy, pneumonia.","Coelhos e carrapatos."],["aolidc1uj","What is plague?","Yersinia pestis from fleas (rodents, prairie dogs): bubonic (painful buboes), pneumonic, septicemic; safety pin staining.","Peste bubônica por pulgas."],["1o8opw914","What is Q fever?","Coxiella burnetii from aerosols of cattle and sheep amniotic fluid: pneumonia, hepatitis, culture-negative endocarditis; no rash, no vector.","Gado e ovelhas; endocardite com cultura negativa."],["1gxgs1usk","What is Rocky Mountain spotted fever?","Rickettsia rickettsii via Dermacentor tick: fever, headache, rash starting on wrists and ankles spreading centrally including palms and soles; southeastern US.","Exantema começa em punhos e tornozelos."],["1f1pmv2dz","Treatment of rickettsial infections?","Doxycycline (even in children).","Doxiciclina."],["1ntkbgj1f","What is epidemic typhus?","Rickettsia prowazekii via human body louse: rash starting centrally and spreading outward, sparing palms and soles.","Exantema central poupando palmas."],["1ltsrx91k","What is endemic (murine) typhus?","Rickettsia typhi via fleas: milder centrally starting rash.","Tifo murino por pulgas."],["gwucpg1r8","What is ehrlichiosis?","Ehrlichia chaffeensis via Lone Star tick: fever, headache, leukopenia, thrombocytopenia, elevated LFTs, monocytes with morulae (berry-like inclusions); usually no rash.","Mórulas em monócitos."],["kmh79dved","What is anaplasmosis?","Anaplasma phagocytophilum via Ixodes tick: fever, leukopenia, thrombocytopenia; granulocytes with morulae.","Mórulas em granulócitos."],["1t09k0c1b","What diseases does Chlamydia trachomatis cause?","Serotypes A-C: trachoma (blindness). D-K: urethritis, cervicitis, PID, ectopic pregnancy, neonatal pneumonia (staccato cough) and conjunctivitis. L1-L3: lymphogranuloma venereum.","Tracoma, uretrite, DIP, linfogranuloma."],["38n05dq29","What are the two forms of Chlamydia?","Elementary body (small, dense, infectious, enters cell) and reticulate body (replicates in cell by fission).","Corpo elementar infecta; reticulado replica."],["ka0roi4mr","Why is Chlamydia not treated with beta-lactams?","Its cell wall lacks classic peptidoglycan (reduced muramic acid).","Parede sem peptidoglicano típico."],["1qi33wp1p","Treatment of chlamydia?","Doxycycline (azithromycin in pregnancy).","Doxiciclina."],["1uevtmaez","What is lymphogranuloma venereum?","Chlamydia L1-L3: painless genital ulcer, then painful inguinal lymphadenopathy (buboes) that may form fistulas, proctocolitis.","Úlcera indolor e bubões dolorosos."],["nz25wd9b8","What is chancroid?","Haemophilus ducreyi: painful genital ulcer with exudate and painful lymphadenopathy.","Úlcera genital dolorosa."],["vjgetgqda","What is granuloma inguinale (donovanosis)?","Klebsiella granulomatis: painless, beefy red genital ulcer that bleeds; Donovan bodies (bipolar staining).","Úlcera vermelha indolor que sangra."],["85gd5l1fk","What are the causes of painless genital ulcers?","Syphilis (chancre), lymphogranuloma venereum, granuloma inguinale.","Sífilis, linfogranuloma, donovanose."],["ditz671ga","What are the causes of painful genital ulcers?","HSV and chancroid (H. ducreyi).","Herpes e cancroide."],["1mc0r0u10","What causes nongonococcal urethritis?","Chlamydia trachomatis most commonly; Mycoplasma genitalium, Ureaplasma, Trichomonas.","Clamídia."],["1nnua6b1f","What causes reactive arthritis?","Chlamydia (urethritis) or GI infections (Shigella, Salmonella, Campylobacter, Yersinia); HLA-B27; conjunctivitis, urethritis, arthritis.","Após clamídia ou diarreia; HLA-B27."],["4wuxoj1u0","What causes bacterial prostatitis in young vs older men?","Young: Chlamydia, gonorrhea. Older: E. coli and other gram-negative rods.","Jovem: IST; idoso: E. coli."],["hrsynxtfi","What causes UTIs in order of frequency?","E. coli > S. saprophyticus > Klebsiella; Proteus, Enterococcus, Pseudomonas in complicated cases.","E. coli é o principal."],["hmn4xg11p","What urine dipstick findings suggest UTI?","Leukocyte esterase (WBCs) and nitrite (gram-negative bacteria reducing nitrate).","Esterase leucocitária e nitrito."],["ojk2qz120","What is sterile pyuria and its causes?","WBCs in urine with negative culture: urethritis from Chlamydia or gonorrhea, TB, interstitial nephritis.","Leucócitos sem bactéria; clamídia."],["1xbq181wu","What causes osteomyelitis in sickle cell disease?","Salmonella and S. aureus.","Salmonella e S. aureus."],["z0yckt1r9","What causes osteomyelitis after foot puncture through a sneaker?","Pseudomonas aeruginosa.","Pseudomonas."],["16bgoopuj","What causes septic arthritis in sexually active young adults?","Neisseria gonorrhoeae.","Gonococo."],["s1fyqx8iw","What causes vertebral osteomyelitis in IV drug users?","S. aureus and Pseudomonas, Candida.","S. aureus e Pseudomonas."],["1deiydtgv","What causes osteomyelitis from cat or dog bite?","Pasteurella multocida.","Pasteurella."],["q4hybqdi6","What causes infections in hunters and farmers with rabbits?","Francisella tularensis.","Francisella."],["eyg05px3m","What causes infection from raw seafood in a patient with cirrhosis?","Vibrio vulnificus.","Vibrio vulnificus."],["5tw4eo5w0","What causes infection in a patient with burns and green pus?","Pseudomonas aeruginosa.","Pseudomonas."],["jbf6kq1si","What causes atypical pneumonia, hyponatremia, and diarrhea in an older smoker?","Legionella.","Legionella."],["qqqpy3tt2","What causes meningitis with petechial rash in a college dorm?","Neisseria meningitidis.","Meningococo."],["13bpuw01y","What causes epiglottitis in an unvaccinated child?","Haemophilus influenzae type b.","Haemophilus tipo b."],["ggzguy1l5","What causes whooping cough in a teenager with waning immunity?","Bordetella pertussis.","Bordetella pertussis."],["1x12xzv18","What causes bloody diarrhea after a petting zoo?","EHEC O157:H7 (or Salmonella, Campylobacter).","E. coli O157:H7."],["1w9bgmeo5","What causes diarrhea and Guillain-Barré syndrome?","Campylobacter jejuni.","Campylobacter."],["l33r3l16f","What causes infection from undercooked pork with pseudoappendicitis?","Yersinia enterocolitica.","Yersinia."],["1ekrgub1w","What causes rice-water stools after travel?","Vibrio cholerae.","Cólera."],["12n56c4la","What causes fever and rash on palms and soles after a camping trip in North Carolina?","Rickettsia rickettsii (RMSF).","Febre maculosa."],["15vew4g1o","What causes a bull's-eye rash after hiking in Connecticut?","Borrelia burgdorferi (Lyme disease).","Doença de Lyme."],["11g5hgr12","What causes fever after cleaning rat-infested areas with jaundice and renal failure?","Leptospira (Weil disease).","Leptospirose."],["1jvigfv1d","What causes a hot tub rash?","Pseudomonas aeruginosa folliculitis.","Pseudomonas."],["1lecqp219","What causes malignant otitis externa in an elderly diabetic?","Pseudomonas aeruginosa.","Pseudomonas."],["1tsulge15","What causes infection after a dog bite in an asplenic patient?","Capnocytophaga canimorsus.","Capnocytophaga."],["1aeu8vf11","What causes undulant fever in a cheese lover traveler?","Brucella (unpasteurized dairy).","Brucella."],["1glbc9p1a","What causes neonatal pneumonia with staccato cough and eosinophilia?","Chlamydia trachomatis.","Clamídia."],["9eyrhf131","What causes PID-associated perihepatitis?","Chlamydia or gonorrhea (Fitz-Hugh-Curtis).","Clamídia ou gonococo."],["1xy0aym1s","What causes urethritis with negative Gram stain in a young man?","Chlamydia trachomatis.","Clamídia."],["184ftma1g","What causes septic shock with purpura fulminans and adrenal hemorrhage?","Neisseria meningitidis (Waterhouse-Friderichsen).","Meningococo."],["s1ezao1wm","What bacteria cause acute otitis media in children?","S. pneumoniae, nontypeable H. influenzae, Moraxella catarrhalis.","Pneumococo, Haemophilus e Moraxella."],["ydnvd51kn","What bacteria cause acute sinusitis?","S. pneumoniae, H. influenzae, M. catarrhalis (most sinusitis is viral).","Mesmos da otite; maioria viral."],["11pxp398s","What bacteria cause infection in chronic granulomatous disease?","Catalase-positive organisms: S. aureus, Burkholderia cepacia, Serratia, Nocardia, Aspergillus.","Catalase-positivos."],["1mw92xdgt","What bacteria commonly cause ventilator-associated pneumonia?","Pseudomonas, MRSA, Klebsiella, Acinetobacter, Enterobacter.","Pseudomonas, MRSA, Klebsiella."],["148ee7a1h","What bacteria commonly cause catheter-related bloodstream infections?","Coagulase-negative staphylococci, S. aureus, Enterococcus, Candida, gram-negative rods.","Estafilococos coagulase negativos."],["1sl85ecpj","What bacteria cause spontaneous bacterial peritonitis?","E. coli, Klebsiella, (and S. pneumoniae).","E. coli e Klebsiella."],["zenj5muuh","What bacteria cause brain abscess?","Viridans streptococci, anaerobes (from sinuses, teeth), S. aureus (hematogenous), Toxoplasma or Nocardia in immunocompromised.","Estreptococos e anaeróbios."],["1i4h54x4h","What bacteria cause sepsis in neonates within the first week?","Group B strep, E. coli, Listeria.","Estreptococo B, E. coli, Listeria."],["k7iv2b159","What bacteria cause infection in CF patients?","Early: S. aureus, H. influenzae. Later: Pseudomonas, Burkholderia cepacia.","Primeiro S. aureus; depois Pseudomonas."],["g640at1co","What bacteria cause pneumonia in HIV patients with low CD4?","S. pneumoniae, H. influenzae, Pseudomonas, plus opportunistic organisms (Pneumocystis, TB).","Pneumococo e oportunistas."],["4geq4t1a3","What bacteria cause pharyngitis with gray pseudomembrane and myocarditis?","Corynebacterium diphtheriae.","Difteria."]]},{"name":"Mycology","cards":[["1l0fmuw1r","What are systemic (endemic) mycoses?","Dimorphic fungi: cold (20°C) = mold, heat (37°C) = yeast; cause pulmonary and disseminated disease; not transmitted person to person.","Fungos dimórficos endêmicos."],["tv7fkk1x9","Mnemonic for dimorphic fungi temperature forms?","Mold in the cold, yeast in the heat.","Bolor no frio, levedura no calor."],["1g8swrw1b","Where is histoplasmosis endemic?","Mississippi and Ohio River valleys; bird or bat droppings (caves).","Vales do Mississippi e Ohio; fezes de aves e morcegos."],["e1bhltldu","Histologic appearance of Histoplasma?","Small oval yeast within macrophages.","Leveduras pequenas dentro de macrófagos."],["b8vmq1a4d","Presentation of histoplasmosis?","Pneumonia, hepatosplenomegaly, mucosal ulcers, pancytopenia in disseminated disease (AIDS); urine/serum antigen test.","Pneumonia e doença disseminada em AIDS."],["al79w61w9","Where is blastomycosis endemic?","Eastern and Central US, Great Lakes.","Leste e centro dos EUA, Grandes Lagos."],["naslt88gv","Histologic appearance of Blastomyces?","Large yeast with broad-based budding (same size as RBCs or bigger).","Levedura grande com brotamento de base larga."],["1wfiptf29","Presentation of blastomycosis?","Pneumonia, inflammatory lung disease, disseminates to skin (verrucous lesions) and bone.","Pneumonia e lesões verrucosas de pele."],["ty3vzoqll","Where is coccidioidomycosis endemic?","Southwestern US (Arizona, California San Joaquin Valley), dust exposure, earthquakes.","Sudoeste dos EUA; poeira."],["wvv96e1lv","Histologic appearance of Coccidioides?","Spherules (much larger than RBCs) filled with endospores.","Esférulas cheias de endósporos."],["m0lqmp1pb","Presentation of coccidioidomycosis?","Pneumonia, erythema nodosum (desert bumps), arthralgias (desert rheumatism), meningitis, skin and bone dissemination.","Pneumonia, eritema nodoso, artralgias."],["igge2exan","Where is paracoccidioidomycosis endemic?","Latin America (Brazil).","América Latina, Brasil."],["a2v12s911","Histologic appearance of Paracoccidioides?","Budding yeast with captain's wheel formation (multiple buds).","Levedura em roda de leme."],["mvhfs514t","Treatment of systemic mycoses?","Fluconazole or itraconazole for local infection; amphotericin B for severe or disseminated disease.","Azóis; anfotericina se grave."],["sa8lsv1ir","What is Sporothrix schenckii?","Dimorphic fungus causing sporotrichosis after thorn prick (rose gardener's disease): ascending nodular lymphangitis; cigar-shaped budding yeast.","Espinho de rosa; linfangite nodular."],["tbarhg1u9","Treatment of sporotrichosis?","Itraconazole (or potassium iodide).","Itraconazol."],["mm89a31t5","What is tinea versicolor?","Malassezia furfur: hypopigmented or hyperpigmented patches, often after hot humid weather; spaghetti and meatballs on KOH.","Pitiríase versicolor; espaguete com almôndegas."],["18lk4py79","Treatment of tinea versicolor?","Selenium sulfide, topical or oral azoles.","Sulfeto de selênio ou azóis."],["1ir57lgji","What are dermatophytes and how are they diagnosed?","Trichophyton, Microsporum, Epidermophyton causing tinea infections; KOH prep shows branching septate hyphae.","Hifas septadas no KOH."],["13nm8vc7l","What is tinea capitis?","Scalp dermatophyte infection in children: alopecia, scaling, possible kerion; treated with oral griseofulvin or terbinafine.","Tinha do couro cabeludo; tratamento oral."],["clg5hw1iy","What is tinea corporis?","Ringworm: erythematous scaling ring with central clearing; from contact with infected cats or dogs.","Lesão em anel com centro claro."],["lglf51ums","What is tinea cruris?","Jock itch: pruritic lesions in inguinal area, sparing the scrotum.","Micose da virilha."],["1hbkgk61k","What is tinea pedis?","Athlete's foot: interdigital, moccasin, or vesicular types.","Pé de atleta."],["tyj8p1rd8","What is tinea unguium (onychomycosis)?","Nail fungal infection; treated with oral terbinafine or itraconazole.","Micose de unha."],["geyzjt1km","What is Candida albicans's morphology?","Yeast with pseudohyphae (germ tubes at 37°C); dimorphic.","Levedura com pseudo-hifas."],["14hx928bp","What infections does Candida cause?","Oral and esophageal thrush, vulvovaginitis (diabetes, antibiotics), diaper rash, endocarditis (IVDU), disseminated candidiasis, chronic mucocutaneous candidiasis.","Sapinho, vulvovaginite, candidemia."],["5eiprv17f","Treatment of Candida infections?","Topical azoles or nystatin (oral, vaginal); fluconazole; echinocandins or amphotericin B for systemic disease.","Nistatina, fluconazol, equinocandinas."],["1sm05p51g","Why does esophageal candidiasis suggest HIV?","It is an AIDS-defining illness (CD4 <100); requires systemic treatment.","Doença definidora de AIDS."],["klj5i21gl","What is Aspergillus fumigatus's morphology?","Septate hyphae branching at acute (45°) angles; conidiophore with radiating chains of spores.","Hifas septadas em ângulo agudo."],["1tj23ji1w","What is invasive aspergillosis?","Infection in immunocompromised (neutropenia, CGD): pneumonia with hemorrhagic infarction, halo sign on CT; treated with voriconazole.","Infecção pulmonar em neutropênicos; voriconazol."],["18fylti1n","What is allergic bronchopulmonary aspergillosis?","Hypersensitivity to Aspergillus in asthma and CF: wheezing, eosinophilia, high IgE, central bronchiectasis.","Alergia ao Aspergillus na asma e fibrose cística."],["zoslnhkbf","What is an aspergilloma?","Fungus ball forming in preexisting lung cavities (old TB); hemoptysis.","Bola fúngica em cavidade."],["1haivw51x","What toxin does Aspergillus flavus produce?","Aflatoxin, associated with hepatocellular carcinoma.","Aflatoxina; câncer de fígado."],["rky4rn1is","What is Cryptococcus neoformans's morphology?","Heavily encapsulated yeast (not dimorphic); India ink or mucicarmine stain; latex agglutination detects capsule antigen.","Levedura encapsulada; tinta da China."],["1pe2xevqp","Source of Cryptococcus?","Soil and pigeon droppings; acquired by inhalation.","Fezes de pombo."],["1ekr9701v","Presentation of cryptococcosis?","Meningitis in immunocompromised (AIDS, CD4 <100), soap bubble lesions in the brain; pneumonia.","Meningite em AIDS."],["xop51w5zf","Treatment of cryptococcal meningitis?","Amphotericin B plus flucytosine, then fluconazole for maintenance; serial LPs for high pressure.","Anfotericina com flucitosina."],["mg5cij1rt","What are Mucor and Rhizopus?","Irregular broad nonseptate hyphae branching at wide (90°) angles.","Hifas largas sem septos em ângulo reto."],["1lymi8oif","Who gets mucormycosis?","Diabetic ketoacidosis, neutropenia, iron overload (deferoxamine).","Cetoacidose diabética."],["1qcyraq3j","Presentation of mucormycosis?","Rhinocerebral infection: facial pain, headache, black necrotic eschar on face or palate, cranial nerve involvement; spreads to brain.","Escara negra no palato ou face."],["1sa17sw1o","Treatment of mucormycosis?","Surgical debridement plus amphotericin B (or isavuconazole, posaconazole).","Desbridamento e anfotericina."],["1tbya5rmn","What is Pneumocystis jirovecii?","Yeast-like fungus causing interstitial pneumonia in immunosuppressed (HIV with CD4 <200).","Pneumonia em HIV com CD4 <200."],["gkcdot22r","Presentation and imaging of Pneumocystis pneumonia?","Dry cough, dyspnea, hypoxemia, diffuse bilateral ground-glass opacities; elevated LDH.","Vidro fosco bilateral e hipoxemia."],["15joqyr1i","How is Pneumocystis diagnosed?","Bronchoalveolar lavage or lung biopsy with methenamine silver stain (disc-shaped yeast).","Lavado com coloração de prata."],["168yod21x","Treatment of Pneumocystis pneumonia?","TMP-SMX (alternatives: pentamidine, dapsone, atovaquone); add steroids if PaO2 <70 mmHg.","Sulfametoxazol-trimetoprima; corticoide se hipoxemia."],["1x6h7n11e","When is Pneumocystis prophylaxis started in HIV?","CD4 count <200 cells/mm³; TMP-SMX.","CD4 abaixo de 200."],["1dm098c1h","Which fungal infections are AIDS-defining?","Esophageal candidiasis, cryptococcal meningitis, Pneumocystis pneumonia, disseminated histoplasmosis or coccidioidomycosis.","Esôfago por Candida, criptococo, Pneumocystis."],["e42jgql3j","What CD4 count predisposes to cryptococcal meningitis and disseminated histoplasmosis?","CD4 <100 (histoplasmosis <150).","CD4 abaixo de 100."],["ekeq5215h","What is the mechanism of amphotericin B?","Binds ergosterol in fungal membranes, forming pores that allow electrolyte leakage.","Liga ergosterol e forma poros."],["y14y8i8i8","Adverse effects of amphotericin B?","Fever and chills (shake and bake), hypotension, nephrotoxicity, arrhythmias, anemia, IV phlebitis; hypokalemia and hypomagnesemia.","Febre, nefrotoxicidade, hipocalemia."],["tcdm8y1kn","How is amphotericin nephrotoxicity reduced?","Hydration (saline loading) and liposomal formulations.","Hidratação e forma lipossomal."],["b8424qrl6","Mechanism of nystatin?","Same as amphotericin B (binds ergosterol); too toxic for systemic use; topical for oral thrush and diaper rash.","Igual à anfotericina; uso tópico."],["lva9c7ars","Mechanism of flucytosine?","Converted to 5-fluorouracil by cytosine deaminase, inhibiting DNA and RNA synthesis; used with amphotericin B for cryptococcus.","Vira 5-FU dentro do fungo."],["1jypsih5o","Adverse effect of flucytosine?","Bone marrow suppression.","Supressão medular."],["1dpdyva1d","Mechanism of azoles?","Inhibit fungal sterol (ergosterol) synthesis by inhibiting CYP450 14-alpha-demethylase (lanosterol to ergosterol).","Inibem a síntese de ergosterol."],["17spb9fbb","Uses of fluconazole?","Chronic suppression of cryptococcal meningitis in AIDS, candidal infections.","Criptococo e Candida."],["1qas03611","Uses of itraconazole?","Blastomyces, Coccidioides, Histoplasma, Sporothrix (non-life-threatening).","Fungos dimórficos."],["mxyja61p8","Uses of voriconazole?","Aspergillus and some Candida.","Aspergillus."],["1plqehp17","Uses of posaconazole and isavuconazole?","Mucor (and other molds) and prophylaxis in high-risk patients.","Mucor e profilaxia."],["15gep571b","Adverse effects of azoles?","Testosterone synthesis inhibition (gynecomastia, especially ketoconazole), liver dysfunction, CYP450 inhibition, QT prolongation.","Ginecomastia, hepatotoxicidade, interações."],["14q4jd6ri","Adverse effects specific to voriconazole?","Visual disturbances, hallucinations, photosensitivity (skin cancer risk), periostitis.","Alterações visuais e fotossensibilidade."],["12ofuwzk3","Mechanism and use of terbinafine?","Inhibits squalene epoxidase, decreasing ergosterol; dermatophytoses, especially onychomycosis.","Inibe esqualeno epoxidase; onicomicose."],["1i3mog64q","Adverse effects of terbinafine?","GI upset, headaches, hepatotoxicity, taste disturbance.","Hepatotoxicidade e alteração do paladar."],["1llf3si1k","Mechanism of echinocandins?","Caspofungin, micafungin, anidulafungin inhibit cell wall synthesis by inhibiting beta-glucan synthase.","Inibem a síntese de beta-glucana."],["10z0lmsqa","Uses and adverse effects of echinocandins?","Invasive aspergillosis, candidemia; GI upset, flushing (histamine release).","Candidemia; rubor."],["euljaj1la","Mechanism and use of griseofulvin?","Interferes with microtubule function, disrupting mitosis; deposits in keratin; oral treatment of tinea capitis and superficial infections.","Atua nos microtúbulos; tinha do couro cabeludo."],["j42ukuvit","Adverse effects of griseofulvin?","Teratogenic, carcinogenic, confusion, headaches, disulfiram-like reaction, CYP450 inducer.","Teratogênico; induz CYP450."],["14es4xa16","What is the fungal cell membrane sterol?","Ergosterol (humans have cholesterol).","Ergosterol."],["16zfwa2r4","What is the fungal cell wall component targeted by echinocandins?","Beta-1,3-D-glucan.","Beta-glucana."],["1nliqjl3s","Which fungus causes infection in neonatal ICU from lipid-rich TPN?","Malassezia furfur (fungemia).","Malassezia."],["nohtiw135","Which fungus produces germ tubes at 37°C?","Candida albicans.","Candida albicans."],["1x5b2i6pb","Which fungus is associated with hemoptysis in a patient with a prior TB cavity?","Aspergillus (aspergilloma).","Aspergillus."],["e1l7b7ywp","Which fungal infection is associated with bat guano in caves?","Histoplasmosis.","Histoplasmose."],["i4s40l147","Which fungal infection is associated with earthquakes and dust storms in California?","Coccidioidomycosis.","Coccidioidomicose."],["17kir9v1r","Which fungal infection is associated with pigeon droppings?","Cryptococcosis.","Criptococose."],["19t657717","Which fungal infection is associated with rose gardening?","Sporotrichosis.","Esporotricose."],["2m3yoq1xo","Which fungal infection causes verrucous skin lesions and bone involvement after lung infection?","Blastomycosis.","Blastomicose."],["9yus6tv3q","Which fungal infection is associated with neutropenia and halo sign?","Invasive aspergillosis.","Aspergilose invasiva."],["qxhg8c1oz","Which test detects invasive fungal infections broadly?","Beta-D-glucan assay (not for Cryptococcus or Mucor).","Beta-D-glucana."],["1f2fso17r","Which test detects invasive aspergillosis?","Galactomannan antigen.","Galactomanana."],["7emvdl1vo","Which fungal infection is linked to TNF-alpha inhibitors?","Histoplasmosis (and other endemic mycoses).","Histoplasmose."],["fcpadopcp","Which fungal infection is associated with corticosteroid use and causes oral white plaques that scrape off?","Oral candidiasis (thrush), e.g., with inhaled corticosteroids; rinse mouth after use.","Sapinho por corticoide inalado."],["1h3629tv5","What is candidal intertrigo?","Erythematous macerated rash with satellite lesions in skin folds.","Assadura com lesões satélites."],["17nhyc1wo","What distinguishes candidal diaper dermatitis from irritant dermatitis?","Candida involves skin folds and has satellite lesions; irritant dermatitis spares folds.","Candida acomete dobras e tem satélites."],["x57lg212e","What is vulvovaginal candidiasis's discharge?","Thick, white, cottage cheese discharge with pruritus, normal pH (<4.5).","Corrimento branco grumoso e pH normal."],["8dfrpb1bb","Treatment of vulvovaginal candidiasis?","Oral fluconazole or topical azoles.","Fluconazol oral."],["19jwmxr1k","What is Histoplasma's mode of evading immunity?","Survives within macrophages.","Sobrevive dentro de macrófagos."],["17pl31s1u","Which fungus is broad-based budding?","Blastomyces (Blasto buds broadly).","Blastomyces."],["dyiuub3z4","Which fungus is narrow-based budding with a capsule?","Cryptococcus.","Cryptococcus."],["179leyl12","Which organism appears as 'Mickey Mouse ears' or captain's wheel?","Paracoccidioides.","Paracoccidioides."],["pn9mkis9e","What is the first-line therapy for severe disseminated histoplasmosis in AIDS?","Liposomal amphotericin B, then itraconazole.","Anfotericina lipossomal e depois itraconazol."],["1xhhc0016","What fungal prophylaxis is used in leukemia or stem cell transplant?","Posaconazole or fluconazole (depending on risk).","Posaconazol ou fluconazol."],["xxyzjchfi","What is chromoblastomycosis?","Chronic verrucous skin infection after traumatic inoculation; copper-colored sclerotic bodies (medlar bodies) in tropical regions.","Lesão verrucosa crônica; corpos fumagoides."]]},{"name":"Parasitology","cards":[["4r5on3hbc","What is Giardia lamblia's presentation?","Bloating, flatulence, foul-smelling fatty diarrhea (no blood); campers and hikers drinking stream water; daycare.","Diarreia gordurosa após água de rio."],["dry5ut1jx","How is Giardia diagnosed and treated?","Trophozoites (pear-shaped, two nuclei, falling leaf motility) or cysts in stool; stool antigen; metronidazole or tinidazole.","Trofozoítos nas fezes; metronidazol."],["11cs6gh1m","What is Entamoeba histolytica's presentation?","Amebic dysentery (bloody diarrhea), liver abscess (anchovy paste), RUQ pain; flask-shaped ulcers.","Disenteria e abscesso hepático."],["y0kuku1nr","How is Entamoeba diagnosed and treated?","Serology, trophozoites with ingested RBCs, cysts with 4 nuclei; metronidazole then paromomycin or iodoquinol (luminal).","Metronidazol mais agente luminal."],["1g639m11d","What is Cryptosporidium's presentation?","Severe watery diarrhea in AIDS; mild in immunocompetent; acid-fast oocysts; resistant to chlorine (outbreaks in pools).","Diarreia aquosa grave em AIDS."],["moyb1ky4s","Treatment of cryptosporidiosis?","Nitazoxanide (immunocompetent); antiretroviral therapy in HIV.","Nitazoxanida."],["1fgi84kzc","What is Toxoplasma gondii's transmission?","Cysts in raw meat or oocysts in cat feces; crosses placenta.","Carne crua e fezes de gato."],["qbn7g41dm","Presentation of toxoplasmosis in AIDS?","Brain abscesses: multiple ring-enhancing lesions on CT/MRI (CD4 <100).","Lesões cerebrais em anel."],["1f0wyr611","Presentation of congenital toxoplasmosis?","Chorioretinitis, hydrocephalus, diffuse intracranial calcifications.","Coriorretinite, hidrocefalia, calcificações."],["tmvce6ssm","Treatment of toxoplasmosis?","Sulfadiazine plus pyrimethamine (with leucovorin).","Sulfadiazina e pirimetamina."],["1l0pliy1h","When is Toxoplasma prophylaxis given in HIV?","CD4 <100 with positive Toxoplasma IgG; TMP-SMX.","CD4 <100; sulfa."],["20rogq9ju","What is Naegleria fowleri's presentation?","Rapidly fatal primary amebic meningoencephalitis after swimming in warm freshwater (enters via cribriform plate).","Meningoencefalite fatal após água doce morna."],["n63edl1ja","Treatment of Naegleria?","Amphotericin B plus miltefosine (usually fatal).","Anfotericina; quase sempre fatal."],["1c4thpjge","What is Trypanosoma brucei's disease?","African sleeping sickness: enlarged posterior cervical nodes (Winterbottom sign), recurring fever (antigenic variation), somnolence, coma; tsetse fly.","Doença do sono pela mosca tsé-tsé."],["p53lywlt8","Treatment of African trypanosomiasis?","Suramin (blood-borne), melarsoprol (CNS); fexinidazole.","Suramina e melarsoprol."],["tg5v4sv6m","What are the Plasmodium species?","P. falciparum, P. vivax, P. ovale, P. malariae, P. knowlesi; transmitted by female Anopheles mosquito.","Malária pelo mosquito Anopheles."],["1xcsqhzqo","Which Plasmodium species form dormant liver hypnozoites?","P. vivax and P. ovale (relapses); treat with primaquine (check G6PD).","Vivax e ovale; primaquina."],["1rydplxaf","What is the fever pattern of P. vivax/ovale vs P. malariae?","Vivax/ovale: every 48 hours (tertian). Malariae: every 72 hours (quartan).","Terçã e quartã."],["n85c0c1fl","Why is P. falciparum the most dangerous?","Irregular fevers, parasitized RBCs occlude capillaries (cerebral malaria, renal, lung); banana-shaped gametocytes, multiple ring forms.","Oclui capilares; malária cerebral."],["tnmu0j13m","How is malaria diagnosed?","Thick and thin blood smears (Giemsa) or rapid antigen test.","Gota espessa."],["1rofxwm18","Treatment of uncomplicated chloroquine-sensitive malaria?","Chloroquine (or hydroxychloroquine).","Cloroquina."],["15avyh893","Treatment of chloroquine-resistant or severe malaria?","Artemisinin combinations (artemether-lumefantrine), atovaquone-proguanil; IV artesunate for severe disease.","Derivados de artemisinina; artesunato."],["e99kt3i9k","What is Babesia's presentation?","Fever and hemolytic anemia in northeastern US (Ixodes tick); Maltese cross on smear; severe in asplenia.","Hemólise e cruz de Malta."],["1tspucv14","Treatment of babesiosis?","Atovaquone plus azithromycin.","Atovaquona e azitromicina."],["1fwbs8q19","What is Trypanosoma cruzi's disease?","Chagas disease: dilated cardiomyopathy with apical atrophy, megacolon, megaesophagus; reduviid (kissing) bug in South America; Romaña sign (unilateral periorbital swelling).","Doença de Chagas pelo barbeiro."],["836whwz1q","Treatment of Chagas disease?","Benznidazole or nifurtimox.","Benznidazol."],["z2bd09m7d","What is Leishmania donovani's disease?","Visceral leishmaniasis (kala-azar): spiking fevers, hepatosplenomegaly, pancytopenia; sandfly; macrophages with amastigotes.","Calazar pelo flebotomíneo."],["xe3i21oyw","Treatment of visceral leishmaniasis?","Liposomal amphotericin B, sodium stibogluconate, miltefosine.","Anfotericina lipossomal."],["7sgadv1ui","What is cutaneous leishmaniasis?","Skin ulcers at sandfly bite sites (Leishmania braziliensis, mexicana, major).","Úlceras de pele."],["1ezhyd91d","What is Trichomonas vaginalis's presentation?","Vaginitis with foul-smelling greenish frothy discharge, itching, strawberry cervix; motile trophozoites on wet mount; pH >4.5.","Corrimento esverdeado espumoso e colo em morango."],["af3ia91o6","Treatment of trichomoniasis?","Metronidazole for patient and partner.","Metronidazol para o casal."],["k0took18w","What is Enterobius vermicularis's presentation?","Pinworm: perianal itching, especially at night; tape test shows eggs.","Coceira anal noturna; fita adesiva."],["1puds6fbm","Treatment of pinworm?","Albendazole, mebendazole, or pyrantel pamoate.","Albendazol."],["1yrh0uip1","What is Ascaris lumbricoides's presentation?","Giant roundworm: fecal-oral; intestinal obstruction at ileocecal valve, biliary obstruction, Löffler syndrome (migrating larvae: cough, eosinophilia).","Obstrução intestinal; síndrome de Löffler."],["qs7io38b1","What is Strongyloides stercoralis's presentation?","Larvae penetrate skin from soil: GI symptoms, pulmonary symptoms, rash; hyperinfection with steroids or HTLV-1 (gram-negative sepsis).","Hiperinfecção com corticoide."],["6swnm2nst","Treatment of strongyloidiasis?","Ivermectin.","Ivermectina."],["1uzuajydl","What are hookworms and their presentation?","Ancylostoma duodenale and Necator americanus: larvae penetrate skin; intestinal blood loss causes microcytic anemia.","Ancilostomíase e anemia ferropriva."],["ei9vvk12r","What is Trichinella spiralis's presentation?","Undercooked pork or bear: fever, myalgia, periorbital edema, eosinophilia (larvae encyst in muscle).","Carne de porco; edema periorbital e mialgia."],["3b3i561d4","What is Trichuris trichiura's presentation?","Whipworm: diarrhea, rectal prolapse in children.","Prolapso retal em crianças."],["1wxivpf15","What is Toxocara canis's presentation?","Visceral larva migrans after ingesting eggs (dog/cat feces): hepatomegaly, eosinophilia, ocular larva migrans (blindness).","Larva migrans visceral e ocular."],["swd6nbg58","What is Onchocerca volvulus's presentation?","River blindness from black fly: skin nodules, depigmentation, blindness; treated with ivermectin.","Cegueira dos rios; ivermectina."],["1fby4a013","What is Loa loa's presentation?","Deer fly: swelling in skin (Calabar swellings), worm visible crossing the conjunctiva.","Verme atravessando o olho."],["621o814wf","What is Wuchereria bancrofti's presentation?","Mosquito-borne lymphatic filariasis: elephantiasis (lymphedema) after months to years; treated with diethylcarbamazine.","Elefantíase."],["af0o4wdih","What is Dracunculus medinensis?","Guinea worm from contaminated water: painful skin ulcer from which worm emerges.","Verme da Guiné."],["1ogk4261t","What is cutaneous larva migrans?","Animal hookworm larvae (Ancylostoma braziliense) in skin: serpiginous pruritic tracks after walking barefoot on beaches.","Bicho geográfico."],["pxgj27125","What is Taenia solium's presentation?","Ingestion of larvae in undercooked pork causes intestinal tapeworm; ingestion of eggs (fecal-oral) causes cysticercosis/neurocysticercosis (swiss cheese brain, seizures).","Carne de porco: teníase; ovos: neurocisticercose."],["136bpap2m","Treatment of neurocysticercosis?","Albendazole (with steroids); praziquantel for intestinal tapeworm.","Albendazol com corticoide."],["15tmtel3u","What is the most common cause of acquired epilepsy worldwide?","Neurocysticercosis.","Neurocisticercose."],["1l8capk12","What is Diphyllobothrium latum's presentation?","Fish tapeworm from raw freshwater fish: B12 deficiency (megaloblastic anemia); treated with praziquantel or niclosamide.","Tênia do peixe; falta de B12."],["1qdq6fxrd","What is Echinococcus granulosus's presentation?","Eggs from dog feces: hydatid cysts in liver (eggshell calcification); cyst rupture causes anaphylaxis; sheep are intermediate hosts.","Cisto hidático; anafilaxia se romper."],["ito807sj4","Treatment of hydatid cyst?","Albendazole and surgery (inject ethanol or hypertonic saline before removal to kill daughter cysts).","Albendazol e cirurgia."],["1sw6i9n4f","What is Schistosoma mansoni and japonicum's presentation?","Snails release cercariae that penetrate skin: liver granulomas, fibrosis, portal hypertension, splenomegaly.","Esquistossomose hepática e hipertensão portal."],["1l3a1l51s","What is Schistosoma haematobium's presentation?","Hematuria and squamous cell carcinoma of the bladder.","Hematúria e câncer de bexiga."],["1o2od3ywh","Treatment of schistosomiasis?","Praziquantel.","Praziquantel."],["1hdvcikbs","What is Clonorchis sinensis's presentation?","Liver fluke from undercooked fish: biliary tract inflammation, pigmented gallstones, cholangiocarcinoma.","Colangiocarcinoma."],["jb6p53139","What is Paragonimus westermani's presentation?","Lung fluke from undercooked crab: hemoptysis, lung inflammation and fibrosis.","Caranguejo; hemoptise."],["1ii1054sr","Which parasites are treated with praziquantel?","Flukes (trematodes) and tapeworms (cestodes), except neurocysticercosis (albendazole preferred).","Trematódeos e cestódeos."],["1smrtc614","Which parasites are treated with albendazole or mebendazole?","Most intestinal nematodes (pinworm, Ascaris, hookworm, whipworm) and cysticercosis, echinococcosis.","Nematódeos e cisticercose."],["1khuzkozh","Which parasites cause eosinophilia?","Helminths, especially tissue-invasive ones (Strongyloides, Trichinella, Toxocara, schistosomes); not protozoa.","Helmintos invasivos."],["1schc4t47","Which parasites cause microcytic anemia?","Hookworms (Ancylostoma, Necator) and Trichuris.","Ancilóstomos."],["lqhwqszlh","Which parasites cause biliary tract disease?","Clonorchis, Ascaris, Fasciola.","Clonorchis e Ascaris."],["kagml7k2m","Which parasites cause brain cysts and seizures?","Taenia solium (neurocysticercosis).","Taenia solium."],["gwiskt17k","Which parasites cause hematuria and bladder cancer?","Schistosoma haematobium.","Schistosoma haematobium."],["195v43a1x","Which parasites cause liver cysts?","Echinococcus granulosus.","Echinococcus."],["bjbd97gup","Which parasites cause myalgias and periorbital edema?","Trichinella spiralis.","Trichinella."],["uyd2i625q","Which parasites cause perianal pruritus?","Enterobius vermicularis.","Oxiúros."],["1b0xenc12","Which parasites cause vitamin B12 deficiency?","Diphyllobothrium latum.","Diphyllobothrium."],["1kk1z9n1p","What is the mechanism of pyrantel pamoate?","Depolarizing neuromuscular blocking agent causing spastic paralysis of worms.","Paralisa o verme."],["13en6hd18","What is the mechanism of ivermectin?","Increases chloride permeability causing paralysis of nematodes (glutamate-gated chloride channels).","Paralisa nematódeos."],["1wr7mqv14","What is the mechanism of praziquantel?","Increases calcium permeability, causing paralysis of trematodes and cestodes.","Aumenta cálcio no verme."],["l61qqk1cb","What is the mechanism of albendazole?","Binds beta-tubulin, inhibiting microtubule formation and glucose uptake in worms.","Inibe microtúbulos do verme."],["1nvlwk215","What is the mechanism of chloroquine?","Blocks detoxification of heme into hemozoin; free heme accumulates and is toxic to plasmodia.","Impede a detoxificação do heme."],["6x4qombzz","Adverse effects of chloroquine?","Retinopathy, pruritus (especially in dark skin), QT prolongation.","Retinopatia e prurido."],["szg0is1fo","Adverse effects of primaquine?","Hemolysis in G6PD deficiency.","Hemólise na deficiência de G6PD."],["wskmse68b","What is the mechanism of metronidazole?","Forms toxic free radical metabolites that damage DNA; bactericidal and antiprotozoal.","Radicais livres que danificam DNA."],["g8qanwz41","Uses of metronidazole?","Giardia, Entamoeba, Trichomonas, Gardnerella, anaerobes (Bacteroides, C. difficile), H. pylori.","Giárdia, ameba, tricomonas, anaeróbios."],["1w4dp3u18","Adverse effects of metronidazole?","Disulfiram-like reaction with alcohol, metallic taste, headache, peripheral neuropathy.","Efeito antabuse e gosto metálico."],["1xuyko5zs","What is the role of mefloquine?","Malaria prophylaxis in chloroquine-resistant areas; neuropsychiatric side effects.","Profilaxia da malária; efeitos psiquiátricos."],["kz5z511ge","Which malaria prophylaxis is used for travelers?","Atovaquone-proguanil, doxycycline, mefloquine, chloroquine (sensitive areas), tafenoquine.","Atovaquona-proguanil ou doxiciclina."],["7ppts910a","What is the role of nifurtimox and benznidazole?","Treat Chagas disease.","Doença de Chagas."],["cxuc0f1rp","What is the role of miltefosine?","Leishmaniasis and free-living amebae (Naegleria).","Leishmaniose e Naegleria."],["97sq8y7hu","What is the role of pentamidine?","Pneumocystis (alternative), African trypanosomiasis, leishmaniasis; adverse: hypoglycemia, pancreatitis, nephrotoxicity.","Pneumocystis e tripanossomíase."],["22230c1ax","What is Acanthamoeba's presentation?","Keratitis in contact lens users and granulomatous amebic encephalitis in immunocompromised.","Ceratite em usuários de lentes."],["nvj60oo6h","What protozoan causes diarrhea in AIDS with acid-fast oocysts?","Cryptosporidium (also Cystoisospora).","Cryptosporidium."],["1uyldkze4","What protozoan is associated with chlorine-resistant swimming pool outbreaks?","Cryptosporidium.","Cryptosporidium."],["jsuur21i2","Which tick-borne protozoan causes hemolysis in asplenic patients?","Babesia microti.","Babesia."],["5hd8fe18z","What parasitic disease causes megacolon and megaesophagus in Brazil?","Chagas disease.","Doença de Chagas."],["1jkqxhl16","What is the vector for leishmaniasis?","Sandfly (Lutzomyia, Phlebotomus).","Flebotomíneo."],["1gez19me8","What is the vector for malaria?","Female Anopheles mosquito.","Anopheles fêmea."],["1q01p8i1b","What is the vector for Chagas disease?","Triatomine (reduviid, kissing) bug.","Barbeiro."],["aiikd3626","What is the vector for African sleeping sickness?","Tsetse fly.","Mosca tsé-tsé."],["1klnubxzt","What is the vector for river blindness?","Black fly (Simulium).","Borrachudo."],["13wngnztr","What is the vector for lymphatic filariasis?","Mosquitoes (Culex, Anopheles, Aedes).","Mosquitos."],["1up9y8hdv","What is the treatment for Toxocara?","Albendazole (with steroids for ocular disease).","Albendazol."],["6x0gqrw4c","What is the presentation of acute schistosomiasis?","Katayama fever: fever, urticaria, eosinophilia weeks after freshwater exposure.","Febre de Katayama."],["192mwb612","What is swimmer's itch?","Cercarial dermatitis from avian schistosomes penetrating the skin; self-limited.","Dermatite por cercárias de aves."],["1yzjx9i1x","What is the main risk of untreated chronic Strongyloides before steroids?","Hyperinfection syndrome with disseminated larvae and gram-negative bacteremia; screen and treat with ivermectin.","Hiperinfecção grave; tratar antes do corticoide."],["1w4f4r61t","What causes visceral larva migrans and how is it acquired?","Toxocara canis or cati from ingesting eggs in soil contaminated by dog or cat feces (children with pica).","Toxocara; crianças que comem terra."],["1o4m358f7","What protozoan causes diarrhea after drinking well water in a hiker?","Giardia lamblia.","Giárdia."],["1n9enub1c","What causes liver abscess after travel to Mexico with bloody diarrhea?","Entamoeba histolytica.","Ameba."],["ddwyl05h8","What causes ring-enhancing brain lesions in an AIDS patient with a cat?","Toxoplasma gondii.","Toxoplasma."],["tg48bx1tu","What causes ring-enhancing brain lesions in an immigrant from Latin America with seizures?","Taenia solium (neurocysticercosis).","Neurocisticercose."],["13n9f1qq8","What causes fever every 48 hours after travel to India?","Plasmodium vivax.","Plasmodium vivax."],["1fvhrw3l1","What causes coma and renal failure in a traveler from sub-Saharan Africa?","Plasmodium falciparum.","Plasmodium falciparum."],["t41cepv5p","What causes vaginitis with frothy green discharge?","Trichomonas vaginalis.","Tricomonas."],["1macaxe1o","What causes anemia and eosinophilia in a child walking barefoot in the South?","Hookworm (Necator americanus).","Ancilostomíase."],["e917w310s","What causes anal itching at night in a child?","Enterobius vermicularis.","Oxiúros."],["1roakl6ax","What causes portal hypertension in an Egyptian farmer?","Schistosoma mansoni.","Esquistossomose."],["km4mna1dn","What causes hemoptysis after eating raw crab in Asia?","Paragonimus westermani.","Paragonimus."],["a3cv561tp","What causes cholangiocarcinoma after eating raw fish in Asia?","Clonorchis sinensis.","Clonorchis."],["2kr02a1fo","What causes megaloblastic anemia after raw fish in Scandinavia?","Diphyllobothrium latum.","Diphyllobothrium."]]},{"name":"Systems","cards":[["btnw2lysx","What are the most common causes of meningitis in newborns (0-6 months)?","Group B Streptococcus, E. coli, Listeria.","Estreptococo B, E. coli, Listeria."],["mitii21i9","What are the most common causes of meningitis in children (6 months-6 years)?","S. pneumoniae, N. meningitidis, H. influenzae type b (unvaccinated), enteroviruses.","Pneumococo, meningococo, enterovírus."],["35pfxj6d4","What are the most common causes of meningitis in ages 6-60?","S. pneumoniae, N. meningitidis, enteroviruses, HSV.","Pneumococo e meningococo."],["tx3blyhz2","What are the most common causes of meningitis over age 60?","S. pneumoniae, N. meningitidis, Listeria.","Pneumococo e Listeria."],["134i3kj1u","What causes meningitis in HIV patients?","Cryptococcus, CMV, toxoplasmosis (brain abscess), JC virus (PML).","Criptococo."],["ygx8q10p2","What are the most common causes of community-acquired pneumonia in neonates?","Group B strep, E. coli.","Estreptococo B e E. coli."],["1pjoiep35","What are the most common causes of pneumonia in children 4 weeks-18 years?","Viruses (RSV), Mycoplasma, Chlamydophila pneumoniae (adolescents), S. pneumoniae.","Vírus e Mycoplasma."],["86868q12h","What are the most common causes of pneumonia in adults 18-40?","Mycoplasma, Chlamydophila pneumoniae, S. pneumoniae, viruses.","Mycoplasma e pneumococo."],["4tzxg011n","What are the most common causes of pneumonia in adults 40-65?","S. pneumoniae, H. influenzae, anaerobes, viruses, Mycoplasma.","Pneumococo e Haemophilus."],["17ln27rml","What are the most common causes of pneumonia in the elderly?","S. pneumoniae, influenza virus, anaerobes, H. influenzae, gram-negative rods.","Pneumococo e influenza."],["12efv7z1g","What are causes of nosocomial pneumonia?","S. aureus, Pseudomonas, other enteric gram-negative rods.","S. aureus e Pseudomonas."],["i9c8aw1qa","What causes pneumonia in immunocompromised patients?","S. aureus, enteric gram-negative rods, fungi, viruses, Pneumocystis (HIV).","Fungos, vírus, Pneumocystis."],["1nbiewc87","What causes aspiration pneumonia?","Anaerobes (oral flora), right lower lobe.","Anaeróbios no lobo inferior direito."],["1wclvdo15","What causes pneumonia in alcoholics?","S. pneumoniae, Klebsiella, S. aureus, anaerobes.","Pneumococo e Klebsiella."],["1weyggm1s","What causes pneumonia in IV drug users?","S. pneumoniae, S. aureus (septic emboli).","S. aureus."],["neradv14f","What causes atypical pneumonia?","Mycoplasma, Chlamydophila, Legionella, viruses (RSV, CMV, influenza, adenovirus).","Mycoplasma, clamídia, Legionella."],["1d5u5wr1a","What causes UTI in ambulatory patients?","E. coli, then S. saprophyticus, Klebsiella.","E. coli."],["1um1jsb1h","What causes UTI in hospitalized patients?","E. coli, Klebsiella, Serratia, Pseudomonas, Enterococcus, Proteus.","E. coli, Klebsiella, Pseudomonas."],["ef6rhj1uh","Why are women more prone to UTIs?","Shorter urethra colonized by fecal flora.","Uretra curta."],["14lioh47w","What are risk factors for UTI?","Female sex, sexual activity, pregnancy, urinary obstruction, catheters, diabetes, vesicoureteral reflux, BPH.","Sexo feminino, gravidez, cateter, obstrução."],["191n8mjgk","What are symptoms of cystitis vs pyelonephritis?","Cystitis: dysuria, frequency, urgency, suprapubic pain. Pyelonephritis: fever, flank pain, CVA tenderness, WBC casts.","Cistite: disúria; pielonefrite: febre e dor lombar."],["1imees81y","What urine finding is specific for pyelonephritis?","WBC casts.","Cilindros leucocitários."],["1tbwwflcx","What causes UTI with alkaline urine and struvite stones?","Proteus mirabilis (urease).","Proteus."],["sd3aqwdcb","What are common vaginal infections and their pH?","Bacterial vaginosis (pH >4.5, fishy), trichomoniasis (pH >4.5, frothy green), candidiasis (pH normal, cottage cheese).","Vaginose e tricomoníase pH alto; candidíase pH normal."],["d4o94yiyj","What is the most common cause of bacterial STI in the US?","Chlamydia trachomatis.","Clamídia."],["1o9l9kh11","What is the presentation of PID?","Lower abdominal pain, cervical motion tenderness (chandelier sign), adnexal tenderness, fever, purulent discharge; chlamydia and gonorrhea.","Dor pélvica e dor à mobilização do colo."],["154nn4n1l","Complications of PID?","Infertility, ectopic pregnancy, chronic pelvic pain, tubo-ovarian abscess, Fitz-Hugh-Curtis syndrome.","Infertilidade e gravidez ectópica."],["mslctx1b9","What are the TORCH infections?","Toxoplasma, Other (syphilis, VZV, parvovirus B19, HIV, Zika), Rubella, CMV, HSV-2.","Infecções congênitas TORCH."],["sdqnwt1qu","What are common causes of neonatal sepsis?","Group B strep, E. coli, Listeria.","Estreptococo B, E. coli, Listeria."],["bi24zr6bz","What are causes of osteomyelitis in most patients?","S. aureus (most common overall).","S. aureus."],["1dxig9v1t","What causes osteomyelitis in sexually active young adults?","Neisseria gonorrhoeae (rare; more often septic arthritis).","Gonococo."],["pntcg91hx","What causes osteomyelitis in diabetics and IV drug users?","Pseudomonas, Serratia, S. aureus (polymicrobial in diabetic foot).","Pseudomonas e S. aureus."],["bjz55c1lt","What causes osteomyelitis after a prosthetic joint?","S. aureus and S. epidermidis.","Estafilococos."],["1sgwshv16","What causes vertebral osteomyelitis with TB?","Mycobacterium tuberculosis (Pott disease).","Tuberculose."],["vf3uxu1cm","What imaging is most sensitive for osteomyelitis?","MRI.","Ressonância."],["wjgurgkd9","What lab elevations occur in osteomyelitis?","Elevated ESR and CRP (useful for monitoring); diagnosis confirmed by bone biopsy and culture.","VHS e PCR altas."],["npmrb11g0","What are the red rashes of childhood?","Coxsackie A (hand-foot-mouth), HHV-6 (roseola), measles, parvovirus B19 (slapped cheek), rubella, S. pyogenes (scarlet fever), VZV (varicella).","Exantemas da infância."],["nnqnh4p2l","What causes a rash beginning at the head and moving down with Koplik spots?","Measles.","Sarampo."],["14zm0g21e","What causes a rash beginning at the head and moving down with postauricular lymphadenopathy?","Rubella.","Rubéola."],["bow6n27os","What causes a sandpaper-like rash with strawberry tongue?","Scarlet fever (S. pyogenes).","Escarlatina."],["1omzht4q2","What causes vesicular rash in different stages starting on trunk?","Varicella (VZV).","Varicela."],["18bnp5kvy","What causes slapped-cheek rash?","Parvovirus B19.","Parvovírus B19."],["12mo3j9ua","What causes rash on palms and soles?","Coxsackie A, RMSF, secondary syphilis (CARS), also Kawasaki, toxic shock syndrome.","Coxsackie, febre maculosa, sífilis."],["27ekpj1nc","What are the causes of bloody diarrhea?","Campylobacter, Salmonella, Shigella, EHEC, EIEC, Yersinia, C. difficile, Entamoeba histolytica.","Campylobacter, Shigella, EHEC, ameba."],["7sbivcek6","What are the causes of watery diarrhea?","ETEC, Vibrio cholerae, C. perfringens, viruses (rotavirus, norovirus), Giardia, Cryptosporidium.","ETEC, cólera, vírus, Giárdia."],["vupyf81hl","Which food poisoning has the shortest incubation (1-6 hours)?","Preformed toxins: S. aureus and B. cereus (emetic).","Toxinas pré-formadas."],["1riqj9w1k","Which organisms cause food poisoning from reheated rice?","Bacillus cereus.","Bacillus cereus."],["1kzj71hr3","Which organisms cause food poisoning from mayonnaise or meats left out?","S. aureus.","S. aureus."],["1j71gza1v","Which organisms cause food poisoning from raw oysters?","Vibrio parahaemolyticus and V. vulnificus (also norovirus).","Vibrio."],["3anyv6w12","Which organisms cause food poisoning from undercooked eggs and poultry?","Salmonella.","Salmonella."],["14qyytz13","Which organisms cause food poisoning from undercooked hamburger?","EHEC O157:H7.","E. coli O157:H7."],["a5a3klor5","Which organisms cause food poisoning from canned foods?","Clostridium botulinum.","Clostridium botulinum."],["vmew7p1mu","Which organisms cause food poisoning from deli meats and soft cheese?","Listeria.","Listeria."],["4iuxis14b","Which organisms cause food poisoning from reheated meat dishes?","Clostridium perfringens.","Clostridium perfringens."],["v8h37v1o6","What organisms are associated with bites from cats and dogs?","Pasteurella multocida (and Capnocytophaga for dogs).","Pasteurella."],["1t7rkhf1q","What organisms are associated with human bites?","Eikenella corrodens (fight bite), oral anaerobes, streptococci.","Eikenella."],["u7mld1lt9","What organisms are associated with rabbit or tick exposure in Arkansas?","Francisella tularensis.","Francisella."],["kozrf61wp","What organisms are associated with fish tank exposure?","Mycobacterium marinum.","Mycobacterium marinum."],["1e4pimr1i","What organisms are associated with birds (parrots)?","Chlamydophila psittaci (and Cryptococcus from pigeons).","Chlamydia psittaci."],["1yxjej764","What organisms are associated with reptiles and turtles?","Salmonella.","Salmonella."],["1bed77asm","What organisms are associated with rat urine-contaminated water?","Leptospira.","Leptospira."],["yam7n81q9","What organisms are associated with sheep and goats (unpasteurized milk)?","Brucella and Coxiella.","Brucella e Coxiella."],["nq4kr19sk","What organisms are associated with armadillos?","Mycobacterium leprae.","Hanseníase."],["1pudo813v","What organisms are associated with prairie dogs and fleas?","Yersinia pestis.","Yersinia pestis."],["ip8l8l17j","What organisms are associated with cat feces?","Toxoplasma gondii.","Toxoplasma."],["1s97j59h3","What organisms cause endocarditis in IV drug users?","S. aureus (tricuspid), Pseudomonas, Candida.","S. aureus."],["1xc4bzlyi","What organisms cause culture-negative endocarditis?","HACEK organisms, Coxiella, Bartonella, Brucella.","HACEK, Coxiella, Bartonella."],["tv640rj2c","What causes conjunctivitis in neonates?","N. gonorrhoeae (days 2-5), Chlamydia trachomatis (days 5-14), chemical (first day).","Gonococo e clamídia."],["18cjyvlp5","What causes adult bacterial conjunctivitis?","S. aureus, S. pneumoniae, H. influenzae; contact lens wearers: Pseudomonas.","Estafilococo e pneumococo."],["1725mam4m","What causes viral conjunctivitis?","Adenovirus (most common, highly contagious).","Adenovírus."],["rozg6y1sw","What causes keratitis in contact lens wearers?","Pseudomonas and Acanthamoeba.","Pseudomonas e Acanthamoeba."],["132eju21x","What causes dendritic corneal ulcers?","HSV keratitis.","Herpes simples."],["1otlucd1a","What causes infectious arthritis in young adults?","N. gonorrhoeae.","Gonococo."],["bjl7zm11x","What causes infectious arthritis in most adults?","S. aureus.","S. aureus."],["1r51vuhm2","What are the features of septic arthritis on synovial fluid?","Cloudy, WBC >50,000 with neutrophils, positive culture.","Leucócitos acima de 50.000."],["5cck851mp","What causes Lyme arthritis?","Borrelia burgdorferi (late stage, large joints like the knee).","Borrelia."],["5y0jq5yjp","What causes reactive arthritis after GI or GU infection?","Shigella, Salmonella, Yersinia, Campylobacter, Chlamydia (HLA-B27).","Infecções intestinais ou clamídia."],["1y27sbfme","What are common causes of acute otitis externa?","Pseudomonas and S. aureus (swimmer's ear).","Pseudomonas."],["qliedf1k7","What causes skin infections after shaving or hot tubs?","Pseudomonas aeruginosa folliculitis.","Pseudomonas."],["1niytdy1b","What causes infections in burn patients?","Pseudomonas, S. aureus.","Pseudomonas e S. aureus."],["1350ss4np","What causes sepsis in splenectomized patients?","Encapsulated organisms: S. pneumoniae, H. influenzae, N. meningitidis.","Bactérias encapsuladas."],["zwcc1j1h2","What infections are more common in diabetics?","Mucormycosis, malignant otitis externa (Pseudomonas), foot infections, emphysematous pyelonephritis, candidiasis.","Mucormicose e otite externa maligna."],["ptkhk01b2","What infections are more common in sickle cell disease?","Encapsulated organisms, Salmonella osteomyelitis, parvovirus B19 aplastic crisis.","Encapsuladas e Salmonella."],["10ifezu1b","What infections are more common with complement C5-C9 deficiency?","Neisseria.","Neisseria."],["fyefjzznw","What infections are more common in cystic fibrosis?","Pseudomonas, S. aureus, Burkholderia cepacia, Aspergillus (ABPA).","Pseudomonas."],["zr3pno90h","What infections are more common in transplant recipients?","CMV, EBV (PTLD), Pneumocystis, Aspergillus, BK virus.","CMV e oportunistas."],["l8b3fckr8","What infections are associated with neutropenia?","Gram-negative rods (Pseudomonas), Candida, Aspergillus.","Gram-negativos e fungos."],["zjsigwh2l","What infections are associated with B-cell deficiency?","Encapsulated bacteria, enteroviruses, Giardia.","Encapsuladas e Giárdia."],["ymci521wi","What infections are associated with T-cell deficiency?","Viruses, fungi, intracellular bacteria, Pneumocystis.","Vírus e fungos."],["1xmstu313","What infections are associated with ventilators?","Pseudomonas, MRSA, Acinetobacter.","Pseudomonas e MRSA."],["1gkfe719q","What infections are associated with urinary catheters?","E. coli, Klebsiella, Proteus, Enterococcus, Candida.","E. coli e Candida."],["m6zh6w13h","What infections are associated with IV catheters?","S. epidermidis, S. aureus, Candida.","S. epidermidis."],["1ro4wev1j","What infections are associated with crowded conditions (military barracks)?","N. meningitidis, Mycoplasma, adenovirus.","Meningococo e adenovírus."],["190q7nk1e","What infections are associated with water damage and air conditioning?","Legionella.","Legionella."],["oa7omsivz","What infections are associated with gardening and roses?","Sporothrix schenckii.","Esporotricose."],["f0bfqd724","What infections are associated with spelunking (caves)?","Histoplasma capsulatum and rabies (bats).","Histoplasma e raiva."],["18yysjsa5","What infections are associated with travel to Southwest US desert?","Coccidioides.","Coccidioides."],["17u8xl814","What infections are associated with travel to Great Lakes and Mississippi?","Blastomyces and Histoplasma.","Blastomyces e Histoplasma."],["89dvdw178","What infections are associated with freshwater swimming and fatal encephalitis?","Naegleria fowleri.","Naegleria."],["bar7sc1fz","What are the hospital-acquired infection prevention measures?","Hand hygiene, contact precautions, catheter care bundles, antibiotic stewardship.","Higiene das mãos e cuidados com cateteres."],["92xdshxc0","What are droplet precautions used for?","N. meningitidis, influenza, pertussis, mumps, rubella (surgical mask).","Máscara cirúrgica."],["1amhqln1g","What are airborne precautions used for?","Tuberculosis, measles, varicella (N95 and negative pressure room).","N95 e quarto com pressão negativa."],["1pnv50laq","What are contact precautions used for?","MRSA, VRE, C. difficile (soap and water; spores resist alcohol), scabies, RSV.","Avental e luvas; C. difficile com água e sabão."],["1bfarbh1b","Why is alcohol hand sanitizer ineffective against C. difficile?","Spores are not killed by alcohol; use soap and water.","Álcool não mata esporos."],["6p69ku7vm","What are the reportable diseases (examples)?","Hepatitis A-C, HIV, measles, mumps, rubella, salmonella, shigella, syphilis, gonorrhea, chlamydia, TB, Lyme, rabies, chickenpox.","Doenças de notificação compulsória."],["16xwn8pai","What is the sepsis definition?","Life-threatening organ dysfunction caused by a dysregulated host response to infection (SOFA increase ≥2).","Disfunção orgânica por infecção."],["9quyirxtm","What are the most common causes of sepsis?","Pneumonia, UTI, intra-abdominal infection, skin and soft tissue.","Pneumonia e ITU."]]},{"name":"Virology (Part 1)","cards":[["12d19spnj","Which viruses have naked (nonenveloped) genomes?","Papillomavirus, adenovirus, parvovirus, polyomavirus (DNA); calicivirus, picornavirus, reovirus, hepevirus (RNA). Give PAPP smallpox CPR and a HE.","Vírus sem envelope."],["j7kshi1is","Why are naked viruses more resistant?","They tolerate drying, detergents, and acid, enabling fecal-oral transmission.","Resistem a secagem e ácido."],["zgrotba04","Where do enveloped viruses acquire their envelope?","Usually from the plasma membrane when they bud; herpesviruses from the nuclear membrane.","Membrana plasmática; herpes da nuclear."],["t21nbpb9u","Which DNA viruses are not double-stranded?","Parvovirus (single-stranded).","Parvovírus."],["clresv1nx","Which DNA viruses are not linear?","Papillomavirus, polyomavirus (circular, supercoiled), hepadnavirus (circular, incomplete).","Papiloma, polioma e hepadna são circulares."],["cdrg4spro","Which RNA virus is double-stranded?","Reoviruses (rotavirus).","Reovírus."],["3m0b7fm97","Where do DNA viruses replicate?","Nucleus, except poxvirus (cytoplasm, carries its own DNA-dependent RNA polymerase).","No núcleo, exceto poxvírus."],["1u6kiul1t","Where do RNA viruses replicate?","Cytoplasm, except influenza and retroviruses (nucleus).","No citoplasma, exceto influenza e retrovírus."],["11rpz7218","What are positive-sense RNA viruses?","Genome acts as mRNA, infectious when purified: retroviruses, togaviruses, flaviviruses, coronaviruses, hepevirus, calicivirus, picornavirus.","Genoma funciona como RNAm."],["1mnd0m1mo","What are negative-sense RNA viruses?","Need RNA-dependent RNA polymerase in the virion: arenaviruses, bunyaviruses, paramyxoviruses, orthomyxoviruses, filoviruses, rhabdoviruses.","Trazem a própria polimerase."],["586ptm14f","Which viruses have segmented genomes?","Bunyaviruses, orthomyxoviruses (influenza), arenaviruses, reoviruses (BOARding flight).","Genoma segmentado permite rearranjos."],["1r2vrlz10","What is recombination in viral genetics?","Exchange of genes between two chromosomes by crossing over within regions of homology.","Troca de genes por recombinação."],["z6t13b1q1","What is reassortment?","Segmented viruses exchanging whole segments (influenza antigenic shift), causing pandemics.","Troca de segmentos; mudança antigênica."],["kvkyilo6m","What is complementation?","One virus provides a functional protein to another nonfunctional virus (e.g., HDV uses HBsAg).","Um vírus ajuda outro defeituoso."],["1fmjla51x","What is phenotypic mixing?","Coinfection where the genome of one virus is coated with proteins of another, without genetic change.","Genoma de um com capa do outro."],["fdrinv1yz","What are the herpesviruses?","HSV-1, HSV-2, VZV, EBV, CMV, HHV-6, HHV-7, HHV-8; enveloped dsDNA linear, latent infection.","Família herpes, com latência."],["pzp7j11s0","What does HSV-1 cause?","Gingivostomatitis, herpes labialis, keratoconjunctivitis, temporal lobe encephalitis, esophagitis, erythema multiforme.","Herpes labial e encefalite temporal."],["ftkuu91mr","Where does HSV-1 remain latent?","Trigeminal ganglia.","Gânglio trigeminal."],["u8qrge4pm","What does HSV-2 cause?","Herpes genitalis, neonatal herpes; latent in sacral ganglia.","Herpes genital; gânglios sacrais."],["ule3451em","How is HSV diagnosed?","PCR (especially CSF for encephalitis); Tzanck smear shows multinucleated giant cells (Cowdry A inclusions).","PCR; células gigantes multinucleadas."],["1w4oqy31p","What is HSV encephalitis's imaging finding?","Temporal lobe involvement (hemorrhagic necrosis) on MRI; CSF lymphocytes and RBCs; treat with IV acyclovir.","Lobo temporal; aciclovir."],["m0706ggw3","What is herpetic whitlow?","HSV infection of the finger (often healthcare workers).","Herpes no dedo."],["1kcbt861h","What does VZV cause?","Varicella (chickenpox), zoster (shingles); latent in dorsal root or trigeminal ganglia.","Varicela e herpes-zóster."],["kz4gc91pl","What is the varicella rash's characteristic?","Pruritic vesicles in different stages (dewdrop on a rose petal), starting on trunk; spreads centrifugally.","Vesículas em diferentes estágios."],["1aoqhj1jj","What are complications of varicella?","Secondary bacterial skin infection, pneumonia (adults), encephalitis, Reye syndrome with aspirin.","Infecção bacteriana, pneumonia, encefalite."],["k7yryp6wz","What is herpes zoster ophthalmicus?","VZV reactivation in V1; Hutchinson sign (nose tip lesions) predicts eye involvement.","Zóster oftálmico; sinal de Hutchinson."],["1b4j2h9gd","What is Ramsay Hunt syndrome?","VZV reactivation in the geniculate ganglion: facial palsy, ear pain, vesicles in the ear canal.","Paralisia facial com vesículas no ouvido."],["10p3a7c58","What is postherpetic neuralgia?","Persistent pain after shingles; risk increases with age; treated with gabapentin, TCAs, lidocaine patches.","Dor persistente após zóster."],["pn1r3215b","How is shingles prevented?","Recombinant zoster vaccine for adults ≥50.","Vacina recombinante após 50 anos."],["f7r74t1ep","What does EBV cause?","Infectious mononucleosis, Burkitt lymphoma, Hodgkin lymphoma, nasopharyngeal carcinoma, primary CNS lymphoma, PTLD, oral hairy leukoplakia.","Mononucleose e linfomas."],["1xt2cbqak","Which cell receptor does EBV use?","CD21 on B cells.","CD21."],["co7ocvvtk","What are features of infectious mononucleosis?","Fever, hepatosplenomegaly, pharyngitis, posterior cervical lymphadenopathy, atypical lymphocytes (reactive CD8+ T cells); rash after amoxicillin.","Febre, faringite, esplenomegalia, linfócitos atípicos."],["ftvqhg1i1","What is the test for EBV infection?","Monospot test (heterophile antibodies agglutinating sheep or horse RBCs); EBV-specific antibodies (VCA IgM).","Monoteste."],["1vc28b31p","Why should patients with mononucleosis avoid contact sports?","Risk of splenic rupture.","Risco de ruptura do baço."],["1evvtsk1a","What does CMV cause?","Congenital infection, mononucleosis-like illness (heterophile negative), pneumonia (transplant), esophagitis, colitis, retinitis (AIDS, CD4 <50).","Infecção congênita e oportunista."],["kkxg1q1tq","What are the inclusion bodies of CMV?","Owl's eye intranuclear inclusions in enlarged cells.","Inclusões em olho de coruja."],["1p2vtm7y9","Treatment of CMV?","Ganciclovir, valganciclovir, foscarnet, cidofovir.","Ganciclovir."],["1vhpnfl1l","What does HHV-6 cause?","Roseola infantum (exanthem subitum): high fever for days, then diffuse macular rash as fever breaks; febrile seizures.","Febre alta e depois exantema."],["27fz8vzu1","What does HHV-8 cause?","Kaposi sarcoma, primary effusion lymphoma, multicentric Castleman disease.","Sarcoma de Kaposi."],["1pqsl2n1f","What is Kaposi sarcoma's appearance?","Dark violaceous flat or nodular skin lesions (also mucosa, GI, lungs) with lymphocytic infiltrate; AIDS and transplant patients.","Lesões violáceas na pele."],["oq41mu1iz","What does adenovirus cause?","Febrile pharyngitis (sore throat), acute hemorrhagic cystitis, pneumonia, conjunctivitis (pink eye), gastroenteritis, myocarditis.","Faringite, conjuntivite, cistite hemorrágica."],["90csc7hy6","What does parvovirus B19 cause?","Erythema infectiosum (slapped cheek rash), aplastic crisis in sickle cell, hydrops fetalis, symmetric arthritis in adults, pure red cell aplasia.","Bochecha esbofeteada e crise aplásica."],["16fc4i81c","What cells does parvovirus B19 infect?","Erythroid precursors (P antigen receptor).","Precursores eritroides."],["d7wcf6ts0","What does HPV cause?","Warts (HPV 1, 2, 6, 11: genital condylomata), cervical, anal, penile, oropharyngeal cancer (HPV 16, 18).","Verrugas e câncer."],["1t9gnswou","How does HPV cause cancer?","E6 inhibits p53 and E7 inhibits Rb.","E6 inibe p53; E7 inibe Rb."],["1iygmfg1r","What is koilocytosis?","Cells with perinuclear clearing and wrinkled nucleus in HPV infection.","Coilócitos no HPV."],["1ngd6a91j","How is HPV prevented?","9-valent HPV vaccine (recommended at 11-12, up to 26, and selected adults to 45).","Vacina contra HPV."],["z4yay61jh","What does JC virus cause?","Progressive multifocal leukoencephalopathy in immunocompromised (AIDS, natalizumab, rituximab).","Leucoencefalopatia multifocal progressiva."],["hbfca611n","What does BK virus cause?","Nephropathy and hemorrhagic cystitis in transplant patients.","Nefropatia em transplantados."],["1605f1f9o","What does poxvirus (molluscum contagiosum) cause?","Flesh-colored umbilicated papules; molluscum bodies (eosinophilic inclusions); common in children and immunocompromised.","Pápulas umbilicadas."],["d9tigil0o","What is smallpox?","Variola virus: synchronous centrifugal rash (all lesions same stage, palms and soles); eradicated.","Varíola: lesões no mesmo estágio."],["w3waps1vr","What is mpox?","Orthopoxvirus: fever, lymphadenopathy, vesiculopustular lesions (often genital and perianal), sexual and close contact transmission.","Mpox com lesões vesiculopustulosas."],["8jhpgn1t9","What does HBV belong to?","Hepadnavirus: partially dsDNA circular, enveloped; replicates using reverse transcriptase.","Hepadnavírus com transcriptase reversa."],["1fjn3ly1y","Which DNA virus uses reverse transcriptase?","Hepatitis B virus.","Hepatite B."],["jh9fn01vx","Which herpes virus remains latent in B cells?","EBV.","EBV."],["kjpunj134","Which herpes virus remains latent in mononuclear cells?","CMV.","CMV."],["1ytbicbij","Which virus causes hemorrhagic cystitis in children?","Adenovirus.","Adenovírus."],["5adyolil9","Which virus causes hydrops fetalis?","Parvovirus B19.","Parvovírus B19."],["lbpuoz80x","Which virus causes oral hairy leukoplakia?","EBV.","EBV."],["24r4pgqqb","Which virus causes temporal lobe encephalitis?","HSV-1.","HSV-1."],["152j5ut1a","Which virus causes congenital deafness, periventricular calcifications, and microcephaly?","CMV.","CMV."],["mfl473oke","Which virus causes rash on cheeks then lacy reticular rash on extremities?","Parvovirus B19 (fifth disease).","Parvovírus B19."],["1vfbr4p19","Which virus causes high fever followed by rash after defervescence in an infant?","HHV-6 (roseola).","HHV-6."],["178qehj17","What is the mechanism of acyclovir?","Guanosine analog phosphorylated by viral thymidine kinase; inhibits viral DNA polymerase (chain termination).","Ativado pela timidina quinase viral."],["13iaumt1i","Uses of acyclovir, valacyclovir, famciclovir?","HSV and VZV; no activity against latent virus.","Herpes e varicela-zóster."],["1w84ylcbp","Adverse effect of acyclovir?","Obstructive crystalline nephropathy (hydrate well).","Cristais nos rins; hidratar."],["1vmqreu13","Mechanism of resistance to acyclovir?","Mutated viral thymidine kinase.","Mutação da timidina quinase."],["stnd7rifx","Mechanism of ganciclovir?","Phosphorylated by CMV viral kinase (UL97); inhibits viral DNA polymerase; CMV infections.","Ativado pela quinase do CMV."],["ngf2iyajj","Adverse effects of ganciclovir?","Bone marrow suppression (leukopenia, neutropenia, thrombocytopenia), renal toxicity.","Supressão medular."],["zou81pegr","Mechanism of foscarnet?","Pyrophosphate analog that binds viral DNA polymerase directly (no activation needed); CMV retinitis resistant to ganciclovir, acyclovir-resistant HSV.","Não precisa de ativação."],["6gl8r41xa","Adverse effects of foscarnet?","Nephrotoxicity, electrolyte abnormalities (hypocalcemia, hypomagnesemia) causing seizures.","Nefrotoxicidade e hipocalcemia."],["142e6vhue","Mechanism of cidofovir?","Nucleotide analog (does not need viral kinase) inhibiting viral DNA polymerase; CMV retinitis, acyclovir-resistant HSV; nephrotoxic (give probenecid and fluids).","Nefrotóxico; usar probenecida."],["qph5dwjyk","What is the mechanism of letermovir?","CMV DNA terminase complex inhibitor; CMV prophylaxis in transplant.","Profilaxia de CMV."],["kxk16oz0n","What is the mechanism of tecovirimat?","Inhibits orthopoxvirus envelope protein (VP37); treats smallpox and mpox.","Trata varíola e mpox."],["lyl1uo1l7","What is the main cause of viral myocarditis in the US?","Coxsackie B virus (and adenovirus, parvovirus B19).","Coxsackie B."],["5q4hw8w20","Which DNA virus is associated with nasopharyngeal carcinoma?","EBV.","EBV."],["1gmsgli1k","Which DNA virus is associated with Merkel cell carcinoma?","Merkel cell polyomavirus.","Poliomavírus de Merkel."],["56m5xm1pf","Which virus causes hepatocellular carcinoma without cirrhosis?","Hepatitis B.","Hepatite B."],["66yhfj1v0","What virus is associated with adult T-cell leukemia/lymphoma?","HTLV-1.","HTLV-1."],["1w76vc71v","Which viruses are oncogenic?","HBV, HCV, HPV, EBV, HHV-8, HTLV-1, Merkel cell polyomavirus.","HBV, HCV, HPV, EBV, HHV-8, HTLV-1."],["1brxu5okd","What is the Tzanck test?","Smear of vesicle base showing multinucleated giant cells in HSV-1, HSV-2, VZV infections.","Células gigantes na base da vesícula."],["ptzm72ok7","What are Cowdry type A inclusions?","Intranuclear eosinophilic inclusions in HSV and VZV infections.","Inclusões nucleares nos herpes."],["15gxlqf1p","What are Negri bodies?","Cytoplasmic inclusions in neurons infected by rabies virus (Purkinje cells, hippocampus).","Inclusões da raiva."],["1gp8gko16","What are Guarnieri bodies?","Cytoplasmic inclusions in poxvirus infections.","Inclusões dos poxvírus."],["1omzi0y52","What causes congenital varicella syndrome?","Maternal varicella in first or second trimester: limb hypoplasia, cutaneous scarring, cataracts, microcephaly.","Varicela materna precoce."],["2d87rx185","Why is neonatal varicella dangerous when maternal rash appears near delivery?","No maternal antibodies transferred; severe disease; give varicella-zoster immune globulin.","Sem anticorpos maternos; dar imunoglobulina."],["1q5t0i41c","What is the CD4 count threshold for CMV retinitis in AIDS?","CD4 <50.","CD4 abaixo de 50."],["1e6w4yw1p","What is CMV retinitis's fundoscopic appearance?","Cottage cheese and ketchup (hemorrhage and exudates) along vessels.","Queijo cottage com ketchup."],["yjyjajqxk","What is herpangina?","Coxsackie A: fever, sore throat, vesicles on the posterior pharynx and soft palate.","Vesículas no palato mole."],["1m506v3kz","What virus causes hand-foot-mouth disease?","Coxsackie A (and enterovirus 71): oral ulcers and vesicles on hands and feet.","Coxsackie A."],["zoxgqik7r","What virus causes acute hemorrhagic conjunctivitis outbreaks?","Enterovirus 70 or Coxsackie A24 (and adenovirus for epidemic keratoconjunctivitis).","Enterovírus."],["e397y0142","What causes 'pharyngoconjunctival fever' in summer camps?","Adenovirus (swimming pools).","Adenovírus."],["6fp52n1mv","What DNA virus is transmitted mainly by respiratory droplets and causes slapped cheek?","Parvovirus B19.","Parvovírus B19."],["1vcbiud1x","Which virus can cause encephalitis in neonates acquired at delivery?","HSV-2 (neonatal herpes).","HSV-2."],["1vl4zq81o","How is neonatal HSV prevented?","Cesarean delivery if active genital lesions at labor; suppressive acyclovir from 36 weeks.","Cesárea se houver lesão; aciclovir no fim da gestação."],["ju1i2d1rg","What test confirms HSV encephalitis?","CSF HSV PCR.","PCR no líquor."],["110mps9q9","What does a monospot-negative mononucleosis suggest?","CMV (or acute HIV, toxoplasmosis).","CMV ou HIV agudo."],["172lch1ol","Which virus causes a 'blueberry muffin' rash in newborns?","Congenital CMV or rubella (extramedullary hematopoiesis).","CMV ou rubéola congênita."],["di6z071ex","Which DNA virus causes respiratory infections and keratoconjunctivitis in military recruits?","Adenovirus (vaccine used in military).","Adenovírus."],["1u9iv5lvi","What is the DNA virus with the largest genome?","Poxvirus.","Poxvírus."],["tl7bn21sv","What is the smallest DNA virus?","Parvovirus.","Parvovírus."],["14xp8wvki","Which herpesvirus causes infectious mononucleosis with heterophile antibodies?","EBV.","EBV."],["n1al7v9r0","What antiviral is used for hepatitis B with HIV coinfection?","Tenofovir (with emtricitabine) as part of ART.","Tenofovir."],["o9mlxw101","What is the mechanism of entecavir?","Guanosine analog inhibiting HBV polymerase (reverse transcriptase).","Inibe a polimerase do HBV."],["1trtou91e","What is the treatment of severe varicella in adults or immunocompromised?","IV acyclovir.","Aciclovir venoso."],["e6y76o16v","What is the prophylaxis for varicella exposure in a pregnant woman without immunity?","Varicella-zoster immune globulin (VariZIG).","Imunoglobulina anti-varicela."],["1gtfstalx","What is the live varicella vaccine schedule?","Two doses (12-15 months and 4-6 years).","Duas doses na infância."],["1r1f5ds19","What skin lesions are classic for molluscum in AIDS?","Numerous large facial molluscum lesions.","Muitas lesões na face."],["1cwfw2p1s","What is the treatment of genital warts?","Cryotherapy, imiquimod, podophyllin, trichloroacetic acid.","Crioterapia ou imiquimode."],["1a2qgzr1w","What is the mechanism of imiquimod?","TLR7 agonist stimulating local immune response (warts, superficial basal cell carcinoma).","Estimula imunidade local."],["ondmn63n1","What is viral latency?","Persistence of viral genome without active replication, with possible reactivation (herpesviruses).","Vírus dormente que pode reativar."],["1rr04lt19","What is a viral envelope's clinical implication?","Enveloped viruses are sensitive to drying and detergents, usually spread by respiratory, sexual, or parenteral routes.","Sensíveis a sabão e secagem."],["jvzeppyky","What is the general structure of a virion?","Nucleic acid genome inside a protein capsid, with or without an envelope.","Genoma, capsídeo e às vezes envelope."],["uwkt4t1xp","Which viruses have icosahedral vs helical capsids?","Most DNA viruses are icosahedral (poxvirus complex); many negative-sense RNA viruses are helical.","Icosaédrico ou helicoidal."],["16s6wndiz","Which viruses carry their own polymerase in the virion?","Negative-sense RNA viruses, dsRNA viruses, poxviruses, and retroviruses (reverse transcriptase).","Vírus RNA negativo, poxvírus, retrovírus."],["hnxehejb5","Which DNA viruses cause cancer by integrating into host DNA?","HPV (high-risk types) and HBV.","HPV e HBV."],["1p7hmf212","What is the most common congenital viral infection?","CMV.","Citomegalovírus."],["1ni9uuxcq","What is the leading infectious cause of congenital sensorineural hearing loss?","CMV.","Citomegalovírus."],["1kp19381u","What is herpes gladiatorum?","HSV-1 skin infection spread among wrestlers by skin contact.","Herpes em lutadores."],["1u2gw3716","What is eczema herpeticum?","Disseminated HSV infection in patients with atopic dermatitis (punched-out erosions); treat with acyclovir.","Herpes disseminado na dermatite atópica."],["7s7tta1is","What is the treatment of herpes zoster in older adults?","Oral valacyclovir or famciclovir within 72 hours.","Valaciclovir nas primeiras 72 horas."],["1v2q4hv33","What is the treatment of oral hairy leukoplakia?","Usually none needed; ART improves it.","Melhora com a TARV."]]},{"name":"Virology (Part 2)","cards":[["18pwshl12","Which viruses are picornaviruses?","Poliovirus, echovirus, rhinovirus, coxsackievirus, hepatitis A virus (PERCH); positive ssRNA, naked.","Pólio, rinovírus, Coxsackie, hepatite A."],["2ir5pfz0f","What is the most common cause of the common cold?","Rhinovirus (acid labile, many serotypes).","Rinovírus."],["1q83suq5p","What does poliovirus cause?","Most asymptomatic; aseptic meningitis; paralytic poliomyelitis from destruction of anterior horn cells (asymmetric flaccid paralysis, LMN signs).","Paralisia flácida assimétrica."],["134lrts72","What are the two polio vaccines?","Salk (inactivated, IPV, used in US) and Sabin (oral, live attenuated, mucosal IgA, risk of vaccine-derived polio).","Salk inativada e Sabin oral."],["1u1vmdhzr","What does coxsackievirus cause?","Aseptic meningitis, herpangina, hand-foot-mouth disease, myocarditis, pericarditis, pleurodynia.","Meningite asséptica, mão-pé-boca, miocardite."],["122gzu2pj","What is the most common cause of aseptic (viral) meningitis?","Enteroviruses (coxsackievirus, echovirus).","Enterovírus."],["1qeg9h24v","What are caliciviruses?","Norovirus: most common cause of viral gastroenteritis in adults; outbreaks on cruise ships, nursing homes.","Norovírus."],["16ue1dvcs","What are reoviruses?","Rotavirus: dsRNA, segmented; most common cause of fatal diarrhea in children worldwide; daycare outbreaks in winter.","Rotavírus."],["nmjdk81kh","How is rotavirus prevented and what is the vaccine risk?","Live oral vaccine; small risk of intussusception.","Vacina oral; risco de intussuscepção."],["gaq6bn1xr","Which flaviviruses cause disease?","Hepatitis C, yellow fever, dengue, West Nile, Zika, Japanese encephalitis, tick-borne encephalitis.","Hepatite C, febre amarela, dengue, Zika."],["5p29qk3lq","What is yellow fever?","Flavivirus via Aedes mosquito: fever, jaundice (hepatocyte necrosis, Councilman bodies), black vomit, bradycardia; live vaccine.","Icterícia e vômito negro."],["1iisr8y13","What is dengue?","Flavivirus via Aedes: fever, severe myalgia and retro-orbital pain (breakbone fever), rash; second infection with different serotype risks hemorrhagic fever/shock (antibody-dependent enhancement).","Dor nos ossos; segunda infecção mais grave."],["15jqe3tdp","What test assesses capillary fragility in dengue?","Tourniquet test (petechiae).","Prova do laço."],["1yv7rcq10","What is West Nile virus?","Flavivirus via Culex mosquitoes, birds are reservoir: fever, meningoencephalitis, acute flaccid paralysis in elderly.","Encefalite e paralisia em idosos."],["o4gdug1vp","What is Zika virus?","Flavivirus via Aedes or sexual: mild rash and conjunctivitis; congenital microcephaly; Guillain-Barré.","Microcefalia congênita."],["z8xedi128","What are togaviruses?","Rubella (matonavirus now) and alphaviruses (chikungunya, eastern and western equine encephalitis).","Rubéola e chikungunya."],["1xn2kobol","What is rubella?","Fever, postauricular and occipital lymphadenopathy, fine maculopapular rash starting on face (lasting 3 days), arthralgia in adults.","Exantema leve e linfonodos retroauriculares."],["1sxpehs1e","What is congenital rubella syndrome?","Classic triad: PDA (or pulmonary artery stenosis), cataracts, sensorineural deafness; blueberry muffin rash.","PCA, catarata e surdez."],["1szu9bwgp","What is chikungunya?","Alphavirus via Aedes: high fever and severe, often persistent polyarthralgia.","Febre com artralgia intensa."],["6y0ced15q","What are coronaviruses?","Common cold, SARS, MERS, COVID-19 (SARS-CoV-2); positive ssRNA, enveloped.","Coronavírus."],["1c2ni4b8n","What is the receptor for SARS-CoV-2?","ACE2 (spike protein binds it).","ECA2."],["18v0n3m1b","What are typical features of severe COVID-19?","Viral pneumonia with ARDS, hypercoagulability, cytokine release; anosmia and ageusia.","SDRA, trombose, perda do olfato."],["bqizmemsq","What are orthomyxoviruses?","Influenza A and B: negative ssRNA, segmented, enveloped; hemagglutinin (binds sialic acid) and neuraminidase (release).","Influenza com hemaglutinina e neuraminidase."],["llx11ymct","What is antigenic drift vs shift?","Drift: point mutations in HA/NA causing seasonal epidemics. Shift: reassortment of segments between strains causing pandemics (influenza A only).","Deriva causa epidemias; mudança causa pandemias."],["npnaq818l","What complications follow influenza?","Secondary bacterial pneumonia (S. aureus, S. pneumoniae, H. influenzae), Reye syndrome with aspirin in children.","Pneumonia bacteriana secundária."],["nfwdun10e","Treatment of influenza?","Neuraminidase inhibitors (oseltamivir, zanamivir, peramivir) or baloxavir (cap-dependent endonuclease inhibitor), best within 48 hours.","Oseltamivir nas primeiras 48 horas."],["1mhdwbegp","What are paramyxoviruses?","Parainfluenza (croup), RSV, measles, mumps, metapneumovirus; negative ssRNA, nonsegmented, enveloped.","Parainfluenza, VSR, sarampo, caxumba."],["1pdmrv5wk","What is croup?","Parainfluenza virus: seal-like barking cough, inspiratory stridor, steeple sign on x-ray in young children.","Tosse de cachorro e sinal da torre."],["knvoorwh8","What does RSV cause?","Bronchiolitis in infants (wheezing, nasal flaring); premature infants at risk; prevented with nirsevimab or maternal vaccine.","Bronquiolite em lactentes."],["1qb34y119","What is measles (rubeola)?","Prodrome of cough, coryza, conjunctivitis, Koplik spots (white spots on buccal mucosa), then maculopapular rash starting at hairline and spreading downward.","Manchas de Koplik e exantema descendente."],["1qsda8ak6","Complications of measles?","Pneumonia (most common cause of death), encephalitis, subacute sclerosing panencephalitis years later, giant cell pneumonia in immunosuppressed.","Pneumonia, encefalite e PEES."],["4gs39cqg2","How does vitamin A help in measles?","Reduces morbidity and mortality, especially in malnourished children.","Reduz a mortalidade."],["1tcepksxv","What is mumps?","Parotitis, orchitis (can cause sterility after puberty), aseptic meningitis, pancreatitis.","Parotidite e orquite."],["12n6q151r","What are rhabdoviruses?","Rabies: bullet-shaped, negative ssRNA; travels retrograde along nerves via dynein.","Raiva; vírus em forma de bala."],["uidmtn10n","Presentation of rabies?","Long incubation; fever, agitation, photophobia, hydrophobia, hypersalivation, paralysis, coma, death.","Hidrofobia e agitação; fatal."],["1y226k11n","Which animals are common rabies sources in the US?","Bats (most common), raccoons, skunks, foxes.","Morcegos."],["1164puvgz","Postexposure prophylaxis for rabies?","Wound cleaning, rabies immune globulin, and rabies vaccine (killed).","Limpar, imunoglobulina e vacina."],["1qctiyf19","What are filoviruses?","Ebola and Marburg: hemorrhagic fever, high mortality; bodily fluid transmission.","Ebola e Marburg."],["ps028yjn6","What are arenaviruses?","Lassa fever (rodents, West Africa) and LCMV (hamsters, mice).","Febre de Lassa e LCMV."],["2rc8l6zcy","What are bunyaviruses?","Hantavirus (pulmonary syndrome, deer mice droppings in Southwest US), Crimean-Congo hemorrhagic fever, Rift Valley fever.","Hantavírus por fezes de roedores."],["1v7jawa16","What is hepatitis D virus?","Defective delta virus requiring HBsAg; increases severity of HBV infection.","Depende do HBsAg."],["6udatnhsl","What is hepatitis E virus?","Hepevirus: fecal-oral, self-limited; high mortality in pregnant women.","Grave em gestantes."],["b711u911a","What is the HIV structure?","Diploid positive ssRNA retrovirus, enveloped; gp120 (binding) and gp41 (fusion); reverse transcriptase.","Retrovírus com gp120 e gp41."],["6chud516v","Which HIV genes encode which proteins?","env: gp120 and gp41. gag: p24 capsid and p17 matrix. pol: reverse transcriptase, integrase, protease.","env, gag e pol."],["8ls1dwmyo","What receptors does HIV use to enter cells?","CD4 plus CCR5 (early, macrophages) or CXCR4 (later, T cells).","CD4 com CCR5 ou CXCR4."],["1fb81bvh0","Why are homozygous CCR5 delta32 individuals resistant to HIV?","They lack functional CCR5 co-receptor.","Sem o correceptor CCR5."],["1kdxyov1i","How is HIV diagnosed?","HIV-1/2 antigen/antibody combination immunoassay (p24 antigen), confirmed with HIV-1/HIV-2 differentiation assay; viral load if acute.","Teste combinado antígeno p24 e anticorpo."],["99p11g1ss","How is HIV diagnosed in newborns of HIV-positive mothers?","HIV RNA or DNA PCR (maternal antibodies cross the placenta).","PCR, não anticorpo."],["1pjkdgg5m","What is acute HIV infection?","Flu-like illness or mononucleosis-like syndrome 2-4 weeks after exposure: fever, rash, lymphadenopathy, sore throat; high viral load.","Síndrome tipo mononucleose."],["torjtlnsv","What defines AIDS?","CD4 <200 cells/mm³ or an AIDS-defining illness in HIV-infected patients.","CD4 <200 ou doença definidora."],["oxlxfz1c9","Which infections occur at CD4 <200?","Pneumocystis pneumonia, HIV-associated dementia, toxoplasmosis risk begins (<100 for Toxo).","Pneumocystis."],["oxpqgc1c9","Which infections occur at CD4 <100?","Toxoplasmosis, cryptococcal meningitis, histoplasmosis, candidal esophagitis, cryptosporidiosis (chronic), PML (variable).","Toxoplasmose e criptococo."],["1c3y4e0ra","Which infections occur at CD4 <50?","CMV retinitis, Mycobacterium avium complex, primary CNS lymphoma.","CMV e MAC."],["1vog8a1jw","What is the treatment of HIV?","Antiretroviral therapy started for all patients regardless of CD4: typically 2 NRTIs plus integrase inhibitor (e.g., bictegravir/tenofovir alafenamide/emtricitabine).","Terapia antirretroviral para todos."],["xte1xjg7u","What is HIV pre-exposure prophylaxis?","Tenofovir-emtricitabine daily or long-acting cabotegravir for high-risk individuals.","PrEP com tenofovir-entricitabina."],["1ne5qjctp","What is HIV post-exposure prophylaxis?","Three-drug ART started within 72 hours of exposure for 28 days.","PEP em até 72 horas por 28 dias."],["7mbnnq139","How is mother-to-child HIV transmission prevented?","Maternal ART, intrapartum zidovudine if high viral load, cesarean if viral load >1000, infant prophylaxis, avoid breastfeeding (in resource-rich settings).","TARV materna e profilaxia do bebê."],["1p1wucaqo","Mechanism of NRTIs?","Nucleoside/nucleotide analogs that inhibit reverse transcriptase by chain termination (tenofovir, emtricitabine, lamivudine, abacavir, zidovudine).","Terminam a cadeia de DNA viral."],["146db1zzn","Adverse effects of NRTIs?","Lactic acidosis (mitochondrial toxicity), zidovudine anemia, abacavir hypersensitivity (HLA-B*5701), tenofovir nephrotoxicity and bone loss.","Acidose lática; reação ao abacavir."],["x013qszda","Mechanism of NNRTIs?","Bind reverse transcriptase at a site different from NRTIs; do not require phosphorylation (efavirenz, rilpivirine, doravirine).","Inibem a transcriptase em outro sítio."],["jl495n1d7","Adverse effects of efavirenz?","Vivid dreams, CNS symptoms, rash, hepatotoxicity.","Sonhos vívidos e sintomas no SNC."],["x62o8b1x4","Mechanism of integrase inhibitors?","Inhibit HIV genome integration into host DNA (raltegravir, dolutegravir, bictegravir, cabotegravir).","Impedem a integração no DNA."],["1sds19ing","Adverse effects of integrase inhibitors?","Increased creatine kinase, weight gain, insomnia; dolutegravir increases serum creatinine (inhibits secretion).","CPK alta e ganho de peso."],["11bbafoaw","Mechanism of protease inhibitors?","Prevent cleavage of polyproteins into functional proteins (atazanavir, darunavir, lopinavir); end in -navir.","Impedem a maturação viral."],["1dif1a11n","Adverse effects of protease inhibitors?","Hyperglycemia, GI intolerance, lipodystrophy, nephropathy (indinavir), hyperbilirubinemia (atazanavir); CYP3A4 inhibition (ritonavir boosts levels).","Hiperglicemia e lipodistrofia."],["9x3k90bdp","Why is ritonavir used in low doses with other protease inhibitors?","Inhibits CYP3A4, boosting levels of other drugs.","Potencializa outros fármacos."],["xe4p6p17e","Mechanism of enfuvirtide?","Binds gp41, inhibiting viral entry (fusion).","Bloqueia a fusão via gp41."],["12bafquz7","Mechanism of maraviroc?","Binds CCR5 on T cells and monocytes, inhibiting interaction with gp120 (entry).","Bloqueia o CCR5."],["1pz7hlvw5","What is the HIV-associated nephropathy?","Collapsing focal segmental glomerulosclerosis, often in Black patients (APOL1).","GESF colapsante."],["ihyoa913z","What is HIV-associated neurocognitive disorder?","Cognitive decline from HIV infection of microglia (multinucleated giant cells).","Declínio cognitivo pelo HIV."],["uc91eb17e","What is immune reconstitution inflammatory syndrome?","Paradoxical worsening of opportunistic infections after starting ART as immunity recovers.","Piora inflamatória ao iniciar a TARV."],["1uoz75c1q","What is HTLV-1?","Retrovirus causing adult T-cell leukemia/lymphoma and HTLV-1-associated myelopathy (tropical spastic paraparesis).","Leucemia T e paraparesia espástica."],["1w83ji5vv","What virus causes croup with steeple sign?","Parainfluenza virus.","Parainfluenza."],["17baic01g","What virus causes bronchiolitis in infants?","RSV.","Vírus sincicial respiratório."],["1mtux1412","What virus causes Koplik spots?","Measles virus.","Sarampo."],["11mjzm4or","What virus causes parotitis and orchitis?","Mumps virus.","Caxumba."],["t4dhuk1ms","What virus causes hydrophobia?","Rabies virus.","Raiva."],["sowyvwqcr","What virus causes a pulmonary syndrome after cleaning a rodent-infested cabin?","Hantavirus.","Hantavírus."],["qaa3nw1l2","What virus causes encephalitis transmitted by mosquitoes with birds as reservoir?","West Nile virus.","Vírus do Nilo Ocidental."],["o165sk132","What virus causes microcephaly after maternal mosquito-borne infection?","Zika virus.","Zika."],["10ed53m1b","What virus causes breakbone fever?","Dengue virus.","Dengue."],["de0e52ejv","What virus causes jaundice and black vomit after travel to South America or Africa?","Yellow fever virus.","Febre amarela."],["bqkb61r16","What virus causes vomiting outbreaks on cruise ships?","Norovirus.","Norovírus."],["1okid7ii4","What virus causes severe diarrhea in unvaccinated infants in winter?","Rotavirus.","Rotavírus."],["31swi21i5","What virus causes the common cold most often?","Rhinovirus.","Rinovírus."],["pmpi1p1df","What virus causes acute flaccid asymmetric paralysis after GI illness?","Poliovirus (or enterovirus D68).","Poliovírus."],["1kdogpsww","What virus causes myocarditis and pleurodynia?","Coxsackie B.","Coxsackie B."],["2sfa645nw","What virus causes subacute sclerosing panencephalitis?","Measles (years after infection).","Sarampo."],["5dknkwsm9","What virus causes hemorrhagic fever with very high mortality in Africa?","Ebola (filovirus).","Ebola."],["fl1ho51sn","What virus causes tropical spastic paraparesis?","HTLV-1.","HTLV-1."],["1141ia44f","What are the viral hepatitis transmission routes?","A and E: fecal-oral. B, C, D: parenteral, sexual, perinatal.","A e E fecal-oral; B, C e D pelo sangue e sexo."],["12fom83r6","Which hepatitis viruses are RNA viruses?","A (picornavirus), C (flavivirus), D (deltavirus), E (hepevirus); B is DNA.","Todas são RNA, exceto a B."],["1gb11gk1r","What is the risk of chronicity in hepatitis C?","High (about 70-85% develop chronic infection).","Alta, cerca de 70-85%."],["1eahgo1wm","Why is there no HCV vaccine?","High antigenic variability (lack of 3'-5' exonuclease proofreading in RNA polymerase).","Grande variabilidade antigênica."],["1wir8sh1n","Mechanism of oseltamivir?","Neuraminidase inhibitor that decreases release of progeny virus.","Inibe a neuraminidase."],["1iu6ph816","Mechanism of baloxavir?","Inhibits cap-dependent endonuclease, blocking influenza viral mRNA transcription.","Inibe a endonuclease do influenza."],["sfstx69da","Mechanism of ribavirin?","Inhibits IMP dehydrogenase, decreasing guanine nucleotide synthesis; used for RSV (rarely) and HCV (historically).","Inibe a IMP desidrogenase."],["q20rs4170","Adverse effect of ribavirin?","Hemolytic anemia; severely teratogenic.","Anemia hemolítica; teratogênico."],["190q8x012","Mechanism of remdesivir?","Nucleotide analog inhibiting RNA-dependent RNA polymerase; COVID-19.","Inibe a polimerase do coronavírus."],["w78mhf11r","Mechanism of nirmatrelvir?","SARS-CoV-2 main protease inhibitor; given with ritonavir (CYP3A4 interactions).","Inibe a protease do coronavírus."],["uarmdcele","Which vaccines are live attenuated among RNA viruses?","MMR, rotavirus, yellow fever, oral polio, intranasal influenza, (also dengue in some contexts).","Tríplice viral, rotavírus, febre amarela."],["1riru6u11","Which vaccine prevents RSV in infants?","Nirsevimab (monoclonal antibody) or maternal RSV vaccine during pregnancy.","Nirsevimabe ou vacina materna."],["v4c3rmqes","What is the influenza vaccine recommendation?","Annual vaccination for everyone ≥6 months.","Anual a partir dos 6 meses."],["1f1zddo1w","What is antibody-dependent enhancement?","Non-neutralizing antibodies from a prior infection increase viral entry into cells (dengue severe disease on second infection).","Anticorpos facilitam a infecção."],["1koneu71m","Which RNA viruses replicate in the nucleus?","Influenza and retroviruses.","Influenza e retrovírus."],["1luhruq65","What is the main cause of severe dehydrating diarrhea in infants worldwide?","Rotavirus (vaccination has reduced cases).","Rotavírus."],["1n99hd7ng","What is the infectious dose difference between norovirus and others?","Norovirus has a very low infectious dose, explaining rapid outbreaks.","Dose infectante muito baixa."],["1ss3yor1n","What is aseptic meningitis's CSF profile?","Lymphocytic pleocytosis, normal glucose, normal or mildly elevated protein.","Linfócitos e glicose normal."],["1ht1lkvlj","What are prions?","Misfolded proteins (PrPsc, beta-pleated) that induce misfolding of normal PrP (alpha-helical); cause spongiform encephalopathy; resistant to standard sterilization.","Proteínas mal dobradas."],["pavehi1hr","What is Creutzfeldt-Jakob disease?","Rapidly progressive dementia with myoclonus (startle myoclonus), periodic sharp waves on EEG, 14-3-3 protein in CSF, spongiform cortex.","Demência rápida com mioclonias."],["122mgmok6","What is variant CJD?","Acquired from bovine spongiform encephalopathy (mad cow disease) in younger patients, with psychiatric symptoms.","Doença da vaca louca."],["w5guhf1vv","What is kuru?","Prion disease from cannibalism (Papua New Guinea).","Prion por canibalismo."],["jtp0b3hap","What is fatal familial insomnia?","Inherited prion disease with severe progressive insomnia and dysautonomia.","Insônia fatal familiar."],["nd5tob27w","How is the hepatitis A vaccine classified?","Inactivated (killed) vaccine.","Vacina inativada."],["ficy7m1kz","What are the features of hantavirus pulmonary syndrome?","Fever, myalgias, then rapid respiratory failure with noncardiogenic pulmonary edema and thrombocytopenia.","Edema pulmonar rápido."],["1bs9r47ef","What is the presentation of chikungunya vs dengue?","Chikungunya: prominent polyarthritis; dengue: severe myalgias, retro-orbital pain, thrombocytopenia, hemorrhage.","Chikungunya dá artrite; dengue dá plaquetopenia."],["t0ui0g15m","Which virus causes acute flaccid myelitis in children?","Enterovirus D68.","Enterovírus D68."],["18wepgm66","Which RNA virus causes infection mostly via respiratory route and is prevented by MMR?","Measles, mumps, rubella.","Sarampo, caxumba e rubéola."],["h0v64r16h","Which RNA virus causes croup and is the most common cause of laryngotracheobronchitis?","Parainfluenza type 1.","Parainfluenza tipo 1."],["vjwow81nz","What virus causes pneumonia and bronchiolitis in older adults and infants (besides RSV)?","Human metapneumovirus.","Metapneumovírus."],["g9kvy510r","What causes COVID-19 loss of taste and smell?","SARS-CoV-2 infection of olfactory support cells.","Infecção das células de suporte olfatório."],["1y783cdbv","How is rabies diagnosed post-mortem in animals?","Negri bodies and direct fluorescent antibody testing of brain tissue.","Corpúsculos de Negri no cérebro."],["mpfn23191","What is the treatment of HIV-associated Kaposi sarcoma?","Antiretroviral therapy; chemotherapy (liposomal doxorubicin) if extensive.","TARV e quimioterapia."],["1a34kdl18","What are the early symptoms of rabies at the wound site?","Paresthesias or pain at the bite site.","Formigamento no local da mordida."]]}];
